  function refuseWorkspace(){const active=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);return `<div id="refuseWorkspace" class="refuse-workspace"><div class="notice refuse-boundary"><b>Advisory boundary:</b> This Municipal Refuse Storage Pre-check uses a selected versioned source and human-entered assumptions. No municipal approval, collection service confirmation, legal certification or professional signoff is represented by a calculation.</div><section class="panel panel-pad refuse-source-panel"><div class="trust-card-head"><div><h2>Municipal refuse rule governance</h2><p>Rates, bins, collection intervals and area allowances remain source controlled and checksum protected.</p></div><button id="refuseSeedButton" class="btn ghost" type="button">Install review-required seed</button></div><div id="refuseSourceList" class="trust-list"><div class="notice">Loading refuse rule sources…</div></div><form id="refuseSourceForm" class="scaffold-grid"><label>New version<input class="form-input" name="version" required maxlength="100" value="municipal-reviewed-2026-1"></label><label>Effective date<input class="form-input" type="date" name="effectiveDate" required></label><label class="trust-wide">Exact official source reference<input class="form-input" name="sourceReference" required maxlength="500" placeholder="Municipality, document title, publication date and retrieval date"></label><label class="trust-wide">Versioned refuse rule JSON<textarea class="form-textarea compliance-rules-json" name="rulesJson" required></textarea></label><div class="trust-actions trust-wide"><button class="btn dark" type="submit">Create review candidate</button><span id="refuseSourceMessage" role="status"></span></div></form></section><form id="refuseCalculatorForm" class="panel panel-pad compliance-card"><div class="trust-card-head"><div><h2>Refuse capacity and storage area</h2><p>${escapeHtml(active?.name||'Standalone refuse study')} · explicit inputs, facilities and calculation trace.</p></div><span class="status amber">Source bound</span></div><div class="scaffold-grid">${complianceProjectFields()}<label>Occupancy / use<select class="form-select" name="occupancyUse" required></select></label><label>Quantity<input class="form-input" type="number" name="quantity" min="0.01" step="0.01" value="12" required></label><label>Collection interval (days)<input class="form-input" type="number" name="collectionIntervalDays" min="1" max="7" value="7" required></label><label>Contingency (%)<input class="form-input" type="number" name="contingencyPercent" min="0" max="100" step="0.01" value="10" required></label><label>Bin type<select class="form-select" name="binType" required></select></label><label>Proposed storage area (m²)<input class="form-input" type="number" name="proposedStorageAreaM2" min="0.01" step="0.01" value="13" required></label><fieldset class="trust-wide proposal-terms"><legend>Facilities explicitly recorded</legend>${[['collectionVehicleAccess','Collection vehicle access'],['washdownWater','Wash-down water point'],['drainage','Compliant drainage arrangement'],['ventilation','Ventilation provision'],['wasteSeparation','Waste-separation provision']].map(([name,label])=>`<label><input type="checkbox" name="${name}" checked> ${label}</label>`).join('')}</fieldset><label class="trust-wide">Assumptions and service confirmation gaps<textarea class="form-textarea" name="assumptions" required maxlength="1000">Municipal collection frequency, bin acceptance and vehicle access require confirmation.</textarea></label><label class="trust-wide">Rule source<select class="form-select" name="ruleVersionId" required><option value="">Install or select a source</option></select></label><label>Assignment<select class="form-select" name="assignment"><option value="none">Standalone / unassigned</option>${active?'<option value="internal_project" selected>Current Architex project</option>':''}</select></label><label class="trust-check"><input type="checkbox" name="issueImmediately"> Issue verified evidence</label><label>Professional role<input class="form-input" name="professionalRole" readonly value="architect"></label><label class="trust-check trust-wide"><input type="checkbox" name="professionalConfirmed"> I reviewed the exact source, inputs, findings and accept professional responsibility.</label><label class="trust-wide">Responsibility statement<input class="form-input" name="responsibilityStatement" maxlength="1000" value="I reviewed the selected municipal source, project inputs, calculated capacity and storage-area findings."></label><label class="trust-wide">Professional issue reason<input class="form-input" name="issueReason" maxlength="500" value="Responsible architect reviewed the exact source version, inputs and findings."></label></div><div class="trust-actions"><button class="btn dark" type="submit">Run refuse pre-check</button><span id="refuseCalculatorMessage" role="status"></span></div><div id="refuseCalculatorResult"></div></form><section class="panel panel-pad"><div class="trust-card-head"><div><h2>Refuse evidence history</h2><p>Advisory runs and immutable issued snapshots persist in MariaDB with integrity-checked exports.</p></div><button id="refuseRefreshButton" class="btn ghost" type="button">Refresh</button></div><div id="refuseRunHistory" class="trust-list"><div class="notice">Loading refuse runs…</div></div></section></div>`;}
  async function hydrateRefuseWorkspace(){const root=document.getElementById('refuseWorkspace');if(!root)return;try{const[rules,runs]=await Promise.all([api.get('/compliance-rule-versions'),api.get('/toolbox/runs?limit=100')]);refuseSources=rules.filter(x=>x.ruleKey==='municipal_refuse');renderRefuseSources();renderRefuseRuns(runs);bindRefuseWorkspace();}catch(error){document.getElementById('refuseSourceList').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function renderRefuseSources(){const list=document.getElementById('refuseSourceList'),form=document.getElementById('refuseSourceForm'),calculator=document.getElementById('refuseCalculatorForm'),governor=['owner','admin'].includes(window.__ARCHITEX_SHELL_STATE__?.session.memberships?.[0]?.role);list.innerHTML=refuseSources.length?refuseSources.map(source=>`<article class="trust-row"><div><b>${escapeHtml(source.version)}</b><span>${escapeHtml(source.sourceReference)}</span><small>${escapeHtml(source.status.replaceAll('_',' '))} · SHA-256 ${escapeHtml(source.payloadSha256.slice(0,16))}…</small></div><div class="trust-row-actions"><span class="status ${source.issueEligible?'green':'amber'}">${source.issueEligible?'issue eligible':'review required'}</span>${governor&&source.status==='review_required'&&!source.version.startsWith('implementation-seed')?`<button class="btn ghost refuse-verify-button" type="button" data-source-id="${escapeHtml(source.id)}">Verify</button>`:''}</div></article>`).join(''):'<div class="notice">No refuse source exists. An owner or admin can install the explicitly unverified implementation seed.</div>';const preferred=refuseSources.find(x=>x.status==='verified')||refuseSources.find(x=>x.status==='review_required');calculator.elements.ruleVersionId.innerHTML='<option value="">Select refuse source</option>'+refuseSources.filter(x=>x.status!=='withdrawn').map(source=>`<option value="${escapeHtml(source.id)}" ${source.id===preferred?.id?'selected':''}>${escapeHtml(source.version)} · ${escapeHtml(source.status.replaceAll('_',' '))}</option>`).join('');form.hidden=!governor;document.getElementById('refuseSeedButton').hidden=!governor;if(preferred)form.elements.rulesJson.value=JSON.stringify(preferred.rules,null,2);if(!form.elements.effectiveDate.value)form.elements.effectiveDate.value=new Date().toISOString().slice(0,10);calculator.elements.ruleVersionId.onchange=syncRefuseSourceControls;document.querySelectorAll('.refuse-verify-button').forEach(button=>button.addEventListener('click',()=>verifyRefuseSource(button.dataset.sourceId)));syncRefuseSourceControls();}
  function syncRefuseSourceControls(){const form=document.getElementById('refuseCalculatorForm'),source=refuseSources.find(x=>x.id===form.elements.ruleVersionId.value),rules=source?.rules||{},use=form.elements.occupancyUse.value,bin=form.elements.binType.value;form.elements.occupancyUse.innerHTML=Object.entries(rules.generationRates||{}).map(([id,item])=>`<option value="${escapeHtml(id)}" ${id===use?'selected':''}>${escapeHtml(item.label)} · ${escapeHtml(item.litresPerUnitPerDay)} L/${escapeHtml(item.unit)}/day</option>`).join('');form.elements.binType.innerHTML=Object.entries(rules.bins||{}).map(([id,item])=>`<option value="${escapeHtml(id)}" ${id===bin?'selected':''}>${escapeHtml(item.label)} · ${escapeHtml(item.capacityLitres)} L</option>`).join('');form.elements.collectionIntervalDays.value=rules.defaultCollectionIntervalDays??form.elements.collectionIntervalDays.value;form.elements.contingencyPercent.value=rules.defaultContingencyPercent??form.elements.contingencyPercent.value;form.elements.issueImmediately.disabled=!source?.issueEligible;if(!source?.issueEligible)form.elements.issueImmediately.checked=false;}
  function bindRefuseWorkspace(){const source=document.getElementById('refuseSourceForm'),calculator=document.getElementById('refuseCalculatorForm');calculator.elements.professionalRole.value='architect_or_civil_engineer';if(!source.dataset.bound){source.dataset.bound='1';source.addEventListener('submit',createRefuseSource);}if(!calculator.dataset.bound){calculator.dataset.bound='1';calculator.addEventListener('submit',runRefuseCalculator);}document.getElementById('refuseSeedButton').onclick=installRefuseSeed;document.getElementById('refuseRefreshButton').onclick=hydrateRefuseWorkspace;}
  async function installRefuseSeed(){try{await api.post('/compliance-rule-versions/seed',{ruleKey:'municipal_refuse'});showToast('Unverified refuse implementation seed installed.');await hydrateRefuseWorkspace();}catch(error){showToast(error.message);}}
  async function createRefuseSource(event){event.preventDefault();const form=event.currentTarget,message=document.getElementById('refuseSourceMessage');message.textContent='Creating source version…';try{await api.post('/compliance-rule-versions',{ruleKey:'municipal_refuse',version:form.elements.version.value,sourceReference:form.elements.sourceReference.value,effectiveDate:form.elements.effectiveDate.value,rules:JSON.parse(form.elements.rulesJson.value)});message.textContent='Review candidate saved; separate human verification is required.';await hydrateRefuseWorkspace();}catch(error){message.textContent=error.message;}}
  async function verifyRefuseSource(id){if(!confirm('Verify this exact refuse rule payload for professional issue? Existing reports remain immutable.'))return;const reason=prompt('Record the exact official-source review reason:');if(!reason?.trim())return;try{await api.post(`/compliance-rule-versions/${encodeURIComponent(id)}/verify`,{humanConfirmed:true,verificationReason:reason.trim()});showToast('Refuse source verified and audited.');await hydrateRefuseWorkspace();}catch(error){showToast(error.message);}}
  async function runRefuseCalculator(event){event.preventDefault();const form=event.currentTarget,message=document.getElementById('refuseCalculatorMessage'),source=refuseSources.find(x=>x.id===form.elements.ruleVersionId.value);message.textContent='Calculating and preserving evidence…';try{if(!source)throw new Error('Select a versioned refuse source.');const input={ruleVersionId:source.id,project:complianceProject(form),occupancyUse:form.elements.occupancyUse.value,quantity:Number(form.elements.quantity.value),collectionIntervalDays:Number(form.elements.collectionIntervalDays.value),contingencyPercent:Number(form.elements.contingencyPercent.value),binType:form.elements.binType.value,proposedStorageAreaM2:Number(form.elements.proposedStorageAreaM2.value),facilities:{collectionVehicleAccess:form.elements.collectionVehicleAccess.checked,washdownWater:form.elements.washdownWater.checked,drainage:form.elements.drainage.checked,ventilation:form.elements.ventilation.checked,wasteSeparation:form.elements.wasteSeparation.checked},assumptions:form.elements.assumptions.value,professionalConfirmation:{confirmed:form.elements.professionalConfirmed.checked,role:form.elements.professionalRole.value,responsibilityStatement:form.elements.responsibilityStatement.value}};const run=await api.post('/toolbox/runs',{toolId:'refuse_area_calculator',input,assignment:complianceAssignment(form),issueImmediately:form.elements.issueImmediately.checked,issueReason:form.elements.issueReason.value});renderComplianceResult(document.getElementById('refuseCalculatorResult'),run);message.textContent=run.status==='issued'?'Verified refuse evidence issued and locked.':'Advisory refuse run saved; formal issue remains unavailable for this source.';await hydrateRefuseWorkspace();}catch(error){message.textContent=error.message;}}
