  async function createDrawingIntelligenceCandidate(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),message=document.getElementById('drawingIntelligenceMessage');message.textContent='Recording human-entered candidate…';try{await api.post('/drawing-intelligence-candidates',{revisionId:v.get('revisionId'),provenance:'human_entered',providerName:null,providerReference:null,confidence:null,candidate:{classification:v.get('classification'),detectedDiscipline:v.get('detectedDiscipline'),titleBlock:{drawingNumber:v.get('drawingNumber'),title:v.get('title'),scale:v.get('scale'),date:v.get('date'),author:v.get('author')},revision:v.get('revision'),issuePurpose:v.get('issuePurpose'),findings:[v.get('findings')],suggestedNextAction:v.get('suggestedNextAction')}});message.textContent='Human-entered candidate saved. No controlled metadata was applied.';await hydrateDocumentControl();}catch(error){message.textContent=error.message;}}
