  async function createControlledDocument(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),message=document.getElementById('documentCreateMessage'),type=v.get('documentType'),body={projectId:window.__ARCHITEX_SHELL_STATE__.selectedProjectId,title:v.get('title'),documentType:type,discipline:v.get('discipline'),phase:v.get('phase'),issuePurpose:v.get('issuePurpose'),revisionCode:v.get('revisionCode'),notes:v.get('notes')};if(type==='drawing')body.drawing={drawingNumber:v.get('drawingNumber'),sheetType:v.get('sheetType'),scale:v.get('scale')};message.textContent='Creating controlled draft…';try{const created=await api.post('/documents',body);activeDocumentRevisionId=created.id;form.reset();message.textContent='Controlled draft created and audited.';await hydrateDocumentControl();}catch(error){message.textContent=error.message;}}
