  window.submitDocumentReview=async function(){const reason=prompt('Reason for professional review?','Drawing metadata and linked evidence are ready for professional review.');if(!reason?.trim())return;try{await api.post(`/documents/${encodeURIComponent(activeDocumentRevisionId)}/submit-review`,{reason:reason.trim()});await hydrateDocumentControl();}catch(error){showToast(error.message);}};
  window.approveControlledDocument=async function(){const reason=prompt('Why is this exact revision approved?','I personally reviewed the exact revision metadata and linked evidence.');if(!reason?.trim()||!confirm('Approve this exact controlled revision?'))return;try{await api.post(`/documents/${encodeURIComponent(activeDocumentRevisionId)}/approve`,{humanConfirmed:true,reason:reason.trim()});await hydrateDocumentControl();}catch(error){showToast(error.message);}};
