  window.reviseControlledDocument=async function(){const form=document.getElementById('documentRevisionForm'),item=documentRevisions.find(x=>x.id===activeDocumentRevisionId),v=new FormData(form),reason=v.get('revisionReason');if(!reason?.trim()||!confirm('Supersede this issued revision and create a linked draft?'))return;const body={revisionCode:v.get('revisionCode'),reason,notes:v.get('notes'),issuePurpose:'for_review'};if(item.drawing)body.drawing={drawingNumber:v.get('drawingNumber'),sheetType:v.get('sheetType'),scale:v.get('scale')};try{const revision=await api.post(`/documents/${encodeURIComponent(item.id)}/revisions`,body);activeDocumentRevisionId=revision.id;await hydrateDocumentControl();showToast('Linked revision created; the prior issue remains visible as superseded.');}catch(error){showToast(error.message);}};
