  async function hydrateCommunicationWorkspace(){const centre=document.getElementById('projectMessageCentre');if(!centre)return;const projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId,phase=document.getElementById('communicationPhase')?.value;if(!projectId)return;try{const[threads,assistant,actions,team]=await Promise.all([api.get(`/communication-threads?projectId=${encodeURIComponent(projectId)}`),api.get(`/projects/${encodeURIComponent(projectId)}/communication-assistant?phase=${encodeURIComponent(phase)}`),api.get(`/projects/${encodeURIComponent(projectId)}/communication-actions`),api.get(`/projects/${encodeURIComponent(projectId)}/team`)]);communicationTeamUserIds=[...new Set(team.filter(item=>item.status==='active'&&item.communicationEligible===true).map(item=>item.userId).filter(Boolean))];const newThread=document.getElementById('communicationNewThread');if(newThread){newThread.textContent=communicationTeamUserIds.length?'New team thread':'New private thread';newThread.title=communicationTeamUserIds.length?`${communicationTeamUserIds.length} eligible organisation teammate${communicationTeamUserIds.length===1?'':'s'} will be included.`:'No active project teammate has organisation access; this thread will include only you.';}activeCommunicationThreadId=threads.some(item=>item.id===activeCommunicationThreadId)?activeCommunicationThreadId:threads[0]?.id||null;renderCommunicationThreads(threads);renderCommunicationAssistant(assistant);renderCommunicationActions(actions);if(activeCommunicationThreadId)await loadCommunicationMessages();else document.getElementById('communicationMessageList').innerHTML='<div class="notice">Create the first project conversation. It will be shared by the mobile applet and desktop centre.</div>';bindCommunicationWorkspace();applyPendingCommunicationContext();}catch(error){document.getElementById('communicationMessageList').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function bindCommunicationWorkspace(){const project=document.getElementById('communicationProjectSwitcher'),phase=document.getElementById('communicationPhase'),composer=document.getElementById('communicationComposer'),search=document.getElementById('communicationSearch'),conversion=document.getElementById('communicationConversionForm');if(!project?.dataset.bound){project.dataset.bound='1';project.addEventListener('change',()=>selectCommunicationProject(project.value));phase.addEventListener('change',hydrateCommunicationWorkspace);composer.addEventListener('submit',sendProjectCommunication);search.addEventListener('submit',event=>{event.preventDefault();loadCommunicationMessages(new FormData(event.currentTarget).get('search'));});conversion.addEventListener('submit',convertProjectCommunication);}}
  function renderCommunicationThreads(threads){const list=document.getElementById('communicationThreadList');list.innerHTML=threads.length?threads.map(item=>`<button class="communication-thread ${item.id===activeCommunicationThreadId?'active':''}" onclick="selectCommunicationThread('${escapeHtml(item.id)}')"><b>${escapeHtml(item.title)}</b><span>${escapeHtml(item.channel.replaceAll('_',' '))} · ${item.participants.length} participant${item.participants.length===1?'':'s'}</span><small>${escapeHtml(item.phase.replaceAll('_',' '))} · ${escapeHtml(item.visibility.replaceAll('_',' '))}</small></button>`).join(''):'<div class="notice">No project conversations yet.</div>';}
  async function loadCommunicationMessages(search=''){if(!activeCommunicationThreadId)return;const query=new URLSearchParams();if(search)query.set('search',String(search));const messages=await api.get(`/communication-threads/${encodeURIComponent(activeCommunicationThreadId)}/messages${query.size?'?'+query:''}`);const list=document.getElementById('communicationMessageList');list.innerHTML=messages.length?messages.map(message=>`<article class="communication-message ${message.senderUserId===window.__ARCHITEX_SHELL_STATE__?.session.userId?'own':''}" data-message-id="${escapeHtml(message.id)}" data-message-body="${escapeHtml(message.body)}" onclick="selectCommunicationMessage(this.dataset.messageId,this.dataset.messageBody)"><b>${escapeHtml(message.senderEmail)}</b><p>${escapeHtml(message.body)}</p><small>${escapeHtml(message.phase.replaceAll('_',' '))}${message.captureType?' · '+escapeHtml(message.captureType.replaceAll('_',' ')):''}${message.attachmentFileId?' · attachment':''} · ${escapeHtml(message.structuredStatus)}</small></article>`).join(''):'<div class="notice">No sent messages match this view.</div>';if(messages.length)await api.post(`/communication-threads/${encodeURIComponent(activeCommunicationThreadId)}/read`,{messageId:messages.at(-1).id});}
  function renderCommunicationAssistant(assistant){const capture=document.getElementById('communicationCaptureType'),prompts=document.getElementById('communicationPromptList'),files=document.getElementById('communicationFileFocus'),pulse=document.getElementById('communicationPulse');capture.innerHTML=assistant.captureTypes.map(item=>`<option value="${escapeHtml(item)}">${escapeHtml(item.replaceAll('_',' '))}</option>`).join('');prompts.innerHTML=assistant.suggestedPrompts.map(item=>`<button type="button" onclick="useCommunicationPrompt('${escapeHtml(item)}')">${escapeHtml(item)}</button>`).join('');files.innerHTML=assistant.fileFocus.map(item=>`<span>${escapeHtml(item)}</span>`).join('');pulse.innerHTML=`<b>${assistant.projectPulse.openActions}</b> open actions · <b>${assistant.projectPulse.overdueItems}</b> overdue · <b>${assistant.projectPulse.pendingApprovals}</b> approvals`;}
  function renderCommunicationActions(actions){const list=document.getElementById('communicationActionList');list.innerHTML=actions.length?actions.map(item=>`<article class="trust-row"><div><b>${escapeHtml(item.title)}</b><span>${escapeHtml(item.conversionType.replaceAll('_',' '))} · ${escapeHtml(item.status)}</span><small>${item.dueOn?'Due '+escapeHtml(item.dueOn):'No due date'}</small></div></article>`).join(''):'<div class="notice">No human-approved communication actions.</div>';}
  async function sendProjectCommunication(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),status=document.getElementById('communicationMessageStatus'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!activeCommunicationThreadId){status.textContent='Create or select a conversation first.';return;}if(v.get('humanConfirmed')!=='on'){status.textContent='Review and approve the exact message before sending.';return;}status.textContent='Preparing reviewed draft…';try{let attachmentFileId=null,file=form.elements.attachment.files[0];if(file){const body=new FormData();body.append('file',file);const response=await fetch(`/api/v1/projects/${encodeURIComponent(projectId)}/files`,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Organisation-Id':api.organisationId,'X-CSRF-Token':api.csrfToken},body});const payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Attachment upload failed.');attachmentFileId=payload.data.id;}const sourceType=v.get('sourceObjectType'),sourceId=v.get('sourceObjectId'),draft=await api.post(`/communication-threads/${encodeURIComponent(activeCommunicationThreadId)}/drafts`,{body:v.get('body'),phase:document.getElementById('communicationPhase').value,captureType:v.get('captureType'),messageKind:v.get('messageKind'),attachmentFileId,context:{moduleKey:pendingCommunicationContext?.moduleKey||'messages',sourceObjectType:sourceType,sourceObjectId:sourceId,title:v.get('contextTitle'),status:pendingCommunicationContext?.status||'active',summary:pendingCommunicationContext?.summary||`Project communication linked to ${sourceType} ${sourceId}.`,persistencePolicy:v.get('persistencePolicy'),auditPolicy:['site_instruction','variation','payment_certificate'].includes(sourceType)?'approval_required':sourceType==='project_dashboard'?'none':'record_summary',linkedFileIds:attachmentFileId?[attachmentFileId]:[]}});await api.post(`/communications/messages/${encodeURIComponent(draft.id)}/send`,{humanConfirmed:true});pendingCommunicationContext=null;form.reset();status.textContent='Approved message sent to the shared project record.';await hydrateCommunicationWorkspace();}catch(error){status.textContent=error.message;}}
  async function convertProjectCommunication(event){event.preventDefault();const v=new FormData(event.currentTarget),status=document.getElementById('communicationConversionStatus');if(!selectedCommunicationMessageId){status.textContent='Select a sent message first.';return;}if(v.get('humanConfirmed')!=='on'){status.textContent='Confirm the exact conversion and destination first.';return;}try{await api.post(`/communications/messages/${encodeURIComponent(selectedCommunicationMessageId)}/convert`,{conversionType:v.get('conversionType'),title:v.get('title'),dueOn:v.get('dueOn')||null,humanConfirmed:true});status.textContent='Controlled work item created and routed to the inbox.';await hydrateCommunicationWorkspace();}catch(error){status.textContent=error.message;}}
  window.createProjectThread=async function(){const projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId,active=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===projectId),title=prompt('Conversation title?',`${active?.name||'Project'} team`);if(!title?.trim())return;try{const thread=await api.post('/communication-threads',{projectId,title:title.trim(),phase:document.getElementById('communicationPhase').value,channel:'project_group',visibility:'project_team',participantUserIds:communicationTeamUserIds});activeCommunicationThreadId=thread.id;await hydrateCommunicationWorkspace();}catch(error){showToast(error.message);}};
