    voltage_drop_calculator:{label:'Voltage drop',role:'electrical_engineer',fields:[['phase','Circuit phase','three_phase','select',[['single_phase','Single phase'],['three_phase','Three phase']]],['nominalVoltageV','Nominal voltage (V)',400],['currentA','Design current (A)',100],['routeLengthM','One-way route length (m)',50],['resistanceOhmPerKm','Resistance (Ω/km)',.5],['reactanceOhmPerKm','Reactance (Ω/km)',.08],['powerFactor','Power factor',.9],['maximumDropPercent','User maximum drop (%)',5]]},
