    tender_rate_build_up_calculator:{label:'Tender rate build-up',role:'quantity_surveyor',fields:[['quantity','Measured quantity',10],['unit','Measurement unit','m2','text'],['materialsPerUnit','Materials / unit',100],['labourPerUnit','Labour / unit',50],['plantPerUnit','Plant / unit',20],['subcontractPerUnit','Subcontract / unit',0],['overheadsPercent','Overheads (%)',10],['profitPercent','Profit (%)',10],['riskPercent','Risk (%)',5]]},
