  const engineeringToolIds=Object.keys(engineeringToolDefinitions);let engineeringActiveTool='beam_quick_check',engineeringRuns=[],engineeringRevisionRunId=null;
  function engineeringFields(toolId){const tool=engineeringToolDefinitions[toolId];return tool.fields.map(([name,label,value,type='number',options])=>type==='select'?`<label>${escapeHtml(label)}<select class="form-select" name="${name}" required>${options.map(([id,text])=>`<option value="${id}" ${id===value?'selected':''}>${escapeHtml(text)}</option>`).join('')}</select></label>`:`<label>${escapeHtml(label)}<input class="form-input" name="${name}" type="${type}" ${type==='number'?'step="any"':''} value="${escapeHtml(value)}" required></label>`).join('');}
  function engineeringEvidenceWorkspace(){const projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;return `<div id="engineeringEvidenceWorkspace" class="engineering-evidence-workspace"><div class="notice engineering-boundary"><b>Controlled working evidence:</b> Inputs, formula version, assumptions and results are persisted exactly. Issue requires current independently reviewed authority matching the responsible role and creates an immutable project record; it does not certify design adequacy or compliance.</div><form id="engineeringRunForm" class="panel panel-pad engineering-run-card"><div class="trust-card-head"><div><h2>Controlled calculation record</h2><p>Use the canonical calculator above for exploration, then reproduce the reviewed values here for governed persistence.</p></div><span class="status amber">Professional review</span></div><div class="scaffold-grid"><label class="trust-wide">Calculator<select class="form-select" name="toolId" onchange="setEngineeringCalculator(this.value)">${engineeringToolIds.map(id=>`<option value="${id}" ${id===engineeringActiveTool?'selected':''}>${escapeHtml(engineeringToolDefinitions[id].label)}</option>`).join('')}</select></label><div id="engineeringInputFields" class="engineering-input-fields trust-wide">${engineeringFields(engineeringActiveTool)}</div><label>Assignment<select class="form-select" name="assignment"><option value="none">Standalone / unassigned</option>${projectId?'<option value="internal_project" selected>Current Architex project</option>':''}</select></label><label>Responsible role<input id="engineeringProfessionalRole" class="form-input" name="professionalRole" readonly value="${escapeHtml(engineeringToolDefinitions[engineeringActiveTool].role)}"></label><label class="trust-check trust-wide"><input type="checkbox" name="issueImmediately"> Issue immutable calculation evidence</label><fieldset class="proposal-terms trust-wide"><legend>Professional responsibility confirmation</legend><label class="trust-check"><input type="checkbox" name="professionalConfirmed"> I am acting in the recorded responsible role and reviewed the exact inputs, assumptions, formula, outputs, risks and limitations.</label><label>Responsibility statement<textarea class="form-textarea" name="responsibilityStatement" maxlength="1000">I reviewed the exact inputs, assumptions, formula, result, risk flags and limitations for this controlled working record.</textarea></label></fieldset><label class="trust-wide">Issue / revision reason<input class="form-input" name="issueReason" maxlength="500" value="Responsible professional reviewed this exact coordination calculation and its stated limitations."></label></div><div class="trust-actions"><button class="btn dark" type="submit">Save calculation record</button><button class="btn ghost" type="button" onclick="cancelEngineeringRevision()" id="engineeringCancelRevision" hidden>Cancel revision</button><span id="engineeringRunMessage" role="status"></span></div><div id="engineeringRunResult"></div></form><section class="panel panel-pad engineering-history"><div class="trust-card-head"><div><h2>Engineering run history</h2><p>Completed working runs and immutable issued revisions stored in MariaDB.</p></div><button class="btn ghost" type="button" onclick="refreshEngineeringWorkspace()">Refresh</button></div><div id="engineeringRunHistory" class="trust-list"><div class="notice">Loading calculation records…</div></div></section></div>`;}
  window.setEngineeringCalculator=function(toolId){if(!engineeringToolDefinitions[toolId])return;engineeringActiveTool=toolId;const fields=document.getElementById('engineeringInputFields'),role=document.getElementById('engineeringProfessionalRole');if(fields)fields.innerHTML=engineeringFields(toolId);if(role)role.value=engineeringToolDefinitions[toolId].role;};
  function engineeringInput(toolId,values){const number=name=>Number(values.get(name)),plain=Object.fromEntries(engineeringToolDefinitions[toolId].fields.map(([name,,value,type])=>[name,type==='text'||type==='select'?String(values.get(name)):number(name)]));if(toolId==='concrete_quantity_calculator')return{elements:[{reference:plain.reference,lengthM:plain.lengthM,widthM:plain.widthM,depthM:plain.depthM,quantity:plain.quantity}],wastePercent:plain.wastePercent};if(toolId==='finishes_quantity_calculator')return plain.mode==='paint'?{mode:'paint',surfaceAreaM2:plain.surfaceAreaM2,coats:plain.coats,coverageM2PerLitre:plain.coverageM2PerLitre,wastePercent:plain.wastePercent}:{mode:'tile',surfaceAreaM2:plain.surfaceAreaM2,packCoverageM2:plain.packCoverageM2,wastePercent:plain.wastePercent};return plain;}
  function engineeringAssignment(form){const mode=form.elements.assignment.value,projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;return mode==='internal_project'&&projectId?{mode,projectId}:{mode:'none'};}
  async function submitEngineeringRun(event){event.preventDefault();const form=event.currentTarget,values=new FormData(form),toolId=String(values.get('toolId')),message=document.getElementById('engineeringRunMessage');message.textContent=engineeringRevisionRunId?'Issuing calculation revision…':'Saving controlled calculation…';try{let input=engineeringInput(toolId,values);const requiresIssue=engineeringRevisionRunId!==null||values.get('issueImmediately')==='on';if(requiresIssue)input.professionalConfirmation={confirmed:values.get('professionalConfirmed')==='on',role:String(values.get('professionalRole')),responsibilityStatement:String(values.get('responsibilityStatement')||'')};const assignment=engineeringAssignment(form),reason=String(values.get('issueReason')||'');const run=engineeringRevisionRunId?await api.post(`/toolbox/runs/${encodeURIComponent(engineeringRevisionRunId)}/revisions`,{input,assignment,reason}):await api.post('/toolbox/runs',{toolId,input,assignment,issueImmediately:requiresIssue,issueReason:reason});engineeringRevisionRunId=null;document.getElementById('engineeringCancelRevision').hidden=true;renderEngineeringRunResult(run);message.textContent=run.status==='issued'?'Issued and locked with immutable SHA-256 evidence.':'Controlled working calculation saved.';await hydrateEngineeringWorkspace();}catch(error){message.textContent=error.message;}}
  function renderEngineeringRunResult(run){const target=document.getElementById('engineeringRunResult');if(!target)return;const results=Object.entries(run.output?.results||{}).map(([key,value])=>`<div><b>${escapeHtml(key.replaceAll('_',' '))}</b><span>${escapeHtml(typeof value==='object'?JSON.stringify(value):value)}</span></div>`).join('');target.innerHTML=`<div class="engineering-result"><div class="trust-card-head"><div><h3>${escapeHtml(run.toolName)}</h3><p>Formula ${escapeHtml(run.output.formulaVersion)} · ${escapeHtml(run.output.calculationClass.replaceAll('_',' '))}</p></div><span class="status ${run.status==='issued'?'green':'amber'}">${escapeHtml(run.status)}</span></div><div class="engineering-result-grid">${results}</div><p>${escapeHtml(run.output.limitations)}</p>${run.auditHash?`<small>SHA-256 ${escapeHtml(run.auditHash)}</small>`:''}</div>`;}
  function renderEngineeringRuns(){const list=document.getElementById('engineeringRunHistory');if(!list)return;list.innerHTML=engineeringRuns.length?engineeringRuns.map(run=>`<article class="trust-row"><div><b>${escapeHtml(engineeringToolDefinitions[run.toolId]?.label||run.toolId)} · ${escapeHtml(run.status)}</b><span>Formula ${escapeHtml(run.output?.formulaVersion||'failed')} · ${escapeHtml(run.assignment.mode.replaceAll('_',' '))}</span><small>${escapeHtml(run.createdAt)}${run.auditHash?' · SHA-256 '+escapeHtml(run.auditHash):''}</small></div><div class="trust-row-actions"><button class="btn ghost" type="button" onclick="loadEngineeringExports('${escapeHtml(run.id)}')">Evidence exports</button>${run.status==='issued'?`<button class="btn ghost" type="button" onclick="prepareEngineeringRevision('${escapeHtml(run.id)}')">Create revision</button>`:''}</div></article>`).join(''):'<div class="notice">No engineering calculation records yet.</div>';}
  async function hydrateEngineeringWorkspace(){if(!document.getElementById('engineeringEvidenceWorkspace'))return;try{const runs=await api.get('/toolbox/runs?limit=100');engineeringRuns=runs.filter(run=>engineeringToolIds.includes(run.toolId));renderEngineeringRuns();const form=document.getElementById('engineeringRunForm');if(form&&!form.dataset.bound){form.dataset.bound='1';form.addEventListener('submit',submitEngineeringRun);}}catch(error){const list=document.getElementById('engineeringRunHistory');if(list)list.innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  window.refreshEngineeringWorkspace=hydrateEngineeringWorkspace;
  window.loadEngineeringExports=async function(runId){try{const exports=await api.get(`/toolbox/runs/${encodeURIComponent(runId)}/exports`),list=document.getElementById('engineeringRunHistory');list.insertAdjacentHTML('afterbegin',`<div class="fee-export-row">${exports.map(file=>`<button class="btn ghost" type="button" onclick="downloadEngineeringExport('${escapeHtml(file.id)}')">Download ${escapeHtml(file.format.toUpperCase())}</button>`).join('')}</div>`);}catch(error){showToast(error.message);}};
  window.downloadEngineeringExport=async function(exportId){try{const response=await fetch(`${api.base}/toolbox/exports/${encodeURIComponent(exportId)}`,{headers:{Accept:'application/octet-stream','X-Organisation-Id':api.organisationId},credentials:'same-origin'});if(!response.ok)throw new Error('Evidence export failed.');const blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/),link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=match?.[1]||`engineering-evidence-${exportId}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){showToast(error.message);}};
  window.prepareEngineeringRevision=function(runId){const run=engineeringRuns.find(item=>item.id===runId);if(!run||run.status!=='issued')return;engineeringRevisionRunId=runId;engineeringActiveTool=run.toolId;const select=document.querySelector('#engineeringRunForm [name=toolId]');if(select){select.value=run.toolId;setEngineeringCalculator(run.toolId);}const form=document.getElementById('engineeringRunForm');if(!form)return;const values=run.toolId==='concrete_quantity_calculator'?{...run.input,...(run.input.elements?.[0]||{})}:run.input;Object.entries(values).forEach(([name,value])=>{const field=form.elements.namedItem(name);if(field&&typeof value!=='object')field.value=String(value);});form.elements.assignment.value=run.assignment.mode==='internal_project'?'internal_project':'none';form.elements.issueImmediately.checked=true;form.elements.professionalConfirmed.checked=run.input.professionalConfirmation?.confirmed===true;form.elements.professionalRole.value=engineeringToolDefinitions[run.toolId].role;form.elements.responsibilityStatement.value=run.input.professionalConfirmation?.responsibilityStatement||'';document.getElementById('engineeringCancelRevision').hidden=false;document.getElementById('engineeringRunMessage').textContent='Revision mode: update values and provide a new reason; the issued baseline remains immutable.';form.scrollIntoView({behavior:'smooth',block:'start'});};
  window.cancelEngineeringRevision=function(){engineeringRevisionRunId=null;const button=document.getElementById('engineeringCancelRevision');if(button)button.hidden=true;const message=document.getElementById('engineeringRunMessage');if(message)message.textContent='Revision cancelled; the issued record is unchanged.';};
