  function planningEvidenceWorkspace(){const active=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId),today=new Date().toISOString().slice(0,10);return `<div id="planningEvidenceWorkspace" class="planning-evidence-workspace"><div class="notice planning-boundary"><b>Authority boundary:</b> Architex records the evidence and human-confirmed external handoff. It does not lodge, pay, notify, accept, decide or approve on behalf of a municipality.</div><form id="planningCreateForm" class="panel panel-pad planning-create"><div class="trust-card-head"><div><h2>New planning application</h2><p>${state.mode==='project'?escapeHtml(active?.name||'Select a project'):'Standalone portfolio record'}</p></div><span class="status amber">Source required</span></div><div class="scaffold-grid"><label>Application number<input class="form-input" name="applicationNumber" required maxlength="80" value="APP-${new Date().getFullYear()}-"></label><label>Type<select class="form-select" name="applicationType">${[['rezoning','Rezoning'],['consent_use','Consent use'],['subdivision','Subdivision'],['consolidation','Consolidation'],['removal_restrictions','Removal of restrictions'],['township_establishment','Township establishment'],['site_development_plan','Site development plan'],['other','Other']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label class="trust-wide">Title<input class="form-input" name="title" required maxlength="220"></label><label>Municipality<input class="form-input" name="municipality" required maxlength="220" value="${escapeHtml(active?.municipality||'')}"></label><label>Property reference<input class="form-input" name="propertyReference" required maxlength="220" value="${escapeHtml(active?.propertyReference||active?.location||'')}"></label><label>Responsible role<select class="form-select" name="responsibleRole"><option value="architect">Architect</option><option value="town_planner">Town planner</option></select></label><label>Source retrieved<input class="form-input" type="date" name="retrievedAt" required value="${today}"></label><label class="trust-wide">Official source title<input class="form-input" name="sourceTitle" required maxlength="220"></label><label class="trust-wide">Official source URL<input class="form-input" type="url" name="sourceUrl" required maxlength="1000" placeholder="https://municipality.example/official-source"></label></div><div class="trust-actions"><button class="btn dark" type="submit">Create governed application</button><span id="planningCreateMessage" role="status"></span></div></form><section class="panel panel-pad planning-register"><div class="trust-card-head"><div><h2>Application register</h2><p>Project and portfolio records persisted in MariaDB.</p></div><button class="btn ghost" type="button" onclick="refreshPlanningWorkspace()">Refresh</button></div><div id="planningApplicationList" class="trust-list"><div class="notice">Loading applications…</div></div></section><section id="planningActiveApplication" class="planning-active"><div class="notice">Create or select an application to manage its evidence registers.</div></section></div>`;}
  function planningApplicationEndpoint(){const projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;return state.mode==='project'&&projectId?`/projects/${encodeURIComponent(projectId)}/planning-applications`:'/planning-applications';}
  async function hydratePlanningWorkspace(){if(!document.getElementById('planningEvidenceWorkspace'))return;try{planningApplications=await api.get(planningApplicationEndpoint());if(planningActiveId&&!planningApplications.some(x=>x.id===planningActiveId))planningActiveId=null;if(!planningActiveId)planningActiveId=planningApplications[0]?.id||null;renderPlanningApplications();renderPlanningActive();bindPlanningCreate();}catch(error){document.getElementById('planningApplicationList').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  window.refreshPlanningWorkspace=hydratePlanningWorkspace;
  function bindPlanningCreate(){const form=document.getElementById('planningCreateForm');if(!form||form.dataset.bound)return;form.dataset.bound='1';form.addEventListener('submit',async event=>{event.preventDefault();const f=event.currentTarget,v=new FormData(f),message=document.getElementById('planningCreateMessage');message.textContent='Creating…';try{const created=await api.post(planningApplicationEndpoint(),{applicationNumber:v.get('applicationNumber'),applicationType:v.get('applicationType'),title:v.get('title'),municipality:v.get('municipality'),propertyReference:v.get('propertyReference'),responsibleRole:v.get('responsibleRole'),sourceBasis:[{title:v.get('sourceTitle'),url:v.get('sourceUrl'),retrievedAt:v.get('retrievedAt')}]});planningActiveId=created.id;message.textContent='Application created and audited.';await hydratePlanningWorkspace();}catch(error){message.textContent=error.message;}});}
  function renderPlanningApplications(){const list=document.getElementById('planningApplicationList');if(!list)return;list.innerHTML=planningApplications.length?planningApplications.map(app=>`<article class="trust-row ${app.id===planningActiveId?'planning-selected':''}"><div><b>${escapeHtml(app.applicationNumber)} · ${escapeHtml(app.title)}</b><span>${escapeHtml(app.applicationType.replaceAll('_',' '))} · ${escapeHtml(app.municipality)}</span><small>${escapeHtml(app.stage.replaceAll('_',' '))} · v${app.version}${app.snapshotSha256?' · SHA-256 '+escapeHtml(app.snapshotSha256.slice(0,16))+'…':''}</small></div><div class="trust-row-actions"><span class="status ${app.status==='active'?'green':'amber'}">${escapeHtml(app.status)}</span><button class="btn ghost" type="button" onclick="selectPlanningApplication('${escapeHtml(app.id)}')">Open</button></div></article>`).join(''):'<div class="notice">No planning applications in this scope.</div>';}
  window.selectPlanningApplication=function(id){planningActiveId=id;renderPlanningApplications();renderPlanningActive();};
  function renderPlanningActive(){const root=document.getElementById('planningActiveApplication'),app=planningApplications.find(x=>x.id===planningActiveId);if(!root)return;if(!app){root.innerHTML='<div class="notice">Create or select an application to manage its evidence registers.</div>';return;}const next=planningStages[planningStages.indexOf(app.stage)+1];root.innerHTML=`<section class="panel panel-pad planning-summary"><div class="trust-card-head"><div><h2>${escapeHtml(app.applicationNumber)} · ${escapeHtml(app.title)}</h2><p>${escapeHtml(app.propertyReference)} · ${escapeHtml(app.municipality)}</p></div><div class="trust-row-actions"><span class="status ${app.status==='active'?'green':'amber'}">${escapeHtml(app.stage.replaceAll('_',' '))}</span>${['json','csv','html'].map(format=>`<button class="btn ghost" type="button" onclick="downloadPlanningExport('${escapeHtml(app.id)}','${format}')">${format.toUpperCase()}</button>`).join('')}</div></div><div class="planning-stages">${['preparation',...planningStages].map(stage=>`<span class="${stage===app.stage?'active':''}">${escapeHtml(stage.replaceAll('_',' '))}</span>`).join('')}</div><div class="planning-kpis">${Object.entries(app.registerCounts).map(([type,count])=>`<div><b>${count}</b><span>${escapeHtml(type.replaceAll('_',' '))}</span></div>`).join('')}</div>${app.snapshotSha256?`<div class="notice"><b>Immutable submission snapshot</b><br>SHA-256 ${escapeHtml(app.snapshotSha256)} · external reference ${escapeHtml(app.externalReference)}. Later register entries do not alter this snapshot.</div>`:''}</section><form id="planningEntryForm" class="panel panel-pad planning-entry"><div class="trust-card-head"><div><h2>Add register evidence</h2><p>Documents, deadlines, participation, conditions, hearings, appeals, profiles, fees and messages.</p></div><span class="status">v${app.version}</span></div><div class="scaffold-grid"><label>Register<select class="form-select" name="entryType">${['document','deadline','participation','condition','hearing','appeal','municipality_profile','fee','message'].map(v=>`<option value="${v}">${escapeHtml(v.replaceAll('_',' '))}</option>`).join('')}</select></label><label>Status<select class="form-select" name="status">${['open','pending','complete','paid','unpaid','resolved','scheduled','received','responded','fulfilled','not_applicable'].map(v=>`<option value="${v}">${escapeHtml(v.replaceAll('_',' '))}</option>`).join('')}</select></label><label class="trust-wide">Title<input class="form-input" name="title" maxlength="220" required></label><label>Due date / time<input class="form-input" name="dueAt" type="datetime-local"></label><label>Amount (R)<input class="form-input" name="amount" type="number" min="0" step="0.01"></label><label class="trust-wide">Basis / provenance<input class="form-input" name="basis" maxlength="500" placeholder="Official notice, tariff, email or document reference"></label><label class="trust-check"><input type="checkbox" name="required"> Required submission evidence</label><label class="trust-wide">Structured details JSON<textarea class="form-textarea" name="payload">{}</textarea></label></div><div class="trust-actions"><button class="btn dark" type="submit">Add audited evidence</button><span id="planningEntryMessage" role="status"></span></div></form>${app.status==='draft'?`<form id="planningSubmitForm" class="panel panel-pad planning-submit"><div class="trust-card-head"><div><h2>Record external submission</h2><p>Requires a complete document entry, exact council reference and responsible-professional confirmation.</p></div><span class="status amber">Human gate</span></div><div class="scaffold-grid"><label>External reference<input class="form-input" name="externalReference" required maxlength="180"></label><label>Professional role<input class="form-input" name="professionalRole" readonly value="${escapeHtml(app.responsibleRole)}"></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed the exact evidence pack and am recording the external handoff.</label><label class="trust-wide">Reason<textarea class="form-textarea" name="reason" maxlength="500" required>Responsible professional reviewed the exact planning evidence pack before recording the external handoff.</textarea></label></div><div class="trust-actions"><button class="btn dark" type="submit">Record submitted snapshot</button><span id="planningSubmitMessage" role="status"></span></div></form>`:next?`<form id="planningStageForm" class="panel panel-pad planning-stage"><div class="trust-card-head"><div><h2>Record next external stage</h2><p>${escapeHtml(app.stage)} → ${escapeHtml(next)}. This records received evidence; it does not claim an authority decision.</p></div><span class="status amber">Human gate</span></div><div class="scaffold-grid"><input type="hidden" name="toStage" value="${escapeHtml(next)}"><label>External reference<input class="form-input" name="externalReference" required maxlength="180"></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> I verified the referenced external evidence.</label><label class="trust-wide">Reason<textarea class="form-textarea" name="reason" required maxlength="500"></textarea></label></div><div class="trust-actions"><button class="btn dark" type="submit">Record ${escapeHtml(next)}</button><span id="planningStageMessage" role="status"></span></div></form>`:''}<section class="panel panel-pad planning-history"><div class="trust-card-head"><div><h2>Registers and audit trail</h2><p>${app.entries.length} evidence entries · ${app.events.length} lifecycle events</p></div></div><div class="planning-entry-grid">${app.entries.length?app.entries.map(entry=>`<article><b>${escapeHtml(entry.title)}</b><span>${escapeHtml(entry.entryType.replaceAll('_',' '))} · ${escapeHtml(entry.status.replaceAll('_',' '))}</span><small>${escapeHtml(entry.basis||'No basis recorded')}${entry.dueAt?' · '+escapeHtml(entry.dueAt):''}${entry.amountCents!==null?' · R '+escapeHtml((entry.amountCents/100).toFixed(2)):''}</small></article>`).join(''):'<div class="notice">No register evidence yet.</div>'}</div><div class="planning-events">${app.events.map(event=>`<div><b>${escapeHtml(event.eventType.replaceAll('_',' '))}</b><span>${escapeHtml(event.reason)}${event.externalReference?' · '+escapeHtml(event.externalReference):''}</span><small>${escapeHtml(event.createdAt)}</small></div>`).join('')}</div></section>`;bindPlanningActive(app);}
  window.downloadPlanningExport=async function(id,format){try{const response=await fetch(`${api.base}/planning-applications/${encodeURIComponent(id)}/exports/${format}`,{headers:{Accept:'application/octet-stream','X-Organisation-Id':api.organisationId},credentials:'same-origin'});if(!response.ok)throw new Error('Planning evidence export failed.');const blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/),link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=match?.[1]||`planning-evidence.${format}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){showToast(error.message);}};
  function bindPlanningActive(app){const entry=document.getElementById('planningEntryForm');entry?.addEventListener('submit',async event=>{event.preventDefault();const f=event.currentTarget,v=new FormData(f),message=document.getElementById('planningEntryMessage');message.textContent='Saving…';try{const amount=String(v.get('amount')||'').trim();await api.post(`/planning-applications/${encodeURIComponent(app.id)}/entries`,{expectedVersion:app.version,entryType:v.get('entryType'),title:v.get('title'),status:v.get('status'),required:v.get('required')==='on',basis:v.get('basis'),dueAt:v.get('dueAt')?new Date(String(v.get('dueAt'))).toISOString():null,amountCents:amount===''?null:Math.round(Number(amount)*100),payload:JSON.parse(String(v.get('payload')||'{}'))});message.textContent='Evidence added without changing any existing snapshot.';await hydratePlanningWorkspace();}catch(error){message.textContent=error.message;}});const submit=document.getElementById('planningSubmitForm');submit?.addEventListener('submit',async event=>{event.preventDefault();const v=new FormData(event.currentTarget),message=document.getElementById('planningSubmitMessage');message.textContent='Recording…';try{await api.post(`/planning-applications/${encodeURIComponent(app.id)}/submit`,{expectedVersion:app.version,humanConfirmed:v.get('humanConfirmed')==='on',professionalRole:v.get('professionalRole'),reason:v.get('reason'),externalReference:v.get('externalReference')});message.textContent='Immutable submission snapshot recorded.';await hydratePlanningWorkspace();}catch(error){message.textContent=error.message;}});const stage=document.getElementById('planningStageForm');stage?.addEventListener('submit',async event=>{event.preventDefault();const v=new FormData(event.currentTarget),message=document.getElementById('planningStageMessage');message.textContent='Recording…';try{await api.post(`/planning-applications/${encodeURIComponent(app.id)}/stages`,{expectedVersion:app.version,humanConfirmed:v.get('humanConfirmed')==='on',toStage:v.get('toStage'),reason:v.get('reason'),externalReference:v.get('externalReference')});message.textContent='Stage evidence recorded.';await hydratePlanningWorkspace();}catch(error){message.textContent=error.message;}});}

  let regulatoryCases=[],regulatoryActiveId=null;
  const regulatoryTypeDefaults={environmental:{role:'environmental_practitioner',authority:'DFFE / competent authority',sourceTitle:'DFFE National Web-Based Environmental Screening Tool',sourceUrl:'https://www.dffe.gov.za/egis'},heritage:{role:'heritage_practitioner',authority:'SAHRA / responsible heritage authority',sourceTitle:'SAHRA Development Applications Unit',sourceUrl:'https://www.sahra.org.za/development-applications-unit/'}};
  function regulatoryWorkspace(){const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId),today=new Date().toISOString().slice(0,10),defaultType=state.tool==='eia_workspace'?'environmental':'heritage',defaults=regulatoryTypeDefaults[defaultType];if(!project)return `<div id="regulatoryWorkspace" class="regulatory-workspace"><div class="notice regulatory-boundary"><b>Project required:</b> Select a project before recording environmental or heritage evidence. Authority submissions and decisions remain external.</div></div>`;return `<div id="regulatoryWorkspace" class="regulatory-workspace"><div class="notice regulatory-boundary"><b>Authority boundary:</b> Architex records human-entered evidence and a verified professional route determination. DFFE screening, SAHRIS actions, authority acceptance, permits and approvals occur outside Architex and are never claimed here.</div><form id="regulatoryCreateForm" class="panel panel-pad regulatory-create"><div class="trust-card-head"><div><h2>New regulatory case</h2><p>${escapeHtml(project.name)} · source-controlled screening</p></div><span class="status amber">Official source</span></div><div class="scaffold-grid"><label>Case number<input class="form-input" name="caseNumber" required maxlength="80" value="${defaultType==='environmental'?'ENV':'HER'}-${new Date().getFullYear()}-"></label><label>Case type<select class="form-select" name="caseType"><option value="environmental" ${defaultType==='environmental'?'selected':''}>Environmental / EIA</option><option value="heritage" ${defaultType==='heritage'?'selected':''}>Heritage</option></select></label><label class="trust-wide">Title<input class="form-input" name="title" required maxlength="220"></label><label>Responsible role<input class="form-input" name="responsibleRole" readonly value="${escapeHtml(defaults.role)}"></label><label>Authority<input class="form-input" name="authorityName" required maxlength="220" value="${escapeHtml(defaults.authority)}"></label><label>Source retrieved<input class="form-input" type="date" name="retrievedAt" required value="${today}"></label><label class="trust-wide">Official source title<input class="form-input" name="sourceTitle" required maxlength="220" value="${escapeHtml(defaults.sourceTitle)}"></label><label class="trust-wide">Official source URL<input class="form-input" type="url" name="sourceUrl" required maxlength="1000" value="${escapeHtml(defaults.sourceUrl)}"></label></div><div class="trust-actions"><button class="btn dark" type="submit">Create governed case</button><span id="regulatoryCreateMessage" role="status"></span></div></form><section class="panel panel-pad regulatory-register"><div class="trust-card-head"><div><h2>Environmental & heritage register</h2><p>Evidence, determinations and immutable project records in MariaDB.</p></div><button class="btn ghost" type="button" onclick="refreshRegulatoryWorkspace()">Refresh</button></div><div id="regulatoryCaseList" class="trust-list"><div class="notice">Loading cases…</div></div></section><section id="regulatoryActiveCase" class="regulatory-active"><div class="notice">Create or select a regulatory case.</div></section></div>`;}
  function regulatoryEndpoint(){const projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;return projectId?`/projects/${encodeURIComponent(projectId)}/regulatory-cases`:null;}
  async function hydrateRegulatoryWorkspace(){const root=document.getElementById('regulatoryWorkspace'),endpoint=regulatoryEndpoint();if(!root||!endpoint)return;try{regulatoryCases=await api.get(endpoint);if(regulatoryActiveId&&!regulatoryCases.some(item=>item.id===regulatoryActiveId))regulatoryActiveId=null;if(!regulatoryActiveId)regulatoryActiveId=regulatoryCases[0]?.id||null;renderRegulatoryCases();renderRegulatoryActive();bindRegulatoryCreate();}catch(error){const list=document.getElementById('regulatoryCaseList');if(list)list.innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
