  function bindRegulatoryCreate(){const form=document.getElementById('regulatoryCreateForm');if(!form||form.dataset.bound)return;form.dataset.bound='1';form.elements.caseType.addEventListener('change',()=>{const values=regulatoryTypeDefaults[form.elements.caseType.value];form.elements.responsibleRole.value=values.role;form.elements.authorityName.value=values.authority;form.elements.sourceTitle.value=values.sourceTitle;form.elements.sourceUrl.value=values.sourceUrl;});form.addEventListener('submit',async event=>{event.preventDefault();const v=new FormData(form),message=document.getElementById('regulatoryCreateMessage');message.textContent='Creating…';try{const created=await api.post(regulatoryEndpoint(),{caseNumber:v.get('caseNumber'),caseType:v.get('caseType'),title:v.get('title'),authorityName:v.get('authorityName'),responsibleRole:v.get('responsibleRole'),sourceBasis:[{title:v.get('sourceTitle'),url:v.get('sourceUrl'),retrievedAt:v.get('retrievedAt')}]});regulatoryActiveId=created.id;message.textContent='Case created and audited.';await hydrateRegulatoryWorkspace();}catch(error){message.textContent=error.message;}});}
  function renderRegulatoryCases(){const list=document.getElementById('regulatoryCaseList');if(!list)return;list.innerHTML=regulatoryCases.length?regulatoryCases.map(item=>`<article class="trust-row ${item.id===regulatoryActiveId?'regulatory-selected':''}"><div><b>${escapeHtml(item.caseNumber)} · ${escapeHtml(item.title)}</b><span>${escapeHtml(item.caseType)} · ${escapeHtml(item.authorityName)}</span><small>v${item.version}${item.snapshotSha256?' · SHA-256 '+escapeHtml(item.snapshotSha256.slice(0,16))+'…':''}</small></div><div class="trust-row-actions"><span class="status ${item.status==='determined'?'green':'amber'}">${escapeHtml(item.status)}</span><button class="btn ghost" type="button" onclick="selectRegulatoryCase('${escapeHtml(item.id)}')">Open</button></div></article>`).join(''):'<div class="notice">No environmental or heritage cases for this project.</div>';}
  window.selectRegulatoryCase=function(id){regulatoryActiveId=id;renderRegulatoryCases();renderRegulatoryActive();};
  function renderRegulatoryActive(){const root=document.getElementById('regulatoryActiveCase'),item=regulatoryCases.find(row=>row.id===regulatoryActiveId);if(!root)return;if(!item){root.innerHTML='<div class="notice">Create or select a regulatory case.</div>';return;}const evidenceOptions=item.caseType==='environmental'?['screening_report','site_sensitivity_verification','listed_activity_review','specialist_study','public_participation','empr','monitoring','audit','authority_correspondence','condition']:['heritage_nid','heritage_impact_assessment','specialist_study','public_participation','authority_correspondence','permit','condition'];const routeOptions=item.caseType==='environmental'?['no_ea_indicated','basic_assessment','scoping_eia','other']:['nid','heritage_impact_assessment','permit_required','other'];root.innerHTML=`<section class="panel panel-pad regulatory-summary"><div class="trust-card-head"><div><h2>${escapeHtml(item.caseNumber)} · ${escapeHtml(item.title)}</h2><p>${escapeHtml(item.caseType)} · ${escapeHtml(item.authorityName)} · ${escapeHtml(item.responsibleRole.replaceAll('_',' '))}</p></div><div class="trust-row-actions"><span class="status ${item.status==='determined'?'green':'amber'}">${escapeHtml(item.status)}</span>${['json','csv','html'].map(format=>`<button class="btn ghost" type="button" onclick="downloadRegulatoryExport('${escapeHtml(item.id)}','${format}')">${format.toUpperCase()}</button>`).join('')}</div></div>${item.snapshotSha256?`<div class="notice"><b>Immutable professional determination</b><br>${escapeHtml(item.determinationRoute.replaceAll('_',' '))} · SHA-256 ${escapeHtml(item.snapshotSha256)} · authority decision claimed: no.</div>`:'<div class="notice">A route determination requires the specified evidence, explicit human confirmation, matching project responsibility, and a current independently reviewed professional registration.</div>'}</section>${item.status==='draft'?`<form id="regulatoryEvidenceForm" class="panel panel-pad regulatory-evidence"><div class="trust-card-head"><div><h2>Add source evidence</h2><p>Evidence is human entered and references an external controlled source.</p></div><span class="status">v${item.version}</span></div><div class="scaffold-grid"><label>Evidence type<select class="form-select" name="evidenceType">${evidenceOptions.map(type=>`<option value="${type}">${escapeHtml(type.replaceAll('_',' '))}</option>`).join('')}</select></label><label>Status<select class="form-select" name="status">${['pending','complete','submitted_externally','received','accepted','rejected','closed'].map(status=>`<option value="${status}">${escapeHtml(status.replaceAll('_',' '))}</option>`).join('')}</select></label><label class="trust-wide">Title<input class="form-input" name="title" required maxlength="220"></label><label>External reference<input class="form-input" name="externalReference" required maxlength="180"></label><label>Observed date<input class="form-input" type="date" name="observedAt" required value="${new Date().toISOString().slice(0,10)}"></label><label class="trust-wide">Evidence source URL<input class="form-input" type="url" name="sourceUrl" required maxlength="1000"></label><label class="trust-wide">Structured evidence JSON<textarea class="form-textarea" name="payload">{"humanEntered":true,"generatedOutsideArchitex":true}</textarea></label></div><div class="trust-actions"><button class="btn dark" type="submit">Add audited evidence</button><span id="regulatoryEvidenceMessage" role="status"></span></div></form><form id="regulatoryDetermineForm" class="panel panel-pad regulatory-determine"><div class="trust-card-head"><div><h2>Record professional route</h2><p>This is a professional evidence determination, not an authority decision or authorisation.</p></div><span class="status amber">Professional gate</span></div><div class="scaffold-grid"><label>Route<select class="form-select" name="route">${routeOptions.map(route=>`<option value="${route}">${escapeHtml(route.replaceAll('_',' '))}</option>`).join('')}</select></label><label>Responsible role<input class="form-input" name="professionalRole" readonly value="${escapeHtml(item.responsibleRole)}"></label><label>External reference<input class="form-input" name="externalReference" required maxlength="180"></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> I reviewed the exact source evidence and accept professional responsibility for this route record.</label><label class="trust-wide">Reason<textarea class="form-textarea" name="reason" required maxlength="500">Responsible professional reviewed the exact source evidence and recorded this route without claiming an authority decision.</textarea></label></div><div class="trust-actions"><button class="btn dark" type="submit">Issue immutable determination</button><span id="regulatoryDetermineMessage" role="status"></span></div></form>`:''}<section class="panel panel-pad regulatory-history"><div class="trust-card-head"><div><h2>Evidence register</h2><p>${item.evidence.length} source records · existing determinations remain immutable.</p></div></div><div class="regulatory-evidence-grid">${item.evidence.length?item.evidence.map(e=>`<article><b>${escapeHtml(e.title)}</b><span>${escapeHtml(e.evidenceType.replaceAll('_',' '))} · ${escapeHtml(e.status.replaceAll('_',' '))}</span><small>${escapeHtml(e.externalReference)} · ${escapeHtml(e.observedAt)}</small><a href="${escapeHtml(e.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open controlled source</a></article>`).join(''):'<div class="notice">No source evidence recorded.</div>'}</div></section>`;bindRegulatoryActive(item);}
  function bindRegulatoryActive(item){document.getElementById('regulatoryEvidenceForm')?.addEventListener('submit',async event=>{event.preventDefault();const v=new FormData(event.currentTarget),message=document.getElementById('regulatoryEvidenceMessage');message.textContent='Saving…';try{await api.post(`/regulatory-cases/${encodeURIComponent(item.id)}/evidence`,{expectedVersion:item.version,evidenceType:v.get('evidenceType'),title:v.get('title'),status:v.get('status'),externalReference:v.get('externalReference'),sourceUrl:v.get('sourceUrl'),observedAt:v.get('observedAt'),payload:JSON.parse(String(v.get('payload')||'{}'))});message.textContent='Evidence persisted with provenance.';await hydrateRegulatoryWorkspace();}catch(error){message.textContent=error.message;}});document.getElementById('regulatoryDetermineForm')?.addEventListener('submit',async event=>{event.preventDefault();const v=new FormData(event.currentTarget),message=document.getElementById('regulatoryDetermineMessage');message.textContent='Verifying responsibility…';try{await api.post(`/regulatory-cases/${encodeURIComponent(item.id)}/determine`,{expectedVersion:item.version,humanConfirmed:v.get('humanConfirmed')==='on',professionalRole:v.get('professionalRole'),route:v.get('route'),reason:v.get('reason'),externalReference:v.get('externalReference')});message.textContent='Immutable route determination issued.';await hydrateRegulatoryWorkspace();}catch(error){message.textContent=error.message;}});}
  window.downloadRegulatoryExport=async function(id,format){try{const response=await fetch(`${api.base}/regulatory-cases/${encodeURIComponent(id)}/exports/${format}`,{headers:{Accept:'application/octet-stream','X-Organisation-Id':api.organisationId},credentials:'same-origin'});if(!response.ok)throw new Error('Regulatory evidence export failed.');const blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/),link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=match?.[1]||`regulatory-evidence.${format}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){showToast(error.message);}};

  let surveyJobs=[],surveyActiveId=null;
  function surveyWorkspace(){const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId),today=new Date().toISOString().slice(0,10);if(!project)return '<div id="surveyWorkspace" class="survey-workspace"><div class="notice survey-boundary"><b>Project required:</b> Select a project before recording survey evidence.</div></div>';return `<div id="surveyWorkspace" class="survey-workspace"><div class="notice survey-boundary"><b>Professional boundary:</b> Coordinates, beacons, cadastral references and fees are human-entered evidence. Architex does not claim official coordinates, cadastral validity, Surveyor-General examination, approval or registration. Private professional fees remain separate from statutory fees.</div><form id="surveyCreateForm" class="panel panel-pad survey-create"><div class="trust-card-head"><div><h2>New survey job</h2><p>${escapeHtml(project.name)} · controlled geomatics evidence</p></div><span class="status amber">SAGC role gate</span></div><div class="scaffold-grid"><label>Job number<input class="form-input" name="jobNumber" required maxlength="80" value="SUR-${new Date().getFullYear()}-"></label><label>Survey type<select class="form-select" name="surveyType">${['topographical','boundary','beacon_relocation','subdivision','consolidation','sectional_title','servitude','lease_diagram','general_plan','as_built','other'].map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label class="trust-wide">Title<input class="form-input" name="title" required maxlength="220"></label><label>Responsible role<input class="form-input" name="responsibleRole" readonly value="land_surveyor"></label><label>Coordinate reference system<input class="form-input" name="coordinateReferenceSystem" required value="Hartebeesthoek94 / Lo29"></label><label>Vertical datum<input class="form-input" name="verticalDatum" required value="MSL"></label><label>Source retrieved<input class="form-input" type="date" name="retrievedAt" required value="${today}"></label><label class="trust-wide">Official source title<input class="form-input" name="sourceTitle" required value="Geomatics Profession Act 19 of 2013"></label><label class="trust-wide">Official source URL<input class="form-input" type="url" name="sourceUrl" required value="https://www.gov.za/documents/geomatics-profession-act"></label></div><div class="trust-actions"><button class="btn dark" type="submit">Create survey job</button><span id="surveyCreateMessage" role="status"></span></div></form><section class="panel panel-pad survey-register"><div class="trust-card-head"><div><h2>Survey job register</h2><p>Project-scoped evidence persisted in MariaDB.</p></div><button class="btn ghost" type="button" onclick="refreshSurveyWorkspace()">Refresh</button></div><div id="surveyJobList" class="trust-list"><div class="notice">Loading survey jobs…</div></div></section><section id="surveyActiveJob" class="survey-active"><div class="notice">Create or select a survey job.</div></section></div>`;}
  function surveyEndpoint(){const id=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;return id?`/projects/${encodeURIComponent(id)}/survey-jobs`:null;}async function hydrateSurveyWorkspace(){const root=document.getElementById('surveyWorkspace'),endpoint=surveyEndpoint();if(!root||!endpoint)return;try{surveyJobs=await api.get(endpoint);if(surveyActiveId&&!surveyJobs.some(x=>x.id===surveyActiveId))surveyActiveId=null;if(!surveyActiveId)surveyActiveId=surveyJobs[0]?.id||null;renderSurveyJobs();renderSurveyActive();bindSurveyCreate();}catch(error){document.getElementById('surveyJobList').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}window.refreshSurveyWorkspace=hydrateSurveyWorkspace;
  function bindSurveyCreate(){const form=document.getElementById('surveyCreateForm');if(!form||form.dataset.bound)return;form.dataset.bound='1';form.addEventListener('submit',async event=>{event.preventDefault();const v=new FormData(form),m=document.getElementById('surveyCreateMessage');m.textContent='Creating…';try{const x=await api.post(surveyEndpoint(),{jobNumber:v.get('jobNumber'),surveyType:v.get('surveyType'),title:v.get('title'),responsibleRole:v.get('responsibleRole'),coordinateReferenceSystem:v.get('coordinateReferenceSystem'),verticalDatum:v.get('verticalDatum'),sourceBasis:[{title:v.get('sourceTitle'),url:v.get('sourceUrl'),retrievedAt:v.get('retrievedAt')}]});surveyActiveId=x.id;m.textContent='Survey job created and audited.';await hydrateSurveyWorkspace();}catch(error){m.textContent=error.message;}});}
  function renderSurveyJobs(){const list=document.getElementById('surveyJobList');if(!list)return;list.innerHTML=surveyJobs.length?surveyJobs.map(x=>`<article class="trust-row ${x.id===surveyActiveId?'survey-selected':''}"><div><b>${escapeHtml(x.jobNumber)} · ${escapeHtml(x.title)}</b><span>${escapeHtml(x.surveyType.replaceAll('_',' '))} · ${escapeHtml(x.coordinateReferenceSystem)}</span><small>v${x.version}${x.snapshotSha256?' · SHA-256 '+escapeHtml(x.snapshotSha256.slice(0,16))+'…':''}</small></div><div class="trust-row-actions"><span class="status ${x.status==='issued'?'green':'amber'}">${x.status}</span><button class="btn ghost" type="button" onclick="selectSurveyJob('${x.id}')">Open</button></div></article>`).join(''):'<div class="notice">No survey jobs for this project.</div>';}window.selectSurveyJob=id=>{surveyActiveId=id;renderSurveyJobs();renderSurveyActive();};
  function renderSurveyActive(){const root=document.getElementById('surveyActiveJob'),x=surveyJobs.find(j=>j.id===surveyActiveId),today=new Date().toISOString().slice(0,10);if(!root)return;if(!x){root.innerHTML='<div class="notice">Create or select a survey job.</div>';return;}root.innerHTML=`<section class="panel panel-pad survey-summary"><div class="trust-card-head"><div><h2>${escapeHtml(x.jobNumber)} · ${escapeHtml(x.title)}</h2><p>${escapeHtml(x.coordinateReferenceSystem)} · ${escapeHtml(x.verticalDatum)}</p></div><div class="trust-row-actions"><span class="status ${x.status==='issued'?'green':'amber'}">${x.status}</span>${['json','csv','html'].map(f=>`<button class="btn ghost" type="button" onclick="downloadSurveyExport('${x.id}','${f}')">${f.toUpperCase()}</button>`).join('')}</div></div>${x.snapshotSha256?`<div class="notice"><b>Immutable survey issue</b><br>SHA-256 ${escapeHtml(x.snapshotSha256)} · Surveyor-General approval claimed: no.</div>`:'<div class="notice">Issue requires two verified observations, one complete deliverable, separated fees, explicit confirmation and current independently reviewed land-surveyor authority.</div>'}</section>${x.status==='draft'?`<form id="surveyObservationForm" class="panel panel-pad"><h2>Control point / observation</h2><div class="scaffold-grid"><label>Point code<input class="form-input" name="pointCode" required></label><label>Type<select class="form-select" name="observationType">${['control_point','benchmark','beacon','boundary_marker','detail_point','other'].map(v=>`<option value="${v}">${v.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Easting<input class="form-input" name="easting" required></label><label>Northing<input class="form-input" name="northing" required></label><label>Elevation<input class="form-input" name="elevation" required></label><label>Status<select class="form-select" name="status"><option value="observed">observed</option><option value="verified">verified</option></select></label><label>Source reference<input class="form-input" name="sourceReference" required></label><label>Observed<input class="form-input" type="date" name="observedAt" value="${today}" required></label><label class="trust-wide">Source URL<input class="form-input" type="url" name="sourceUrl" required></label></div><div class="trust-actions"><button class="btn dark">Add observation</button><span id="surveyObservationMessage"></span></div></form><form id="surveyDeliverableForm" class="panel panel-pad"><h2>Survey deliverable</h2><div class="scaffold-grid"><label>Type<select class="form-select" name="deliverableType">${['topographical_plan','cadastral_diagram','general_plan','beacon_certificate','control_report','servitude_diagram','sectional_title_plan','as_built_plan','coordinate_schedule','other'].map(v=>`<option value="${v}">${v.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Status<select class="form-select" name="status"><option value="draft">draft</option><option value="complete">complete</option><option value="submitted_externally">submitted externally</option></select></label><label class="trust-wide">Title<input class="form-input" name="title" required></label><label>External reference<input class="form-input" name="externalReference" required></label><label class="trust-wide">Source URL<input class="form-input" type="url" name="sourceUrl" required></label></div><div class="trust-actions"><button class="btn dark">Add deliverable</button><span id="surveyDeliverableMessage"></span></div></form><form id="surveyFeeForm" class="panel panel-pad"><h2>Fee separation</h2><div class="scaffold-grid"><label>Field days<input class="form-input" name="fieldDays" value="2.00" required></label><label>Field rate (R/day)<input class="form-input" type="number" name="fieldRate" value="1500" required></label><label>Office days<input class="form-input" name="officeDays" value="1.50" required></label><label>Office rate (R/day)<input class="form-input" type="number" name="officeRate" value="1200" required></label><label>Travel km<input class="form-input" name="travelDistanceKm" value="80.00" required></label><label>Travel rate (R/km)<input class="form-input" type="number" name="travelRate" value="6.50" required></label><label>Complexity allowance (R)<input class="form-input" type="number" name="complexity" value="250" required></label><label>Statutory fees (R)<input class="form-input" type="number" name="statutory" value="450" required></label><label class="trust-wide">Statutory source title<input class="form-input" name="statutorySourceTitle" value="Chief Surveyor-General prescribed fees" required></label><label class="trust-wide">Statutory source URL<input class="form-input" type="url" name="statutorySourceUrl" value="https://csg.dlrrd.gov.za/fees.htm" required></label><input type="hidden" name="retrievedAt" value="${today}"></div><div class="trust-actions"><button class="btn dark">Calculate and persist separated fees</button><span id="surveyFeeMessage"></span></div></form><form id="surveyIssueForm" class="panel panel-pad"><h2>Professional issue</h2><div class="scaffold-grid"><label>External reference<input class="form-input" name="externalReference" required></label><label>Professional role<input class="form-input" name="professionalRole" readonly value="${escapeHtml(x.responsibleRole)}"></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed the exact observations, datum, deliverables and separated fees.</label><label class="trust-wide">Reason<textarea class="form-textarea" name="reason" required>Registered land surveyor reviewed the exact survey evidence without claiming Surveyor-General approval or official coordinates.</textarea></label></div><div class="trust-actions"><button class="btn dark">Issue immutable survey record</button><span id="surveyIssueMessage"></span></div></form>`:''}<section class="panel panel-pad survey-history"><h2>Evidence register</h2><div class="survey-evidence-grid">${x.observations.map(o=>`<article><b>${escapeHtml(o.pointCode)}</b><span>${escapeHtml(o.observationType.replaceAll('_',' '))} · ${escapeHtml(o.status)}</span><small>${escapeHtml(o.easting)}, ${escapeHtml(o.northing)}, ${escapeHtml(o.elevation)} · ${escapeHtml(o.sourceReference)}</small></article>`).join('')}${x.deliverables.map(d=>`<article><b>${escapeHtml(d.title)}</b><span>${escapeHtml(d.deliverableType.replaceAll('_',' '))} · ${escapeHtml(d.status)}</span><small>${escapeHtml(d.externalReference)}</small></article>`).join('')}</div>${x.feePayload?`<div class="notice">Private professional fee R ${(x.privateProfessionalFeeCents/100).toFixed(2)} · statutory fee R ${(x.statutoryFeeCents/100).toFixed(2)} · total R ${(x.totalFeeCents/100).toFixed(2)}</div>`:''}</section>`;bindSurveyActive(x);}
  function bindSurveyActive(x){const bind=(id,message,path,body)=>document.getElementById(id)?.addEventListener('submit',async event=>{event.preventDefault();const m=document.getElementById(message);m.textContent='Saving…';try{await api.post(`/survey-jobs/${encodeURIComponent(x.id)}/${path}`,body(new FormData(event.currentTarget)));m.textContent='Saved with audit evidence.';await hydrateSurveyWorkspace();}catch(error){m.textContent=error.message;}});bind('surveyObservationForm','surveyObservationMessage','observations',v=>({expectedVersion:x.version,pointCode:v.get('pointCode'),observationType:v.get('observationType'),easting:v.get('easting'),northing:v.get('northing'),elevation:v.get('elevation'),status:v.get('status'),sourceReference:v.get('sourceReference'),sourceUrl:v.get('sourceUrl'),observedAt:v.get('observedAt'),payload:{humanEntered:true}}));bind('surveyDeliverableForm','surveyDeliverableMessage','deliverables',v=>({expectedVersion:x.version,deliverableType:v.get('deliverableType'),title:v.get('title'),status:v.get('status'),externalReference:v.get('externalReference'),sourceUrl:v.get('sourceUrl'),payload:{humanEntered:true}}));const cents=v=>Math.round(Number(v)*100);bind('surveyFeeForm','surveyFeeMessage','fees',v=>({expectedVersion:x.version,fieldDays:v.get('fieldDays'),fieldDayRateCents:cents(v.get('fieldRate')),officeDays:v.get('officeDays'),officeDayRateCents:cents(v.get('officeRate')),travelDistanceKm:v.get('travelDistanceKm'),travelRateCentsPerKm:cents(v.get('travelRate')),complexityAllowanceCents:cents(v.get('complexity')),statutoryFeeCents:cents(v.get('statutory')),statutorySourceTitle:v.get('statutorySourceTitle'),statutorySourceUrl:v.get('statutorySourceUrl'),statutorySourceRetrievedAt:v.get('retrievedAt')}));bind('surveyIssueForm','surveyIssueMessage','issue',v=>({expectedVersion:x.version,humanConfirmed:v.get('humanConfirmed')==='on',professionalRole:v.get('professionalRole'),reason:v.get('reason'),externalReference:v.get('externalReference')}));}
  window.downloadSurveyExport=async function(id,format){try{const response=await fetch(`${api.base}/survey-jobs/${encodeURIComponent(id)}/exports/${format}`,{headers:{'X-Organisation-Id':api.organisationId},credentials:'same-origin'});if(!response.ok)throw new Error('Survey export failed.');const blob=await response.blob(),link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=`survey-evidence.${format}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){showToast(error.message);}};

  let procurementPackages=[],procurementWorkspace=null,procurementMatches=[],procurementDocuments=[],procurementListings=[];
  const procurementAppointmentState='appointment_pending_formalisation';
