  function rfqMarketplaceWorkspace(){const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);if(!project)return '<div id="rfqMarketplaceWorkspace"><div class="notice"><b>Project required:</b> Select a project before preparing a procurement package.</div></div>';return `<div id="rfqMarketplaceWorkspace" class="procurement-workspace"><div class="notice"><b>Fair tendering:</b> Matching and comparisons are advisory. Material clarifications are distributed as equal-information addenda to every active bidder. <b>No automatic award</b>, contract, signed appointment, statutory threshold or email delivery is claimed.</div>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Marketplace presence</h2><p>Publish a public-safe capacity listing. Private organisation and verification evidence stays protected.</p></div><span class="status amber">Human publication</span></div><form id="procurementListingForm" class="scaffold-grid"><label>Listing type<select class="form-select" name="listingType">${['contractor','subcontractor','supplier','specialist_consultant','quantity_surveyor_support','freelancer_candidate_professional','equipment_resource'].map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Name<input class="form-input" name="name" required maxlength="180"></label><label class="trust-wide">Public summary<textarea class="form-textarea" name="publicSummary" required maxlength="1000"></textarea></label><label>Trades / disciplines<input class="form-input" name="disciplinesTrades" required placeholder="architecture, general_building"></label><label>Service areas<input class="form-input" name="serviceAreas" required placeholder="Gauteng, Johannesburg"></label><label>Capacity<select class="form-select" name="capacityStatus"><option value="available">Available</option><option value="limited">Limited</option><option value="unavailable">Unavailable</option></select></label><label class="trust-check"><input type="checkbox" name="supervisionRequired"> Registered-professional supervision required</label><div class="trust-actions trust-wide"><button class="btn dark" type="submit">Create private draft</button><span id="procurementListingMessage" role="status"></span></div></form><div id="procurementListingList" class="trust-list"><div class="notice">Loading your listings…</div></div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>New governed package</h2><p>${escapeHtml(project.name)} · classification is an organisational guide, never a statutory threshold.</p></div><span class="status amber">Issued documents required</span></div><form id="procurementPackageForm" class="scaffold-grid"><label>Package number<input class="form-input" name="packageNumber" required value="RFQ-${new Date().getFullYear()}-"></label><label>Title<input class="form-input" name="title" required maxlength="220"></label><label>Procurement need<select class="form-select" name="procurementNeed"><option value="appoint a main contractor">Main contractor</option><option value="appoint a trade subcontractor">Trade package</option><option value="procure materials or equipment">Supplier</option><option value="appoint a specialist consultant">Specialist consultant</option><option value="freelance project support">Freelancer support</option></select></label><label>Selected method<select class="form-select" name="procurementMethod"><option value="invited_tender">Invited tender</option><option value="open_tender">Open tender</option><option value="rfq">RFQ</option><option value="direct_appointment">Direct appointment</option></select></label><label class="trust-wide">Method reason<textarea class="form-textarea" name="methodReason" required>Project team selected this controlled method after considering scope, value, complexity, urgency and market access.</textarea></label><label class="trust-wide">Scope summary<textarea class="form-textarea" name="scopeSummary" required></textarea></label><label>Estimated value (R)<input class="form-input" type="number" name="estimatedValueZar" min="0" step="0.01" required></label><label>Complexity<select class="form-select" name="complexity"><option>medium</option><option>low</option><option>high</option></select></label><label>Urgency<select class="form-select" name="urgency"><option>normal</option><option>urgent</option><option>emergency</option></select></label><label>Province<input class="form-input" name="province" required value="Gauteng"></label><label>Location<input class="form-input" name="location" required value="Johannesburg"></label><label>Required trades<input class="form-input" name="requiredTrades" placeholder="general_building"></label><label>Required specialists<input class="form-input" name="requiredSpecialists" placeholder="architect"></label><label class="trust-wide">Required returnables<input class="form-input" name="requiredReturnables" required value="priced_scope, programme, tax_clearance, exclusions_schedule"></label><label>Municipal readiness (%)<input class="form-input" type="number" name="municipalReadinessScore" min="0" max="100" value="80" required></label><label>Deadline<input class="form-input" type="datetime-local" name="deadlineAt" required></label><label class="trust-wide">Issued-for-tender documents<select id="procurementDocumentSelect" class="form-select" name="documentRevisionIds" required multiple size="4"><option value="">Loading controlled documents…</option></select></label><fieldset class="proposal-terms trust-wide"><legend>Evaluation criteria (%)</legend><label>Price <input class="form-input" type="number" name="priceWeight" value="40" min="0" max="100"></label><label>Returnables <input class="form-input" type="number" name="returnablesWeight" value="20" min="0" max="100"></label><label>Lead time <input class="form-input" type="number" name="leadWeight" value="15" min="0" max="100"></label><label>Risk <input class="form-input" type="number" name="riskWeight" value="25" min="0" max="100"></label></fieldset><div class="trust-actions trust-wide"><button class="btn dark" type="submit">Create draft package</button><span id="procurementPackageMessage" role="status"></span></div></form></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Package register</h2><p>Drafts, immutable issued revisions, invitations and award governance.</p></div><button class="btn ghost" type="button" onclick="refreshProcurementWorkspace()">Refresh</button></div><div id="procurementPackageList" class="trust-list"><div class="notice">Loading packages…</div></div></section><section id="procurementActivePackage"><div class="notice">Create or select a package.</div></section></div>`;}
  async function hydrateProcurementWorkspace(){const root=document.getElementById('rfqMarketplaceWorkspace'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root||!projectId)return;try{const[packs,docs,mine]=await Promise.all([api.get(`/projects/${encodeURIComponent(projectId)}/procurement-packages`),api.get(`/documents?projectId=${encodeURIComponent(projectId)}`),api.get('/marketplace/listings/mine')]);procurementPackages=packs;procurementDocuments=docs.filter(x=>x.status==='issued'&&x.issuePurpose==='for_tender');procurementListings=mine;if(activeProcurementPackageId&&!packs.some(x=>x.id===activeProcurementPackageId))activeProcurementPackageId=null;activeProcurementPackageId=activeProcurementPackageId||packs[0]?.id||null;renderProcurementListings();renderProcurementDocuments();renderProcurementPackages();bindProcurementWorkspace();if(activeProcurementPackageId)await loadProcurementPackage(activeProcurementPackageId);}catch(error){document.getElementById('procurementPackageList').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function renderProcurementDocuments(){const select=document.getElementById('procurementDocumentSelect');if(!select)return;select.innerHTML=procurementDocuments.length?procurementDocuments.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.title)} · ${escapeHtml(x.revisionCode)} · issued for tender</option>`).join(''):'<option value="">No issued-for-tender document revision is available</option>';}
  function renderProcurementListings(){const list=document.getElementById('procurementListingList');if(!list)return;list.innerHTML=procurementListings.length?procurementListings.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.name)}</b><span>${escapeHtml(x.listingType.replaceAll('_',' '))} · ${escapeHtml(x.capacityStatus)}</span><small>${escapeHtml(x.verificationStatus)} · ${escapeHtml(x.status)}</small></div>${x.status==='draft'?`<button class="btn dark" type="button" onclick="publishProcurementListing('${x.id}',${x.version})">Review & publish</button>`:'<span class="status green">public</span>'}</article>`).join(''):'<div class="notice">No organisation marketplace listings yet.</div>';}
  function renderProcurementPackages(){const list=document.getElementById('procurementPackageList');if(!list)return;list.innerHTML=procurementPackages.length?procurementPackages.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.packageNumber)} · ${escapeHtml(x.title)}</b><span>${escapeHtml(x.procurementType.replaceAll('_',' '))} · ${escapeHtml(x.procurementMethod.replaceAll('_',' '))}</span><small>${escapeHtml(x.status)} · deadline ${escapeHtml(x.deadlineAt)}</small></div><button class="btn ghost" type="button" onclick="selectProcurementPackage('${x.id}')">Open</button></article>`).join(''):'<div class="notice">No procurement packages yet.</div>';}
  async function loadProcurementPackage(id){activeProcurementPackageId=id;procurementWorkspace=await api.get(`/procurement-packages/${encodeURIComponent(id)}/workspace`);renderProcurementActive();}
  function renderProcurementActive(){const root=document.getElementById('procurementActivePackage'),w=procurementWorkspace;if(!root||!w)return;const p=w.package,material=w.clarifications.filter(x=>x.material&&x.status==='submitted'),latestComparison=w.comparisons[0],latestRecommendation=w.recommendations[0];root.innerHTML=`<section class="panel panel-pad"><div class="trust-card-head"><div><h2>${escapeHtml(p.packageNumber)} · ${escapeHtml(p.title)}</h2><p>${escapeHtml(p.scopeSummary)}</p></div><span class="status ${p.status==='issued'?'green':'amber'}">${escapeHtml(p.status)}</span></div><div class="notice">${p.snapshotSha256?'Immutable issue SHA-256 '+escapeHtml(p.snapshotSha256):'Draft: review the exact method, returnables, criteria and controlled documents before issue.'}</div>${p.status==='draft'?`<form id="procurementIssueForm" class="trust-actions"><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> I reviewed the exact package and controlled documents.</label><input class="form-input" name="reason" required value="Project team reviewed the exact RFQ package and its fairness controls."><button class="btn dark">Issue package</button><span role="status"></span></form>`:`<div class="trust-actions"><button class="btn ghost" type="button" onclick="matchProcurementMarketplace()">Refresh advisory matches</button><button class="btn dark" type="button" onclick="compareProcurementQuotes()">Create advisory comparison</button></div>`}<div id="procurementMatchList" class="trust-list">${procurementMatches.length?procurementMatches.map(m=>`<article class="trust-row"><div><b>${escapeHtml(m.listing.name)} · ${m.score}</b><span>${m.reasons.map(escapeHtml).join(' · ')}</span><small>Advisory only · conflict declaration required</small></div><button class="btn dark" type="button" onclick="inviteProcurementListing('${m.listing.id}')">Invite</button></article>`).join(''):p.status==='issued'?'<div class="notice">Run marketplace matching to see advisory candidates.</div>':''}</div></section>
    ${p.status==='issued'?`<section class="panel panel-pad"><div class="trust-card-head"><div><h2>Bidder communications</h2><p>${w.invitations.length} invitations · emailDeliveryClaimed=false · copy each one-time link through an approved channel.</p></div><span class="status amber">In-app records</span></div><div id="procurementInviteShare"></div><div class="trust-list">${w.invitations.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.listingName)}</b><span>${escapeHtml(x.status)} · ${escapeHtml(x.deliveryStatus)}</span><small>Access token cannot be retrieved after invitation creation.</small></div></article>`).join('')||'<div class="notice">No bidders invited.</div>'}</div>${material.length?`<form id="procurementAddendumForm" class="scaffold-grid"><label>Title<input class="form-input" name="title" required value="Addendum ${w.addenda.length+1}"></label><label class="trust-wide">Equal-information response<textarea class="form-textarea" name="content" required></textarea></label><fieldset class="proposal-terms trust-wide"><legend>Material clarifications answered</legend>${material.map(x=>`<label><input type="checkbox" name="clarificationIds" value="${x.id}" checked> ${escapeHtml(x.question)}</label>`).join('')}</fieldset><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Issue this exact response to every active bidder.</label><label class="trust-wide">Reason<input class="form-input" name="reason" required value="Material clarification answered through equal distribution."></label><button class="btn dark">Issue equal-information addendum</button><span id="procurementAddendumMessage" role="status"></span></form>`:'<div class="notice">No unanswered material clarifications.</div>'}<div class="trust-list">${w.addenda.map(x=>`<article class="trust-row"><div><b>Addendum ${x.sequenceNumber} · ${escapeHtml(x.title)}</b><span>${x.distributionCount} equal-information distributions</span><small>SHA-256 ${escapeHtml(x.snapshotSha256)}</small></div></article>`).join('')}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Quote facts & advisory comparison</h2><p>Raw returnables, exclusions, qualifications, conflicts and lateness remain visible.</p></div><span class="status amber">No automatic award</span></div><div class="trust-list">${w.quotes.map(q=>`<article class="trust-row"><div><b>${escapeHtml(q.listingName)} · ${procurementMoney(q.priceZar)}</b><span>${q.leadTimeWeeks} weeks · missing: ${q.missingReturnables.map(escapeHtml).join(', ')||'none'}</span><small>Exclusions: ${q.exclusions.map(escapeHtml).join(', ')||'none'} · qualifications: ${q.qualifications.map(escapeHtml).join(', ')||'none'} · conflictDeclared=${q.conflictDeclared} · late=${q.lateSubmission}</small></div></article>`).join('')||'<div class="notice">No quotes submitted.</div>'}</div>${latestComparison&&w.quotes.length?`<form id="procurementRecommendationForm" class="scaffold-grid"><input type="hidden" name="comparisonId" value="${latestComparison.id}"><label>Selected quote revision<select class="form-select" name="quoteRevisionId">${w.quotes.map(q=>`<option value="${q.revisionId}">${escapeHtml(q.listingName)} · ${procurementMoney(q.priceZar)}</option>`).join('')}</select></label><label class="trust-wide">Human recommendation reason<textarea class="form-textarea" name="reason" required></textarea></label><label class="trust-wide">Risk notes<input class="form-input" name="riskNotes" required placeholder="One risk per line"></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed the comparison and recommend this exact revision; no award is automatic.</label><button class="btn dark">Record award recommendation</button><span id="procurementRecommendationMessage" role="status"></span></form>`:'<div class="notice">At least two current quotes are required before an advisory comparison.</div>'}</section>
    ${latestRecommendation?`<section class="panel panel-pad"><div class="trust-card-head"><div><h2>Separate award decisions</h2><p>Client and verified procurement professional approvals must be by distinct users.</p></div><span class="status amber">${escapeHtml(latestRecommendation.status)}</span></div><form id="procurementApprovalForm" class="scaffold-grid"><input type="hidden" name="recommendationId" value="${latestRecommendation.id}"><label>Approval capacity<select class="form-select" name="approvalType"><option value="client">Client</option><option value="professional">Professional</option></select></label><label>Recorded role / capacity<input class="form-input" name="approverCapacity" value="client" required></label><label>Decision<select class="form-select" name="decision"><option value="approved">Approve</option><option value="rejected">Reject</option></select></label><label class="trust-wide">Reason<input class="form-input" name="reason" required></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed the immutable recommendation in this recorded capacity.</label><button class="btn dark">Record separate decision</button><span id="procurementApprovalMessage" role="status"></span></form><form id="procurementFinaliseForm" class="trust-actions"><input type="hidden" name="recommendationId" value="${latestRecommendation.id}"><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Create only an appointment placeholder.</label><input class="form-input" name="reason" required value="Both decisions reviewed; formal signed appointment remains outstanding."><button class="btn dark">Create appointment placeholder</button><span id="procurementFinaliseMessage" role="status"></span></form><div class="trust-list">${w.appointmentPlaceholders.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.listingName)}</b><span>${escapeHtml(x.status)}</span><small>Not a contract or signed appointment · SHA-256 ${escapeHtml(x.snapshotSha256)}</small></div></article>`).join('')}</div></section>`:''}`:''}`;bindProcurementActive();}
  function bindProcurementWorkspace(){const listing=document.getElementById('procurementListingForm'),packageForm=document.getElementById('procurementPackageForm');listing?.setAttribute('autocomplete','off');listing?.elements.name?.setAttribute('autocomplete','organization');packageForm?.setAttribute('autocomplete','off');listing?.addEventListener('submit',createProcurementListing);packageForm?.addEventListener('submit',createProcurementPackage);const deadline=document.querySelector('#procurementPackageForm [name=deadlineAt]');if(deadline&&!deadline.value){const date=new Date(Date.now()+14*86400000);deadline.value=date.toISOString().slice(0,16);}}
  function bindProcurementActive(){document.getElementById('procurementIssueForm')?.addEventListener('submit',issueProcurementPackage);document.getElementById('procurementAddendumForm')?.addEventListener('submit',issueProcurementAddendum);document.getElementById('procurementRecommendationForm')?.addEventListener('submit',recommendProcurementAward);document.getElementById('procurementApprovalForm')?.addEventListener('submit',approveProcurementAward);const finalise=document.getElementById('procurementFinaliseForm');finalise?.elements.reason?.setAttribute('aria-label','Appointment placeholder reason');finalise?.addEventListener('submit',finaliseProcurementAward);}
  async function createProcurementListing(event){event.preventDefault();const f=event.currentTarget,v=new FormData(f),m=document.getElementById('procurementListingMessage');m.textContent='Creating…';try{await api.post('/marketplace/listings',{listingType:v.get('listingType'),name:v.get('listingName'),publicSummary:v.get('publicSummary'),disciplinesTrades:procurementLines(v.get('disciplinesTrades')),serviceAreas:procurementLines(v.get('serviceAreas')),capacityStatus:v.get('capacityStatus'),supervisionRequired:v.get('supervisionRequired')==='on'});m.textContent='Private draft created.';await hydrateProcurementWorkspace();}catch(e){m.textContent=e.message;}}
  async function publishProcurementListing(id,version){try{await api.post(`/marketplace/listings/${id}/publish`,{expectedVersion:version,humanConfirmed:true,reason:'Organisation owner reviewed the exact public-safe marketplace listing.'});await hydrateProcurementWorkspace();}catch(e){showToast(e.message);}}window.publishProcurementListing=publishProcurementListing;
  async function createProcurementPackage(event){event.preventDefault();const f=event.currentTarget,v=new FormData(f),m=document.getElementById('procurementPackageMessage');m.textContent='Creating governed draft…';try{const weights={price:Number(v.get('priceWeight')),returnables:Number(v.get('returnablesWeight')),lead_time:Number(v.get('leadWeight')),risk:Number(v.get('riskWeight'))};await api.post(`/projects/${encodeURIComponent(window.__ARCHITEX_SHELL_STATE__.selectedProjectId)}/procurement-packages`,{packageNumber:v.get('packageNumber'),title:v.get('title'),procurementNeed:v.get('procurementNeed'),procurementMethod:v.get('procurementMethod'),methodReason:v.get('methodReason'),scopeSummary:v.get('scopeSummary'),estimatedValueZar:Number(v.get('estimatedValueZar')),complexity:v.get('complexity'),urgency:v.get('urgency'),province:v.get('province'),location:v.get('location'),requiredTrades:procurementLines(v.get('requiredTrades')),requiredSpecialists:procurementLines(v.get('requiredSpecialists')),requiredReturnables:procurementLines(v.get('requiredReturnables')),evaluationCriteria:weights,documentRevisionIds:[...f.elements.documentRevisionIds.selectedOptions].map(x=>x.value).filter(Boolean),municipalReadinessScore:Number(v.get('municipalReadinessScore')),deadlineAt:new Date(v.get('deadlineAt')).toISOString()});m.textContent='Draft package created.';await hydrateProcurementWorkspace();}catch(e){m.textContent=e.message;}}
  async function selectProcurementPackage(id){procurementMatches=[];try{await loadProcurementPackage(id);}catch(e){showToast(e.message);}}window.selectProcurementPackage=selectProcurementPackage;
  async function issueProcurementPackage(event){event.preventDefault();const f=event.currentTarget,v=new FormData(f),m=f.querySelector('[role=status]');try{await api.post(`/procurement-packages/${activeProcurementPackageId}/issue`,{expectedVersion:procurementWorkspace.package.version,humanConfirmed:v.get('humanConfirmed')==='on',reason:v.get('reason')});await hydrateProcurementWorkspace();}catch(e){m.textContent=e.message;}}
  async function matchProcurementMarketplace(){try{procurementMatches=await api.post(`/procurement-packages/${activeProcurementPackageId}/matches`,{});renderProcurementActive();}catch(e){showToast(e.message);}}window.matchProcurementMarketplace=matchProcurementMarketplace;
  async function inviteProcurementListing(listingId){try{const invitation=await api.post(`/procurement-packages/${activeProcurementPackageId}/invitations`,{listingId,humanConfirmed:true});await loadProcurementPackage(activeProcurementPackageId);const share=document.getElementById('procurementInviteShare'),url=`${location.origin}${location.pathname}?procurement_token=${encodeURIComponent(invitation.accessToken)}`;share.innerHTML=`<div class="notice"><b>One-time bidder link created.</b><br>SMTP is not configured; copy this link through an approved channel. emailDeliveryClaimed=${invitation.emailDeliveryClaimed}<input class="form-input" readonly value="${escapeHtml(url)}"></div>`;}catch(e){showToast(e.message);}}window.inviteProcurementListing=inviteProcurementListing;
  async function issueProcurementAddendum(event){event.preventDefault();const f=event.currentTarget,v=new FormData(f),m=document.getElementById('procurementAddendumMessage');try{await api.post(`/procurement-packages/${activeProcurementPackageId}/addenda`,{title:v.get('title'),content:v.get('content'),reason:v.get('reason'),clarificationIds:v.getAll('clarificationIds'),humanConfirmed:v.get('humanConfirmed')==='on'});await loadProcurementPackage(activeProcurementPackageId);}catch(e){m.textContent=e.message;}}
  async function compareProcurementQuotes(){try{await api.post(`/procurement-packages/${activeProcurementPackageId}/comparisons`,{});await loadProcurementPackage(activeProcurementPackageId);}catch(e){showToast(e.message);}}window.compareProcurementQuotes=compareProcurementQuotes;
  async function recommendProcurementAward(event){event.preventDefault();const f=event.currentTarget,v=new FormData(f),m=document.getElementById('procurementRecommendationMessage');try{await api.post(`/procurement-packages/${activeProcurementPackageId}/award-recommendations`,{comparisonId:v.get('comparisonId'),quoteRevisionId:v.get('quoteRevisionId'),reason:v.get('reason'),riskNotes:procurementLines(v.get('riskNotes')),humanConfirmed:v.get('humanConfirmed')==='on'});await loadProcurementPackage(activeProcurementPackageId);}catch(e){m.textContent=e.message;}}
  async function approveProcurementAward(event){event.preventDefault();const f=event.currentTarget,v=new FormData(f),m=document.getElementById('procurementApprovalMessage');try{await api.post(`/procurement-award-recommendations/${v.get('recommendationId')}/approvals`,{approvalType:v.get('approvalType'),decision:v.get('decision'),approverCapacity:v.get('approverCapacity'),reason:v.get('reason'),humanConfirmed:v.get('humanConfirmed')==='on'});m.textContent='Separate decision recorded.';await loadProcurementPackage(activeProcurementPackageId);}catch(e){m.textContent=e.message;}}
  async function finaliseProcurementAward(event){event.preventDefault();const f=event.currentTarget,v=new FormData(f),m=document.getElementById('procurementFinaliseMessage');try{const result=await api.post(`/procurement-award-recommendations/${v.get('recommendationId')}/appointment-placeholder`,{humanConfirmed:v.get('humanConfirmed')==='on',reason:v.get('reason')});m.textContent=`${result.status}; signedAppointment=${result.signedAppointment}`;await loadProcurementPackage(activeProcurementPackageId);}catch(e){m.textContent=e.message;}}
  window.refreshProcurementWorkspace=hydrateProcurementWorkspace;
  async function renderPublicProcurementInvitation(token){enforceProductionControls(null);root.dataset.shellState='public-procurement';const main=document.getElementById('main'),nav=document.getElementById('navigator'),inspector=document.getElementById('inspectBody');if(nav)nav.innerHTML='<div class="nav-head"><div class="kicker">Secure bidder access</div><div class="nav-title">Procurement invitation</div><div class="nav-sub">This token is scoped to one bidder and one package.</div></div>';if(inspector)inspector.innerHTML='<div class="inspect-note"><b>Public-safe portal.</b><br>No buyer organisation data outside this invitation is loaded.</div>';try{const response=await fetch(`/api/v1/procurement-invitations/${encodeURIComponent(token)}`,{headers:{Accept:'application/json'},credentials:'same-origin'}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Invitation unavailable.');const x=payload.data;main.innerHTML=`<section id="publicProcurementInvitation" class="panel panel-pad" style="max-width:900px;margin:28px auto"><div class="trust-card-head"><div><h1>${escapeHtml(x.package.packageNumber)} · ${escapeHtml(x.package.title)}</h1><p>Invitation for ${escapeHtml(x.listing.name)} · deadline ${escapeHtml(x.package.deadlineAt)}</p></div><span class="status amber">${escapeHtml(x.status)}</span></div><div class="notice"><b>Fair tendering:</b> material answers appear as equal-information addenda. No automatic award and no email delivery are claimed.</div><p>${escapeHtml(x.package.scopeSummary)}</p><h2>Required returnables</h2><ul>${x.package.requiredReturnables.map(y=>`<li>${escapeHtml(y)}</li>`).join('')}</ul><div class="trust-list">${x.addenda.map(a=>`<article class="trust-row"><div><b>Addendum ${a.sequenceNumber} · ${escapeHtml(a.title)}</b><span>${escapeHtml(a.content)}</span><small>SHA-256 ${escapeHtml(a.snapshotSha256)}</small></div></article>`).join('')}</div>${x.status==='invited'?'<button id="procurementAcceptButton" class="btn dark" type="button">Accept invitation</button>':`<form id="publicProcurementClarification" class="scaffold-grid"><label class="trust-wide">Clarification question<textarea class="form-textarea" name="question" required></textarea></label><label class="trust-check"><input type="checkbox" name="material"> Material: the answer could affect scope, price, programme or fairness.</label><button class="btn ghost">Submit clarification</button><span role="status"></span></form><form id="publicProcurementQuote" class="scaffold-grid"><label>Price (R)<input class="form-input" type="number" name="priceZar" min="0.01" step="0.01" required></label><label>Lead time (weeks)<input class="form-input" type="number" name="leadTimeWeeks" min="0.01" step="0.01" required></label><fieldset class="proposal-terms trust-wide"><legend>Provided returnables</legend>${x.package.requiredReturnables.map(y=>`<label><input type="checkbox" name="providedReturnables" value="${escapeHtml(y)}"> ${escapeHtml(y)}</label>`).join('')}</fieldset><label>Exclusions<input class="form-input" name="exclusions" placeholder="One per line"></label><label>Qualifications<input class="form-input" name="qualifications" placeholder="One per line"></label><label class="trust-check"><input type="checkbox" name="conflictDeclared"> A conflict exists</label><label class="trust-wide">Conflict detail<input class="form-input" name="conflictDetail"></label><button class="btn dark">Submit immutable quote revision</button><span role="status"></span></form>`}</section>`;document.getElementById('procurementAcceptButton')?.addEventListener('click',async()=>{await publicProcurementPost(token,'accept',{});await renderPublicProcurementInvitation(token);});document.getElementById('publicProcurementClarification')?.addEventListener('submit',async e=>{e.preventDefault();const v=new FormData(e.currentTarget);try{await publicProcurementPost(token,'clarifications',{question:v.get('question'),material:v.get('material')==='on'});e.currentTarget.querySelector('[role=status]').textContent='Clarification submitted.';}catch(error){e.currentTarget.querySelector('[role=status]').textContent=error.message;}});document.getElementById('publicProcurementQuote')?.addEventListener('submit',async e=>{e.preventDefault();const v=new FormData(e.currentTarget);try{const quote=await publicProcurementPost(token,'quotes',{priceZar:Number(v.get('priceZar')),leadTimeWeeks:Number(v.get('leadTimeWeeks')),providedReturnables:v.getAll('providedReturnables'),exclusions:procurementLines(v.get('exclusions')),qualifications:procurementLines(v.get('qualifications')),conflictDeclared:v.get('conflictDeclared')==='on',conflictDetail:v.get('conflictDeclared')==='on'?v.get('conflictDetail'):null});e.currentTarget.querySelector('[role=status]').textContent=`Quote revision ${quote.revision} stored · SHA-256 ${quote.snapshotSha256}`;}catch(error){e.currentTarget.querySelector('[role=status]').textContent=error.message;}});}catch(error){main.innerHTML=`<section class="panel panel-pad"><div class="notice">${escapeHtml(error.message)}</div></section>`;}}
  async function publicProcurementPost(token,action,body){const response=await fetch(`/api/v1/procurement-invitations/${encodeURIComponent(token)}/${action}`,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Request failed.');return payload.data;}

  let financeWorkspaceState=null,financeAppointments=[];
  const financeMoney=cents=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(Number(cents||0)/100);
  function renderFinanceNavigator(title){const nav=document.getElementById('navigator'),project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);if(nav)nav.innerHTML=`<div class="nav-head"><div class="kicker">Commercial control</div><div class="nav-title">${escapeHtml(title)}</div><div class="nav-sub">${escapeHtml(project?.name||'No project selected')}</div></div><div class="back-row" onclick="openProjectSpace()"><span>←</span><span class="nav-label">Back to datum project space</span></div><div class="nav-section"><button class="nav-row active" onclick="document.getElementById('financeSummary')?.scrollIntoView({behavior:'smooth'})"><span class="nav-icon">${icon('payments_escrow',21)}</span><span class="nav-label">Commercial baseline</span></button><button class="nav-row" onclick="document.getElementById('financeWorkspaceBody')?.scrollIntoView({behavior:'smooth'})"><span class="nav-icon">${icon('valuation',21)}</span><span class="nav-label">Schedules & valuations</span></button><button class="nav-row" onclick="document.getElementById('financeWorkspaceBody')?.scrollIntoView({behavior:'smooth'})"><span class="nav-icon">${icon('contract_admin',21)}</span><span class="nav-label">Variations & claims</span></button><button class="nav-row" onclick="document.getElementById('financeWorkspaceBody')?.scrollIntoView({behavior:'smooth'})"><span class="nav-icon">${icon('audit_trail',21)}</span><span class="nav-label">Certificates & releases</span></button></div><div class="nav-note"><b>Provider boundary:</b><br>Architex records approvals and third-party references. It never holds funds or releases money automatically.</div>`;}
  function renderFinanceInspector(){const title=document.getElementById('inspectTitle'),sub=document.getElementById('inspectSub'),body=document.getElementById('inspectBody');if(title)title.textContent='Commercial evidence';if(sub)sub.textContent='MariaDB-backed controls';if(body)body.innerHTML='<div class="inspect-note"><b>Human approvals remain mandatory.</b><br>Contract sums, variations, claims, certificates, retention, release approvals and provider events remain separately auditable.</div><div class="inspect-block"><h4>Financial boundary</h4><p>Funds held by Architex: no<br>Automatic release: no<br>Unconfigured provider: blocked<br>Disputed certificate: locked<br>Provider-paid amount: webhook evidence only</p></div>';}
  function financeCommercialWorkspace(){const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);if(!project)return '<div id="financeCommercialWorkspace"><div class="notice"><b>Project required:</b> Select a project before opening commercial control.</div></div>';return `<div id="financeCommercialWorkspace" class="procurement-workspace"><div class="notice"><b>Third-party provider boundary:</b> Architex records contract sums, claims, certificates, approvals, disputes and provider references. It never holds client funds and does not act as an escrow, wallet, trust-account, EFT/card, payout or financial-services provider. No automatic release is permitted. Unconfigured requests remain <code>provider_configuration_required</code>.</div><div id="financeWorkspaceBody"><div class="notice">Loading finance and commercial records…</div></div></div>`;}
  async function hydrateFinanceWorkspace(){const root=document.getElementById('financeCommercialWorkspace'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root||!projectId)return;try{[financeWorkspaceState,financeAppointments]=await Promise.all([api.get(`/projects/${encodeURIComponent(projectId)}/finance-workspace`),api.get('/appointments')]);renderFinanceWorkspace();}catch(error){document.getElementById('financeWorkspaceBody').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function renderFinanceWorkspace(){const root=document.getElementById('financeWorkspaceBody'),w=financeWorkspaceState,projectId=window.__ARCHITEX_SHELL_STATE__.selectedProjectId;if(!root||!w)return;const appointments=financeAppointments.filter(x=>x.projectId===projectId&&x.formallyIssuedAt);if(!w.baseline){root.innerHTML=`<form id="financeBaselineForm" class="panel panel-pad"><div class="trust-card-head"><div><h2>Commercial baseline</h2><p>Bind a human-confirmed contract amount to a formally issued appointment.</p></div><span class="status amber">Formal source required</span></div>${appointments.length?`<div class="scaffold-grid"><label>Formally issued appointment<select class="form-select" name="appointmentId" required>${appointments.map(x=>`<option value="${escapeHtml(x.id)}">Revision ${x.revision} · ${escapeHtml(x.formalIssueReason||'issued appointment')}</option>`).join('')}</select></label><label>Contract sum (R)<input class="form-input" name="contractSum" type="number" min="0.01" step="0.01" required></label><label>Contingency (R)<input class="form-input" name="contingency" type="number" min="0" step="0.01" value="0" required></label><label>Retention (%)<input class="form-input" name="retentionPercent" type="number" min="0" max="20" step="0.01" value="5" required></label><label class="trust-check"><input type="checkbox" name="vatIncluded" required> Contract sum includes VAT.</label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> I checked the exact source and commercial amount.</label><label class="trust-wide">Reason<input class="form-input" name="reason" required value="Client reviewed the formally issued source and exact commercial amount."></label></div><div class="trust-actions"><button class="btn dark">Create immutable baseline</button><span role="status"></span></div>`:'<div class="notice"><b>Blocked:</b> This project has no formally issued professional appointment. Complete professional confirmation and formal issue before creating a baseline.</div>'}</form>`;document.getElementById('financeBaselineForm')?.addEventListener('submit',createFinanceBaseline);return;}const b=w.baseline,currentSchedule=w.schedules.find(x=>x),certificateIds=new Set(w.certificates.map(x=>x.certificateRevisionId)),releaseCertificateIds=new Set(w.releaseRequests.map(x=>x.certificateRevisionId));root.innerHTML=`<section id="financeSummary" class="panel panel-pad"><div class="trust-card-head"><div><h2>${escapeHtml(w.projectName)} · commercial control</h2><p>Baseline revision ${b.revision} · ${escapeHtml(b.currency)} · SHA-256 ${escapeHtml(b.snapshotSha256)}</p></div><span class="status green">Active</span></div><div class="summary-grid"><div><span>Original contract</span><b>${financeMoney(b.originalContractSumCents)}</b></div><div><span>Current contract</span><b>${financeMoney(b.currentContractSumCents)}</b></div><div><span>Retention held</span><b>${financeMoney(w.retention?.heldToDateCents)}</b></div><div><span>Provider-paid</span><b>${financeMoney(w.releaseRequests.reduce((sum,x)=>sum+x.providerPaidCents,0))}</b></div></div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Payment schedule</h2><p>Milestones must reconcile exactly to the current contract sum.</p></div><span class="status ${currentSchedule?'green':'amber'}">${currentSchedule?'Issued':'Required'}</span></div>${currentSchedule?`<div class="trust-list">${currentSchedule.milestones.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.label)}</b><span>${financeMoney(x.amountCents)}</span><small>Due ${escapeHtml(x.dueDate)}</small></div></article>`).join('')}</div>`:`<form id="financeScheduleForm" class="scaffold-grid"><label class="trust-wide">Title<input class="form-input" name="title" value="Construction payment schedule" required></label><label class="trust-wide">Milestones: label | amount in rand | YYYY-MM-DD<textarea class="form-textarea" name="milestones" required>Mobilisation | ${(b.currentContractSumCents/100).toFixed(2)} | ${new Date(Date.now()+30*86400000).toISOString().slice(0,10)}</textarea></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Human-reviewed schedule.</label><label class="trust-wide">Reason<input class="form-input" name="reason" required value="QS and client reviewed milestone values and dates."></label><button class="btn dark">Issue schedule</button><span role="status"></span></form>`}</section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Variations</h2><p>Draft → review → separate QS, lead-professional and client approvals.</p></div><span class="status amber">No automatic contract change</span></div><form id="financeVariationForm" class="scaffold-grid"><label>Reference<input class="form-input" name="reference" required></label><label>Title<input class="form-input" name="title" required></label><label>Amount (R; negative allowed)<input class="form-input" type="number" step="0.01" name="amount" required></label><label>Time impact (days)<input class="form-input" type="number" name="timeImpactDays" value="0" required></label><label class="trust-wide">Description<textarea class="form-textarea" name="description" required></textarea></label><button class="btn dark">Create draft variation</button><span role="status"></span></form><div class="trust-list">${w.variations.length?w.variations.map(financeVariationRow).join(''):'<div class="notice">No variations recorded.</div>'}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Claims and certificates</h2><p>Claimed, certified, retained, previous, disputed and net amounts remain separate.</p></div><span class="status amber">QS certification</span></div>${currentSchedule?`<form id="financeClaimForm" class="scaffold-grid"><label>Claim number<input class="form-input" name="claimNumber" required></label><label>Claimed to date (R)<input class="form-input" name="claimedToDate" type="number" min="0.01" step="0.01" required></label><label>Milestone<select class="form-select" name="milestoneId">${currentSchedule.milestones.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.label)}</option>`).join('')}</select></label><label class="trust-check"><input type="checkbox" name="disputed"> Unresolved dispute exists.</label><label class="trust-wide">Evidence references, one per line<textarea class="form-textarea" name="evidence" required placeholder="record:site-progress-001"></textarea></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Cumulative claim and evidence checked.</label><label class="trust-wide">Reason<input class="form-input" name="reason" required></label><button class="btn dark">Submit immutable claim</button><span role="status"></span></form>`:'<div class="notice">Issue a payment schedule before claims.</div>'}<div class="trust-list">${w.claims.length?w.claims.map(x=>financeClaimRow(x,w.certificates)).join(''):'<div class="notice">No claims recorded.</div>'}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Third-party financial providers</h2><p>Registry metadata only. Secrets are never returned; a registry row does not prove live configuration.</p></div><span class="status amber">${w.providers.some(x=>x.liveConfigured)?'Connector verified':'Configuration required'}</span></div><form id="financeProviderForm" class="scaffold-grid"><label>Provider key<input class="form-input" name="providerKey" required></label><label>Name<input class="form-input" name="name" autocomplete="organization" required></label><label>Type<select class="form-select" name="providerType"><option value="payment_provider">Payment provider</option><option value="escrow_provider">Escrow provider</option><option value="trust_account_provider">Trust-account provider</option></select></label><label class="trust-check"><input type="checkbox" name="registered" required> Registration independently checked.</label><label class="trust-wide">Capabilities<label><input type="checkbox" name="capabilities" value="release" checked> release</label> <label><input type="checkbox" name="capabilities" value="webhook_status" checked> webhook status</label> <label><input type="checkbox" name="capabilities" value="escrow_hold"> escrow hold</label> <label><input type="checkbox" name="capabilities" value="payout"> payout</label></label><button class="btn dark">Register candidate</button><span role="status"></span></form><div class="trust-list">${w.providers.length?w.providers.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.name)}</b><span>${escapeHtml(x.providerType.replaceAll('_',' '))} · ${x.capabilities.map(escapeHtml).join(', ')}</span><small>registered=${x.registered} · liveConfigured=${x.liveConfigured} · fundsHeldByArchitex=false</small></div><span class="status ${x.liveConfigured?'green':'amber'}">${x.liveConfigured?'Live verified':'Not configured'}</span></article>`).join(''):'<div class="notice">No registered provider candidates.</div>'}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Release requests</h2><p>Client and lead-professional approvals are recorded separately. Disputes lock release.</p></div><span class="status amber">Provider mediated only</span></div><div class="trust-list">${w.certificates.map(x=>financeCertificateRow(x,w.providers,releaseCertificateIds)).join('')||'<div class="notice">No payment certificates available.</div>'}${w.releaseRequests.map(financeReleaseRow).join('')}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Cashflow forecast</h2><p>Immutable advisory snapshot from the issued schedule, certificates, retention and provider-confirmed payments.</p></div><button class="btn ghost" type="button" onclick="createFinanceCashflow()">Create snapshot</button></div>${w.cashflowSnapshots.length?financeCashflowRow(w.cashflowSnapshots[0]):'<div class="notice">No cashflow snapshot yet.</div>'}</section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Retention release</h2><p>Completion evidence, lead-professional approval, client approval and a configured third-party provider are separate gates.</p></div><span class="status amber">No automatic release</span></div>${w.retention?.heldToDateCents>0&&w.providers.length?`<form id="financeRetentionReleaseForm" class="scaffold-grid"><label>Amount (R)<input class="form-input" name="amount" type="number" min="0.01" step="0.01" max="${w.retention.heldToDateCents/100}" required></label><label>Provider<select class="form-select" name="providerId">${w.providers.map(p=>`<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('')}</select></label><label class="trust-wide">Completion certificate reference<input class="form-input" name="completionCertificateReference" required placeholder="record:practical-completion-001"></label><label class="trust-check"><input type="checkbox" name="defectsLiabilityCompleted" required> Defects-liability condition is complete.</label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Exact evidence and amount checked.</label><label class="trust-wide">Reason<input class="form-input" name="reason" required></label><button class="btn dark">Prepare retention release</button><span role="status"></span></form>`:'<div class="notice">Retention balance and a registered provider candidate are required.</div>'}<div class="trust-list">${w.retentionReleaseRequests.map(financeRetentionReleaseRow).join('')}</div></section>`;bindFinanceWorkspace();}
  function financeVariationRow(x){return `<article class="trust-row"><div><b>${escapeHtml(x.reference)} · ${escapeHtml(x.title)}</b><span>${financeMoney(x.amountCents)} · ${x.timeImpactDays} days · ${escapeHtml(x.status.replaceAll('_',' '))}</span><small>${x.approvals.map(a=>a.approvalType+': '+a.decision).join(' · ')||'No approvals'}</small></div><div class="trust-row-actions">${x.status==='draft'?`<button class="btn ghost" onclick="submitFinanceVariation('${x.id}',${x.version})">Submit</button>`:''}${x.status==='under_review'?`<button class="btn ghost" onclick="approveFinanceVariation('${x.id}','quantity_surveyor')">QS approve</button><button class="btn ghost" onclick="approveFinanceVariation('${x.id}','lead_professional')">Lead approve</button><button class="btn ghost" onclick="approveFinanceVariation('${x.id}','client')">Client approve</button>`:''}</div></article>`;}
  function financeClaimRow(x,certificates){const cert=certificates.find(c=>c.claimId===x.claimId);return `<article class="trust-row"><div><b>${escapeHtml(x.claimNumber)} · ${financeMoney(x.claimedToDateCents)}</b><span>${escapeHtml(x.status.replaceAll('_',' '))} · disputed=${x.disputed}</span><small>${x.evidenceReferences.map(escapeHtml).join(' · ')}</small></div>${!cert?`<form class="finance-certify-form trust-row-actions" data-claim="${x.claimId}"><input class="form-input" type="number" step="0.01" min="0" name="gross" aria-label="Gross certified to date" placeholder="Gross certified R" required><input class="form-input" type="number" step="0.01" min="0" name="deductions" aria-label="Other deductions" value="0" required><button class="btn dark">QS certify</button><span role="status"></span></form>`:''}</article>${cert?`<article class="trust-row"><div><b>Certificate revision ${cert.revision}</b><span>Gross ${financeMoney(cert.grossCertifiedToDateCents)} · retention ${financeMoney(cert.retentionHeldToDateCents)} · previous ${financeMoney(cert.previousCertifiedPaymentsCents)} · net ${financeMoney(cert.netPayableCents)}</span><small>Disputed ${financeMoney(cert.disputedAmountCents)} · ${escapeHtml(cert.status)} · SHA-256 ${escapeHtml(cert.snapshotSha256||'')}</small></div></article>`:''}`;}
  function financeCertificateRow(x,providers,used){if(used.has(x.certificateRevisionId))return '';return `<article class="trust-row"><div><b>Certified net ${financeMoney(x.netPayableCents)}</b><span>${escapeHtml(x.status.replaceAll('_',' '))}</span><small>Provider-paid remains R0.00 until a verified webhook.</small></div>${providers.length?`<form class="finance-release-form trust-row-actions" data-revision="${x.certificateRevisionId}"><select class="form-select" name="providerId">${providers.map(p=>`<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('')}</select><button class="btn dark">Prepare release</button><span role="status"></span></form>`:'<span class="status amber">Register provider first</span>'}</article>`;}
  function financeReleaseRow(x){return `<article class="trust-row"><div><b>Release ${financeMoney(x.requestedAmountCents)}</b><span>${escapeHtml(x.status.replaceAll('_',' '))} · provider paid ${financeMoney(x.providerPaidCents)}</span><small>fundsHeldByArchitex=false · providerReference=${escapeHtml(x.providerReference||'not submitted')}</small></div><div class="trust-row-actions">${!['rejected','provider_confirmed_paid','submitted_to_provider'].includes(x.status)?`<button class="btn ghost" onclick="approveFinanceRelease('${x.id}','lead_professional')">Lead approve</button><button class="btn ghost" onclick="approveFinanceRelease('${x.id}','client')">Client approve</button>`:''}</div></article>`;}
  function financeCashflowRow(x){return `<div class="summary-grid"><div><span>Scheduled</span><b>${financeMoney(x.scheduledTotalCents)}</b></div><div><span>Gross certified</span><b>${financeMoney(x.grossCertifiedToDateCents)}</b></div><div><span>Provider paid</span><b>${financeMoney(x.providerPaidToDateCents)}</b></div><div><span>Remaining contract</span><b>${financeMoney(x.remainingContractValueCents)}</b></div></div><div class="notice">Advisory only · certified awaiting provider payment ${financeMoney(x.certifiedAwaitingProviderPaymentCents)}</div>`;}
  function financeRetentionReleaseRow(x){return `<article class="trust-row"><div><b>Retention ${financeMoney(x.requestedAmountCents)}</b><span>${escapeHtml(x.status.replaceAll('_',' '))} · provider paid ${financeMoney(x.providerPaidCents)}</span><small>${escapeHtml(x.conditions.completionCertificateReference||'')} · fundsHeldByArchitex=false</small></div><div class="trust-row-actions">${!['rejected','provider_confirmed_paid','submitted_to_provider'].includes(x.status)?`<button class="btn ghost" onclick="approveFinanceRetentionRelease('${x.id}','lead_professional')">Lead approve</button><button class="btn ghost" onclick="approveFinanceRetentionRelease('${x.id}','client')">Client approve</button>`:''}</div></article>`;}
  function bindFinanceWorkspace(){document.getElementById('financeScheduleForm')?.addEventListener('submit',createFinanceSchedule);document.getElementById('financeVariationForm')?.addEventListener('submit',createFinanceVariation);document.getElementById('financeClaimForm')?.addEventListener('submit',createFinanceClaim);document.getElementById('financeProviderForm')?.addEventListener('submit',createFinanceProvider);document.getElementById('financeRetentionReleaseForm')?.addEventListener('submit',createFinanceRetentionRelease);document.querySelectorAll('.finance-certify-form').forEach(form=>form.addEventListener('submit',certifyFinanceClaim));document.querySelectorAll('.finance-release-form').forEach(form=>form.addEventListener('submit',createFinanceRelease));}
  async function financeSubmit(form,operation){const status=form.querySelector('[role=status]');if(status)status.textContent='Saving…';try{await operation(new FormData(form));if(status)status.textContent='Persisted.';await hydrateFinanceWorkspace();}catch(error){if(status)status.textContent=error.message;else showToast(error.message);}}
  function cents(value){const number=Number(value);if(!Number.isFinite(number))throw new Error('Enter a valid amount.');return Math.round(number*100);}
  async function createFinanceBaseline(event){event.preventDefault();const form=event.currentTarget;await financeSubmit(form,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/commercial-baselines`,{appointmentId:v.get('appointmentId'),contractSumCents:cents(v.get('contractSum')),currency:'ZAR',vatIncluded:v.get('vatIncluded')==='on',contingencyCents:cents(v.get('contingency')),retentionBasisPoints:Math.round(Number(v.get('retentionPercent'))*100),humanConfirmed:v.get('humanConfirmed')==='on',reason:v.get('reason')}));}
  async function createFinanceSchedule(event){event.preventDefault();const form=event.currentTarget;await financeSubmit(form,v=>{const milestones=String(v.get('milestones')).split(/\r?\n/).filter(Boolean).map(line=>{const[label,amount,dueDate]=line.split('|').map(x=>x.trim());return{label,amountCents:cents(amount),dueDate};});return api.post(`/commercial-baselines/${financeWorkspaceState.baseline.id}/payment-schedules`,{title:v.get('title'),milestones,humanConfirmed:v.get('humanConfirmed')==='on',reason:v.get('reason')});});}
  async function createFinanceVariation(event){event.preventDefault();const form=event.currentTarget;await financeSubmit(form,v=>api.post(`/commercial-baselines/${financeWorkspaceState.baseline.id}/variations`,{reference:v.get('reference'),title:v.get('title'),description:v.get('description'),amountCents:cents(v.get('amount')),timeImpactDays:Number(v.get('timeImpactDays'))}));}
  window.submitFinanceVariation=async(id,version)=>{try{await api.post(`/commercial-variations/${id}/submit`,{expectedVersion:version,humanConfirmed:true,reason:'Exact scope, cost and time impact submitted for separate human review.'});await hydrateFinanceWorkspace();}catch(error){showToast(error.message);}};
  window.approveFinanceVariation=async(id,type)=>{try{await api.post(`/commercial-variations/${id}/approvals`,{approvalType:type,decision:'approved',humanConfirmed:true,reason:`Authorised ${type.replaceAll('_',' ')} reviewed the exact variation.`});await hydrateFinanceWorkspace();}catch(error){showToast(error.message);}};
  async function createFinanceClaim(event){event.preventDefault();const form=event.currentTarget;await financeSubmit(form,v=>api.post(`/commercial-baselines/${financeWorkspaceState.baseline.id}/claims`,{claimNumber:v.get('claimNumber'),claimedToDateCents:cents(v.get('claimedToDate')),milestoneId:v.get('milestoneId'),evidenceReferences:String(v.get('evidence')).split(/\r?\n/).map(x=>x.trim()).filter(Boolean),disputed:v.get('disputed')==='on',humanConfirmed:v.get('humanConfirmed')==='on',reason:v.get('reason')}));}
  async function certifyFinanceClaim(event){event.preventDefault();const form=event.currentTarget;await financeSubmit(form,v=>api.post(`/commercial-claims/${form.dataset.claim}/certificates`,{grossCertifiedToDateCents:cents(v.get('gross')),otherDeductionsCents:cents(v.get('deductions')),humanConfirmed:true,reason:'Quantity surveyor reviewed measured work, evidence, retention and previous certified payments.'}));}
  async function createFinanceProvider(event){event.preventDefault();const form=event.currentTarget;await financeSubmit(form,v=>api.post('/financial-providers',{providerKey:v.get('providerKey'),name:v.get('name'),providerType:v.get('providerType'),registered:v.get('registered')==='on',capabilities:v.getAll('capabilities'),configurationReference:null}));}
  async function createFinanceRelease(event){event.preventDefault();const form=event.currentTarget;await financeSubmit(form,v=>api.post(`/payment-certificates/${form.dataset.revision}/release-requests`,{providerId:v.get('providerId'),humanConfirmed:true,reason:'Prepare a provider-mediated request only; Architex does not hold or release funds.'}));}
  window.approveFinanceRelease=async(id,type)=>{try{await api.post(`/provider-release-requests/${id}/approvals`,{approvalType:type,decision:'approved',humanConfirmed:true,reason:`Authorised ${type.replaceAll('_',' ')} reviewed the exact certificate and requested amount.`});await hydrateFinanceWorkspace();}catch(error){showToast(error.message);}};
  window.createFinanceCashflow=async()=>{try{await api.post(`/commercial-baselines/${financeWorkspaceState.baseline.id}/cashflow-snapshots`,{humanConfirmed:true,reason:'Project team reviewed the current schedule, certificates, retention and provider-paid facts.'});await hydrateFinanceWorkspace();}catch(error){showToast(error.message);}};
  async function createFinanceRetentionRelease(event){event.preventDefault();const form=event.currentTarget;await financeSubmit(form,v=>api.post(`/commercial-baselines/${financeWorkspaceState.baseline.id}/retention-release-requests`,{providerId:v.get('providerId'),requestedAmountCents:cents(v.get('amount')),defectsLiabilityCompleted:v.get('defectsLiabilityCompleted')==='on',completionCertificateReference:v.get('completionCertificateReference'),humanConfirmed:v.get('humanConfirmed')==='on',reason:v.get('reason')}));}
  window.approveFinanceRetentionRelease=async(id,type)=>{try{await api.post(`/retention-release-requests/${id}/approvals`,{approvalType:type,decision:'approved',humanConfirmed:true,reason:`Authorised ${type.replaceAll('_',' ')} reviewed the completion evidence and exact retention amount.`});await hydrateFinanceWorkspace();}catch(error){showToast(error.message);}};
  window.refreshFinanceWorkspace=hydrateFinanceWorkspace;

  let siteExecutionState=null;
  const siteTools=['site_diary','rfis','quality','issues_rfis','itp','site_instructions','ncr_manager','snag_manager'];
  const siteLines=value=>String(value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  function siteExecutionWorkspace(){const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);if(!project)return '<div id="siteExecutionWorkspace"><div class="notice"><b>Project required:</b> Select a project before opening Site Execution.</div></div>';return `<div id="siteExecutionWorkspace" class="procurement-workspace"><div class="notice"><b>Controlled field record:</b> No automatic EOT or variation entitlement. Internal inspection is not statutory approval. Payment blockers are recommendations only and never move money. Formal instructions and sign-off records require an authorised human.</div><div id="siteExecutionBody"><div class="notice">Loading MariaDB-backed site records…</div></div></div>`;}
  function renderSiteNavigator(){const nav=document.getElementById('navigator'),project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);if(!nav)return;nav.innerHTML=`<div class="nav-head"><div class="kicker">Construction execution</div><div class="nav-title">Site & field control</div><div class="nav-sub">${escapeHtml(project?.name||'No project selected')}</div></div><div class="back-row" onclick="openProjectSpace()"><span>←</span><span class="nav-label">Back to datum project space</span></div><div class="nav-section"><button class="nav-row active" onclick="document.getElementById('siteDailyLog')?.scrollIntoView({behavior:'smooth'})"><span class="nav-icon">${icon('site_diary',21)}</span><span class="nav-label">Daily site log</span></button><button class="nav-row" onclick="document.getElementById('siteRfis')?.scrollIntoView({behavior:'smooth'})"><span class="nav-icon">${icon('rfi',21)}</span><span class="nav-label">RFIs & instructions</span></button><button class="nav-row" onclick="document.getElementById('siteQuality')?.scrollIntoView({behavior:'smooth'})"><span class="nav-icon">${icon('ncr_manager',21)}</span><span class="nav-label">NCR & snags</span></button><button class="nav-row" onclick="document.getElementById('siteInspections')?.scrollIntoView({behavior:'smooth'})"><span class="nav-icon">${icon('inspection',21)}</span><span class="nav-label">Inspections & delays</span></button></div><div class="nav-note"><b>Evidence boundary:</b><br>Photos, files and location metadata remain private to this organisation and project.</div>`;}
  function renderSiteInspector(){const title=document.getElementById('inspectTitle'),sub=document.getElementById('inspectSub'),body=document.getElementById('inspectBody');if(title)title.textContent='Field-control evidence';if(sub)sub.textContent='MariaDB-backed controls';if(body)body.innerHTML='<div class="inspect-note"><b>Human authority remains mandatory.</b><br>Issued instructions are superseded, never silently edited. Candidate inspections require professional supervision.</div><div class="inspect-block"><h4>Contract boundaries</h4><p>Automatic EOT: no<br>Automatic variation: no<br>Statutory approval implied: no<br>Payment movement: no<br>Project/tenant scope: enforced</p></div>';}
  async function hydrateSiteExecution(){const root=document.getElementById('siteExecutionBody'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root||!projectId)return;try{siteExecutionState=await api.get(`/projects/${encodeURIComponent(projectId)}/site-execution-workspace`);renderSiteExecution();}catch(error){root.innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function siteStatus(value){return escapeHtml(String(value||'').replaceAll('_',' '));}
  function renderSiteExecution(){const root=document.getElementById('siteExecutionBody'),w=siteExecutionState;if(!root||!w)return;const projectId=window.__ARCHITEX_SHELL_STATE__.selectedProjectId;root.innerHTML=`
    <section id="siteDailyLog" class="panel panel-pad"><div class="trust-card-head"><div><h2>Daily site log</h2><p>Weather, labour, plant, deliveries, visitors, delays, safety notes and linked evidence.</p></div><span class="status green">${w.dailyLogs.length} logs</span></div><form id="siteDailyLogForm" class="scaffold-grid"><label>Date<input class="form-input" type="date" name="logDate" required></label><label>Weather<input class="form-input" name="weather" required maxlength="1000"></label><label class="trust-wide">Labour · one role|count per line<textarea class="form-textarea" name="labour" placeholder="main_contractor|12"></textarea></label><label>Plant · one per line<textarea class="form-textarea" name="plant"></textarea></label><label>Deliveries<textarea class="form-textarea" name="deliveries"></textarea></label><label>Visitors<textarea class="form-textarea" name="visitors"></textarea></label><label>Delay notes<textarea class="form-textarea" name="delays"></textarea></label><label class="trust-wide">Safety notes<textarea class="form-textarea" name="safetyNotes"></textarea></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed this exact daily record for submission.</label><button class="btn dark">Submit daily log</button><span role="status"></span></form><div class="trust-list">${w.dailyLogs.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.logDate)} · ${escapeHtml(x.weather)}</b><span>${siteStatus(x.status)} · labour ${Object.values(x.labour||{}).reduce((a,b)=>a+Number(b),0)}</span><small>${(x.delays||[]).map(escapeHtml).join(' · ')||'No delays recorded'}</small></div></article>`).join('')||'<div class="notice">No daily logs yet.</div>'}</div>
    <form id="siteEvidenceForm" class="scaffold-grid"><label>Linked daily log<select class="form-select" name="dailyLogId"><option value="">Unlinked project evidence</option>${w.dailyLogs.map(x=>`<option value="${x.id}">${escapeHtml(x.logDate)}</option>`).join('')}</select></label><label>Evidence type<select class="form-select" name="evidenceType"><option value="photo">Photo</option><option value="delivery_note">Delivery note</option><option value="weather_report">Weather report</option><option value="drawing">Drawing</option><option value="specification">Specification</option><option value="file">File</option></select></label><label>Title<input class="form-input" name="title" required maxlength="220"></label><label>Private file<input class="form-input" type="file" name="file"></label><label>Location<input class="form-input" name="locationLabel" maxlength="500"></label><label>POPIA classification<select class="form-select" name="popiaClassification"><option value="project_team">Project team</option><option value="restricted">Restricted</option><option value="personal_information">Personal information</option></select></label><label>Latitude<input class="form-input" type="number" step="0.0000001" name="latitude"></label><label>Longitude<input class="form-input" type="number" step="0.0000001" name="longitude"></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I confirm the project scope, location metadata and processing classification.</label><button class="btn dark">Capture field evidence</button><span role="status"></span></form><div class="trust-list">${w.evidence.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.title)}</b><span>${siteStatus(x.evidenceType)} · ${siteStatus(x.popiaClassification)}</span><small>${escapeHtml(x.locationLabel||'No location')}</small></div></article>`).join('')}</div></section>
    <section id="siteRfis" class="panel panel-pad"><div class="trust-card-head"><div><h2>RFI register</h2><p>Open, overdue, responded and closed questions with controlled professional responses.</p></div><button class="btn ghost" type="button" onclick="siteMarkRfisOverdue()">Check SLA</button></div><form id="siteRfiForm" class="scaffold-grid"><label>Subject<input class="form-input" name="subject" required maxlength="220"></label><label>Discipline<select class="form-select" name="discipline"><option value="architectural">Architectural</option><option value="structural">Structural</option><option value="civil">Civil</option><option value="electrical">Electrical</option><option value="mechanical">Mechanical</option><option value="quantity_surveying">Quantity surveying</option></select></label><label class="trust-wide">Question<textarea class="form-textarea" name="question" required></textarea></label><label>Due date/time<input class="form-input" type="datetime-local" name="dueAt" required></label><label class="trust-wide">Controlled document IDs · one per line<textarea class="form-textarea" name="linkedDocumentIds"></textarea></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Submit this exact question to the discipline route.</label><button class="btn dark">Create RFI</button><span role="status"></span></form><div class="trust-list">${w.rfis.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.subject)}</b><span>${siteStatus(x.status)} · due ${escapeHtml(x.dueAt)}</span><small>${escapeHtml(x.response?.answer||x.question)}</small></div><div class="trust-row-actions">${['open','overdue'].includes(x.status)?`<button class="btn dark" type="button" onclick="siteRespondRfi('${x.id}')">Respond</button>`:''}${x.status==='responded'?`<button class="btn ghost" type="button" onclick="siteCloseRfi('${x.id}')">Close</button>`:''}</div></article>`).join('')||'<div class="notice">No RFIs yet.</div>'}</div>
    <div class="trust-card-head"><div><h2>Site instructions</h2><p>Draft, authorised issue, contractor acknowledgement and immutable supersession.</p></div></div><form id="siteInstructionForm" class="scaffold-grid"><label>Title<input class="form-input" name="title" required maxlength="220"></label><label>Linked RFI<select class="form-select" name="linkedRfiId"><option value="">None</option>${w.rfis.map(x=>`<option value="${x.id}">${escapeHtml(x.subject)}</option>`).join('')}</select></label><label class="trust-wide">Instruction<textarea class="form-textarea" name="instruction" required></textarea></label><label>Cost impact<select class="form-select" name="costImpact"><option value="none">None</option><option value="possible">Possible</option><option value="confirmed">Confirmed</option></select></label><label>Time impact<select class="form-select" name="timeImpact"><option value="none">None</option><option value="possible">Possible</option><option value="confirmed">Confirmed</option></select></label><button class="btn dark">Create controlled draft</button><span role="status"></span></form><div class="trust-list">${w.siteInstructions.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.title)}</b><span>${siteStatus(x.status)} · cost ${siteStatus(x.costImpact)} · time ${siteStatus(x.timeImpact)}</span><small>Variation review flag: ${x.variationFlag?'yes':'no'}</small></div><div class="trust-row-actions">${x.status==='draft'?`<button class="btn dark" onclick="siteIssueInstruction('${x.id}')">Issue</button>`:''}${x.status==='issued'?`<button class="btn ghost" onclick="siteAcknowledgeInstruction('${x.id}')">Acknowledge</button>`:''}${['issued','acknowledged'].includes(x.status)?`<button class="btn ghost" onclick="siteSupersedeInstruction('${x.id}')">Supersede</button>`:''}</div></article>`).join('')||'<div class="notice">No site instructions yet.</div>'}</div></section>
    <section id="siteQuality" class="panel panel-pad"><div class="trust-card-head"><div><h2>NCR and snag quality control</h2><p>Corrective evidence, professional verification, reinspection and optional finance blockers.</p></div></div><form id="siteNcrForm" class="scaffold-grid"><label>Title<input class="form-input" name="title" required maxlength="220"></label><label>Severity<select class="form-select" name="severity"><option>low</option><option>medium</option><option>high</option><option>critical</option></select></label><label>Responsible party<input class="form-input" name="responsibleParty" required></label><label class="trust-wide">Description<textarea class="form-textarea" name="description" required></textarea></label><label>Evidence<select class="form-select" name="evidenceIds" multiple>${w.evidence.map(x=>`<option value="${x.id}">${escapeHtml(x.title)}</option>`).join('')}</select></label><label class="trust-check"><input type="checkbox" name="blocksPayment"> Recommend payment blocker</label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed this NCR and its linked evidence.</label><button class="btn dark">Create NCR</button><span role="status"></span></form><div class="trust-list">${w.ncrs.map(x=>siteQualityRow(x,'ncr')).join('')||'<div class="notice">No NCRs yet.</div>'}</div>
    <form id="siteSnagForm" class="scaffold-grid"><label>Location<input class="form-input" name="location" required maxlength="500"></label><label>Priority<select class="form-select" name="priority"><option>low</option><option>medium</option><option>high</option><option>critical</option></select></label><label>Responsible party<input class="form-input" name="responsibleParty" required></label><label>Due date/time<input class="form-input" type="datetime-local" name="dueAt" required></label><label class="trust-wide">Description<textarea class="form-textarea" name="description" required></textarea></label><label>Evidence<select class="form-select" name="evidenceIds" multiple>${w.evidence.map(x=>`<option value="${x.id}">${escapeHtml(x.title)}</option>`).join('')}</select></label><label class="trust-check"><input type="checkbox" name="blocksPayment"> Recommend payment blocker</label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed this snag and allocation details.</label><button class="btn dark">Create snag</button><span role="status"></span></form><div class="trust-list">${w.snags.map(x=>siteQualityRow(x,'snag')).join('')||'<div class="notice">No snags yet.</div>'}</div></section>
    <section id="siteInspections" class="panel panel-pad"><div class="trust-card-head"><div><h2>Inspections, delays and programme impact</h2><p>Internal checklists and evidence-first notices; no statutory or entitlement claim.</p></div></div><form id="siteInspectionForm" class="scaffold-grid"><label>Inspection type<select class="form-select" name="inspectionType"><option>architectural</option><option>structural</option><option>quality</option><option>safety</option><option>municipal</option><option>progress</option></select></label><label>Findings · one per line<textarea class="form-textarea" name="findings"></textarea></label><label>Follow-ups · one per line<textarea class="form-textarea" name="followUps"></textarea></label><label>Checklist · item|pass/fail/not_applicable<textarea class="form-textarea" name="checklist"></textarea></label><label class="trust-check"><input type="checkbox" name="signOffRequired"> Professional sign-off required</label><button class="btn dark">Create inspection draft</button><span role="status"></span></form><div class="trust-list">${w.inspections.map(x=>`<article class="trust-row"><div><b>${siteStatus(x.inspectionType)} inspection</b><span>${siteStatus(x.status)} · statutory approval: no</span><small>${(x.findings||[]).map(escapeHtml).join(' · ')||'No adverse findings'}</small></div><div class="trust-row-actions">${x.status==='draft'?`<button class="btn dark" onclick="siteIssueInspection('${x.id}')">Issue</button>`:''}${['issued','requires_follow_up'].includes(x.status)?`<button class="btn ghost" onclick="siteCloseInspection('${x.id}')">Close</button>`:''}${!['closed'].includes(x.status)?`<button class="btn ghost" onclick="siteCreateBlocker('inspection','${x.id}')">Block payment recommendation</button>`:''}</div></article>`).join('')||'<div class="notice">No inspections yet.</div>'}</div>
    <div class="trust-card-head"><div><h3>Delay early warnings</h3><p>Evidence, notice deadlines and programme-review routing only.</p></div></div><form id="siteDelayForm" class="scaffold-grid"><label>Cause<select class="form-select" name="cause"><option>weather</option><option>materials</option><option>labour</option><option>client</option><option>professional</option><option>contractor</option><option>unknown</option></select></label><label>Notice deadline<input class="form-input" type="datetime-local" name="noticeDeadline" required></label><label>Likely impact days<input class="form-input" type="number" min="0" max="3650" name="likelyProgrammeImpactDays" value="0" required></label><label class="trust-wide">Description<textarea class="form-textarea" name="description" required></textarea></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Record an early warning only; no EOT entitlement is granted.</label><button class="btn dark">Record delay warning</button><span role="status"></span></form><div class="trust-list">${w.delayWarnings.map(x=>`<article class="trust-row"><div><b>${siteStatus(x.cause)} delay warning</b><span>${siteStatus(x.status)} · likely ${x.likelyProgrammeImpactDays} days</span><small>grantsEntitlement=false · deadline ${escapeHtml(x.noticeDeadline)}</small></div><div class="trust-row-actions">${x.status==='notice_required'?`<button class="btn ghost" onclick="siteTransitionDelay('${x.id}','under_review')">Review</button>`:''}${x.status==='under_review'?`<button class="btn ghost" onclick="siteTransitionDelay('${x.id}','closed')">Close</button>`:''}<button class="btn ghost" onclick="siteAssessImpact('${x.id}',${x.likelyProgrammeImpactDays})">Assess programme</button></div></article>`).join('')||'<div class="notice">No delay warnings yet.</div>'}</div><div class="trust-card-head"><div><h3>Payment recommendation blockers</h3><p>Finance visibility only; no certificate or money movement is changed.</p></div></div><div class="trust-list">${w.paymentBlockers.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.reason)}</b><span>${siteStatus(x.status)} · ${siteStatus(x.severity)}</span><small>movesMoney=false · ${siteStatus(x.sourceType)}</small></div>${x.status==='active'?`<button class="btn ghost" onclick="siteClearBlocker('${x.id}')">Clear after source closeout</button>`:''}</article>`).join('')||'<div class="notice">No payment blockers.</div>'}</div></section>`;bindSiteExecution();}
  function siteQualityRow(x,type){const label=type==='ncr'?x.title:x.description,source=type==='ncr'?'ncr':'snag';let actions='';if(type==='ncr'&&['open','rejected'].includes(x.status))actions=`<button class="btn ghost" onclick="siteCorrectNcr('${x.id}')">Submit corrective action</button>`;if(type==='ncr'&&x.status==='corrective_action_submitted')actions=`<button class="btn dark" onclick="siteDecideNcr('${x.id}','verified_closed')">Verify close</button><button class="btn ghost" onclick="siteDecideNcr('${x.id}','rejected')">Reject</button>`;if(type==='snag'&&x.status==='open')actions=`<button class="btn ghost" onclick="siteAllocateSnag('${x.id}')">Allocate</button>`;if(type==='snag'&&x.status==='allocated')actions=`<button class="btn ghost" onclick="siteReadySnag('${x.id}')">Ready for reinspection</button>`;if(type==='snag'&&x.status==='ready_for_reinspection')actions=`<button class="btn dark" onclick="siteDecideSnag('${x.id}','closed')">Close</button><button class="btn ghost" onclick="siteDecideSnag('${x.id}','rejected')">Reject</button>`;if(x.blocksPayment&&!['verified_closed','closed'].includes(x.status))actions+=`<button class="btn ghost" onclick="siteCreateBlocker('${source}','${x.id}')">Create blocker</button>`;return `<article class="trust-row"><div><b>${escapeHtml(label)}</b><span>${siteStatus(x.status)} · ${siteStatus(x.severity||x.priority)}</span><small>${escapeHtml(x.responsibleParty||'')} · blocks payment ${x.blocksPayment?'recommended':'no'}</small></div><div class="trust-row-actions">${actions}</div></article>`;}
  function bindSiteExecution(){for(const[id,handler]of[['siteDailyLogForm',createSiteDailyLog],['siteEvidenceForm',createSiteEvidence],['siteRfiForm',createSiteRfi],['siteInstructionForm',createSiteInstruction],['siteNcrForm',createSiteNcr],['siteSnagForm',createSiteSnag],['siteInspectionForm',createSiteInspection],['siteDelayForm',createSiteDelay]])document.getElementById(id)?.addEventListener('submit',handler);const now=new Date(),tomorrow=new Date(Date.now()+86400000);document.querySelector('#siteDailyLogForm [name=logDate]')?.setAttribute('value',localDateInputValue(now));for(const selector of ['#siteRfiForm [name=dueAt]','#siteSnagForm [name=dueAt]','#siteDelayForm [name=noticeDeadline]'])document.querySelector(selector)?.setAttribute('value',localDateTimeInputValue(tomorrow));}
  async function siteSubmit(form,operation){const m=form.querySelector('[role=status]');if(m)m.textContent='Saving…';try{await operation(new FormData(form));if(m)m.textContent='Persisted.';await hydrateSiteExecution();}catch(error){if(m)m.textContent=error.message;else showToast(error.message);}}
  async function createSiteDailyLog(e){e.preventDefault();const f=e.currentTarget;await siteSubmit(f,v=>{const labour={};for(const line of siteLines(v.get('labour'))){const[name,count]=line.split('|').map(x=>x.trim());if(name)labour[name]=Number(count);}return api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/site-diary`,{logDate:v.get('logDate'),weather:v.get('weather'),labour,plant:siteLines(v.get('plant')),deliveries:siteLines(v.get('deliveries')),visitors:siteLines(v.get('visitors')),delays:siteLines(v.get('delays')),safetyNotes:siteLines(v.get('safetyNotes')),humanConfirmed:v.get('humanConfirmed')==='on'});});}
  async function createSiteEvidence(e){e.preventDefault();const f=e.currentTarget;await siteSubmit(f,async v=>{let fileId=null,file=f.elements.file.files[0];if(file){const body=new FormData();body.append('file',file);const response=await fetch(`/api/v1/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/files`,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Organisation-Id':api.organisationId,'X-CSRF-Token':api.csrfToken},body}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Private file upload failed.');fileId=payload.data.id;}const number=name=>v.get(name)===''?null:Number(v.get(name));return api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/site-evidence`,{dailyLogId:v.get('dailyLogId')||null,fileId,evidenceType:v.get('evidenceType'),title:v.get('title'),locationLabel:v.get('locationLabel')||null,latitude:number('latitude'),longitude:number('longitude'),capturedAt:new Date().toISOString(),popiaClassification:v.get('popiaClassification'),humanConfirmed:v.get('humanConfirmed')==='on'});});}
  async function createSiteRfi(e){e.preventDefault();const f=e.currentTarget;await siteSubmit(f,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/rfis`,{subject:v.get('subject'),question:v.get('question'),discipline:v.get('discipline'),linkedDocumentIds:siteLines(v.get('linkedDocumentIds')),dueAt:new Date(v.get('dueAt')).toISOString(),humanConfirmed:v.get('humanConfirmed')==='on'}));}
  async function createSiteInstruction(e){e.preventDefault();const f=e.currentTarget;await siteSubmit(f,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/site-instructions`,{title:v.get('title'),instruction:v.get('instruction'),linkedRfiId:v.get('linkedRfiId')||null,costImpact:v.get('costImpact'),timeImpact:v.get('timeImpact')}));}
  async function createSiteNcr(e){e.preventDefault();const f=e.currentTarget;await siteSubmit(f,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/ncrs`,{title:v.get('title'),description:v.get('description'),severity:v.get('severity'),responsibleParty:v.get('responsibleParty'),evidenceIds:v.getAll('evidenceIds'),blocksPayment:v.get('blocksPayment')==='on',humanConfirmed:v.get('humanConfirmed')==='on'}));}
  async function createSiteSnag(e){e.preventDefault();const f=e.currentTarget;await siteSubmit(f,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/snags`,{location:v.get('location'),description:v.get('description'),priority:v.get('priority'),responsibleParty:v.get('responsibleParty'),dueAt:new Date(v.get('dueAt')).toISOString(),evidenceIds:v.getAll('evidenceIds'),blocksPayment:v.get('blocksPayment')==='on',humanConfirmed:v.get('humanConfirmed')==='on'}));}
  async function createSiteInspection(e){e.preventDefault();const f=e.currentTarget;await siteSubmit(f,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/inspections`,{inspectionType:v.get('inspectionType'),findings:siteLines(v.get('findings')),followUps:siteLines(v.get('followUps')),checklist:siteLines(v.get('checklist')).map(line=>{const[item,outcome]=line.split('|').map(x=>x.trim());return{item,outcome};}),signOffRequired:v.get('signOffRequired')==='on'}));}
  async function createSiteDelay(e){e.preventDefault();const f=e.currentTarget;await siteSubmit(f,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/delay-warnings`,{cause:v.get('cause'),description:v.get('description'),noticeDeadline:new Date(v.get('noticeDeadline')).toISOString(),likelyProgrammeImpactDays:Number(v.get('likelyProgrammeImpactDays')),humanConfirmed:v.get('humanConfirmed')==='on'}));}
  async function siteAction(path,body){try{await api.post(path,body);await hydrateSiteExecution();}catch(error){showToast(error.message);}}
  window.siteMarkRfisOverdue=()=>siteAction(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/rfis/mark-overdue`,{asAt:new Date().toISOString()});
  window.siteRespondRfi=id=>{const answer=prompt('Exact professional response');if(answer)siteAction(`/rfis/${id}/responses`,{answer,requiresInstruction:confirm('Does this response require a formal site instruction?'),humanConfirmed:true});};
  window.siteCloseRfi=id=>siteAction(`/rfis/${id}/close`,{humanConfirmed:true,reason:'Originator confirmed the issued response resolves the exact question.'});
  window.siteIssueInstruction=id=>siteAction(`/site-instructions/${id}/issue`,{humanConfirmed:confirm('Issue this exact formal instruction in your authorised professional capacity?'),reason:'Authorised professional reviewed the exact instruction and linked records.'});
  window.siteAcknowledgeInstruction=id=>siteAction(`/site-instructions/${id}/acknowledge`,{humanConfirmed:true,reason:'Contractor acknowledges receipt only; no entitlement is accepted.'});
  window.siteSupersedeInstruction=id=>{const instruction=prompt('Replacement instruction text');if(instruction)siteAction(`/site-instructions/${id}/supersede`,{title:'Revised site instruction',instruction,costImpact:'possible',timeImpact:'possible',humanConfirmed:true,reason:'Authorised revision supersedes the original without mutation.'});};
  window.siteCorrectNcr=id=>{const action=prompt('Corrective action submitted for verification');if(action)siteAction(`/ncrs/${id}/corrective-actions`,{correctiveAction:action,evidenceIds:[],humanConfirmed:true});};
  window.siteDecideNcr=(id,decision)=>siteAction(`/ncrs/${id}/decisions`,{decision,humanConfirmed:confirm(`Confirm NCR decision: ${decision}?`),reason:'Authorised professional reviewed the corrective action and evidence.'});
  window.siteAllocateSnag=id=>siteAction(`/snags/${id}/allocate`,{humanConfirmed:true});
  window.siteReadySnag=id=>siteAction(`/snags/${id}/ready-for-reinspection`,{evidenceIds:[],humanConfirmed:true});
  window.siteDecideSnag=(id,decision)=>siteAction(`/snags/${id}/decisions`,{decision,humanConfirmed:confirm(`Confirm snag reinspection decision: ${decision}?`),reason:'Authorised professional completed the reinspection.'});
  window.siteIssueInspection=id=>siteAction(`/inspections/${id}/issue`,{professionalSupervisorId:window.__ARCHITEX_SHELL_STATE__.session.userId,humanConfirmed:confirm('Issue this internal inspection under professional supervision?')});
  window.siteCloseInspection=id=>siteAction(`/inspections/${id}/close`,{humanConfirmed:true,reason:'All internal follow-ups reviewed; no statutory approval is represented.'});
  window.siteTransitionDelay=(id,status)=>siteAction(`/delay-warnings/${id}/transitions`,{status,humanConfirmed:true,reason:'Evidence and notice status reviewed; no entitlement decision is made.'});
  window.siteAssessImpact=(id,days)=>siteAction(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/programme-impacts`,{sourceType:'delay_warning',sourceObjectId:id,estimatedDays:Number(days),humanConfirmed:true});
  window.siteCreateBlocker=(sourceType,sourceObjectId)=>siteAction(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/payment-blockers`,{sourceType,sourceObjectId,reason:'Unresolved field-control item requires commercial review.',severity:'high',humanConfirmed:confirm('Create a finance recommendation blocker? This does not move money.')});
  window.siteClearBlocker=id=>siteAction(`/payment-blockers/${id}/clear`,{humanConfirmed:true,reason:'Source field-control item is verified closed.'});
  window.refreshSiteExecution=hydrateSiteExecution;

  let practiceState=null;
  const practiceUserId=()=>window.__ARCHITEX_SHELL_STATE__?.session?.userId||window.__ARCHITEX_SHELL_STATE__?.session?.id||'';
  const practiceCanGovern=()=>['owner','admin'].includes(window.__ARCHITEX_SHELL_STATE__?.session?.memberships?.find(x=>x.organisationId===api.organisationId)?.role);
  function practiceManagementWorkspace(){return `<div id="practiceManagementWorkspace" class="procurement-workspace"><div class="notice"><b>Professional office boundary:</b> Invoice readiness does not create an invoice or move money. Candidate records require separate registered-professional sign-off. Registration reminders are not verification guarantees.</div><div id="practiceManagementBody"><div class="notice">Loading tenant-scoped office records from MariaDB…</div></div></div>`;}
  async function hydratePracticeManagement(){const root=document.getElementById('practiceManagementBody'),p=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root||!p)return;try{practiceState=await api.get(`/projects/${p}/practice-workspace`);renderPracticeManagement();}catch(error){root.innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  const practiceRows=(items,label,detail=x=>siteStatus(x.status||x.stage))=>items.length?items.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.title||x.name||label)}</b><span>${escapeHtml(detail(x))}</span><small>${escapeHtml(x.createdAt||x.workDate||x.expiresOn||'Audited office record')}</small></div></article>`).join(''):`<div class="notice">No ${escapeHtml(label.toLowerCase())} yet.</div>`;
  function renderPracticeManagement(){const root=document.getElementById('practiceManagementBody'),w=practiceState,user=practiceUserId(),canGovern=practiceCanGovern();if(!root||!w)return;root.innerHTML=`
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Project pipeline</h2><p>Forecast values, weighted value and explicit win/loss/abandoned outcomes.</p></div></div><form id="practicePipelineForm" class="scaffold-grid"><label>Opportunity title<input class="form-input" name="title" required value="New project opportunity"></label><label>Stage<select class="form-select" name="stage"><option>lead</option><option selected>qualified</option><option>proposal</option><option>negotiation</option></select></label><label>Probability %<input class="form-input" type="number" name="probabilityPercent" min="0" max="100" value="50" required></label><label>Forecast value (R)<input class="form-input" type="number" name="forecastValue" min="0" step="0.01" value="100000" required></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Confirm the human-entered forecast.</label><button class="btn dark">Add pipeline item</button><span role="status"></span></form><div class="trust-list">${w.pipelineItems.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.title)}</b><span>${siteStatus(x.stage)} · ${x.probabilityPercent}% · weighted ${money(x.weightedValueCents)}</span><small>${escapeHtml(x.createdAt)}</small></div>${!['won','lost','abandoned'].includes(x.stage)?`<div class="trust-actions">${x.stage!=='negotiation'?`<button class="btn ghost" onclick="practiceAdvancePipeline('${x.id}','${x.stage}')">Advance</button>`:''}<button class="btn dark" onclick="practiceTransitionPipeline('${x.id}','won')">Won</button><button class="btn ghost" onclick="practiceTransitionPipeline('${x.id}','lost')">Lost</button><button class="btn ghost" onclick="practiceTransitionPipeline('${x.id}','abandoned')">Abandon</button></div>`:''}</article>`).join('')||'<div class="notice">No pipeline items yet.</div>'}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Tasks and workload</h2><p>Assignees, deadlines, SLA and explicit over-allocation warnings.</p></div></div><form id="practiceTaskForm" class="scaffold-grid"><label>Task<input class="form-input" name="title" required value="Coordinate project deliverable"></label><label>Assigned user ID<input class="form-input" name="assignedUserId" pattern="[a-fA-F0-9]{32}" value="${escapeHtml(user)}" required></label><label>Due<input class="form-input" type="datetime-local" name="dueAt" required></label><label>SLA hours<input class="form-input" type="number" min="1" max="8760" name="slaHours" value="24" required></label><label>Priority<select class="form-select" name="priority"><option>low</option><option selected>medium</option><option>high</option><option>critical</option></select></label><button class="btn dark">Assign task</button><span role="status"></span></form><form id="practiceResourceForm" class="scaffold-grid"><label>User ID<input class="form-input" name="userId" pattern="[a-fA-F0-9]{32}" value="${escapeHtml(user)}" required></label><label>Starts<input class="form-input" type="date" name="startsOn" required></label><label>Ends<input class="form-input" type="date" name="endsOn" required></label><label>Allocated hours<input class="form-input" type="number" min="0" step="0.25" name="allocatedHours" value="40" required></label><label>Capacity hours<input class="form-input" type="number" min="0" step="0.25" name="capacityHours" value="40" required></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Confirm capacity.</label><button class="btn dark">Plan resource</button><span role="status"></span></form><div class="trust-list">${w.tasks.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.title)}</b><span>${siteStatus(x.status)} · ${siteStatus(x.priority)} · due ${escapeHtml(x.dueAt)}</span><small>Assigned ${escapeHtml(x.assignedUserId)}</small></div>${!['completed','cancelled'].includes(x.status)?`<div class="trust-actions">${x.status==='open'?`<button class="btn ghost" onclick="practiceTransitionTask('${x.id}','in_progress')">Start</button>`:''}${x.status==='blocked'?`<button class="btn ghost" onclick="practiceTransitionTask('${x.id}','in_progress')">Resume</button>`:''}${x.status!=='blocked'?`<button class="btn ghost" onclick="practiceTransitionTask('${x.id}','blocked')">Block</button>`:''}<button class="btn dark" onclick="practiceTransitionTask('${x.id}','completed')">Complete</button><button class="btn ghost" onclick="practiceTransitionTask('${x.id}','cancelled')">Cancel</button></div>`:''}</article>`).join('')||'<div class="notice">No tasks yet.</div>'}${practiceRows(w.resourceAllocations,'Resource allocations',x=>`${x.allocatedMinutes/60}h / ${x.capacityMinutes/60}h · ${x.overAllocated?'over allocated':'within capacity'}`)}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Timesheets and invoice readiness</h2><p>Billable/non-billable time remains reviewable and only produces Finance-ready data.</p></div><button class="btn ghost" onclick="practiceAssessInvoice()">Assess invoice readiness</button></div><form id="practiceTimesheetForm" class="scaffold-grid"><label>Workstage<input class="form-input" name="workstage" value="design_development" required></label><label>Work date<input class="form-input" type="date" name="workDate" required></label><label>Minutes<input class="form-input" type="number" min="1" max="1440" name="minutes" value="60" required></label><label class="trust-check"><input type="checkbox" name="billable" checked> Billable</label><label class="trust-wide">Description<textarea class="form-textarea" name="description" required>Project coordination work.</textarea></label><button class="btn dark">Capture time</button><span role="status"></span></form><div class="trust-list">${w.timesheets.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.workstage)}</b><span>${x.minutes} min · ${x.billable?'billable':'non-billable'} · ${siteStatus(x.status)}</span><small>${escapeHtml(x.workDate)} · ${escapeHtml(x.description)}</small></div>${x.status==='draft'?`<button class="btn ghost" onclick="practiceSubmitTime('${x.id}')">Submit</button>`:''}${x.status==='submitted'&&canGovern?`<button class="btn dark" onclick="practiceReviewTime('${x.id}')">Approve</button>`:''}</article>`).join('')||'<div class="notice">No time entries yet.</div>'}${practiceRows(w.invoiceReadiness,'Invoice-readiness checks',x=>`${siteStatus(x.status)} · approved ${x.approvedBillableMinutes} min · movesMoney=false`)}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Candidate supervision</h2><p>The candidate and mentor are explicit; the candidate cannot self-sign.</p></div></div><form id="practiceSupervisionForm" class="scaffold-grid"><label>Candidate user ID<input class="form-input" name="candidateUserId" pattern="[a-fA-F0-9]{32}" required></label><label>Mentor user ID<input class="form-input" name="mentorUserId" pattern="[a-fA-F0-9]{32}" value="${escapeHtml(user)}" required></label><label>Period starts<input class="form-input" type="date" name="periodStart" required></label><label>Period ends<input class="form-input" type="date" name="periodEnd" required></label><label class="trust-wide">Summary<textarea class="form-textarea" name="summary" required></textarea></label><label>Competencies<input class="form-input" name="competencies" placeholder="documentation, coordination" required></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Confirm exact supervision evidence.</label><button class="btn dark">Create review</button><span role="status"></span></form><div class="trust-list">${w.supervisionReviews.map(x=>`<article class="trust-row"><div><b>Candidate supervision review</b><span>${siteStatus(x.status)} · ${escapeHtml(x.periodStart)} to ${escapeHtml(x.periodEnd)}</span><small>Candidate ${escapeHtml(x.candidateUserId)} · mentor ${escapeHtml(x.mentorUserId)}</small></div>${x.status==='review_required'?`<button class="btn dark" onclick="practiceSignOffSupervision('${x.id}')">Professional sign-off</button>`:''}</article>`).join('')||'<div class="notice">No supervision reviews yet.</div>'}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Registration, PI and CPD reminders</h2><p>Members may maintain their own reminder; owners/admins may maintain organisation records. Professional-body verification remains external.</p></div></div><form id="practiceRegistrationForm" class="scaffold-grid"><label>User ID<input class="form-input" name="userId" pattern="[a-fA-F0-9]{32}" value="${escapeHtml(user)}" ${canGovern?'':'readonly'} required></label><label>Professional body<input class="form-input" name="professionalBody" value="SACAP" required></label><label>Registration number<input class="form-input" name="registrationNumber" required></label><label>Expires<input class="form-input" type="date" name="expiresOn" required></label><label>Required CPD<input class="form-input" type="number" min="0" step="0.1" name="requiredCpdPoints" value="25" required></label><label>Recorded CPD<input class="form-input" type="number" min="0" step="0.1" name="recordedCpdPoints" value="0" required></label><label>PI expires<input class="form-input" type="date" name="piExpiresOn"></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Record as reminder, not verification.</label><button class="btn dark">Record reminder</button><span role="status"></span></form><div class="trust-list">${practiceRows(w.registrationRenewals,'Registration reminders',x=>`${siteStatus(x.status)} · ${x.professionalBody} · verificationGuaranteed=false`)}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Practice template library</h2><p>Role-aware, checksum-bound versions; only organisation owners/admins may publish controlled revisions.</p></div></div>${canGovern?`<form id="practiceTemplateForm" class="scaffold-grid"><label>Name<input class="form-input" name="name" autocomplete="off" required></label><label>Category<input class="form-input" name="category" value="report" required></label><label>Allowed roles<input class="form-input" name="allowedRoles" value="owner, admin, member" required></label><label class="trust-wide">Controlled content<textarea class="form-textarea" name="content" required></textarea></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Confirm this exact template version.</label><button class="btn dark">Create template</button><span role="status"></span></form>`:'<div class="notice">Controlled template publishing requires an organisation owner or admin.</div>'}<div class="trust-list">${w.templates.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.name)}</b><span>v${x.version} · ${siteStatus(x.status)} · SHA-256 ${escapeHtml(x.contentSha256.slice(0,12))}…</span><small>${escapeHtml(x.category)} · ${escapeHtml(x.allowedRoles.join(', '))}</small></div>${x.status==='active'&&canGovern?`<button class="btn ghost" onclick="practiceReviseTemplate('${x.id}')">Create revision</button>`:''}</article>`).join('')||'<div class="notice">No templates yet.</div>'}</div></section>`;bindPracticeManagement();}
  function practiceBind(formId,operation){document.getElementById(formId)?.addEventListener('submit',e=>{e.preventDefault();const status=e.currentTarget.querySelector('[role=status]');if(status)status.textContent='Saving…';operation(new FormData(e.currentTarget)).then(()=>hydratePracticeManagement()).catch(error=>{if(status)status.textContent=error.message;});},{once:true});}
  function bindPracticeManagement(){const p=window.__ARCHITEX_SHELL_STATE__.selectedProjectId,now=new Date(),later=new Date(Date.now()+86400000*7);document.querySelector('#practiceTaskForm [name=dueAt]').value=localDateTimeInputValue(later);for(const name of ['workDate','startsOn','periodStart']){const el=document.querySelector(`#practiceManagementWorkspace [name=${name}]`);if(el&&!el.value)el.value=localDateInputValue(now);}for(const name of ['endsOn','periodEnd','expiresOn']){const el=document.querySelector(`#practiceManagementWorkspace [name=${name}]`);if(el&&!el.value)el.value=localDateInputValue(later);}practiceBind('practicePipelineForm',v=>api.post(`/projects/${p}/practice/pipeline`,{title:v.get('title'),stage:v.get('stage'),probabilityPercent:Number(v.get('probabilityPercent')),forecastValueCents:Math.round(Number(v.get('forecastValue'))*100),humanConfirmed:v.get('humanConfirmed')==='on'}));practiceBind('practiceTaskForm',v=>api.post(`/projects/${p}/practice/tasks`,{title:v.get('title'),assignedUserId:v.get('assignedUserId'),dueAt:new Date(v.get('dueAt')).toISOString(),slaHours:Number(v.get('slaHours')),priority:v.get('priority')}));practiceBind('practiceResourceForm',v=>api.post(`/projects/${p}/practice/resource-allocations`,{userId:v.get('userId'),startsOn:v.get('startsOn'),endsOn:v.get('endsOn'),allocatedHours:Number(v.get('allocatedHours')),capacityHours:Number(v.get('capacityHours')),humanConfirmed:v.get('humanConfirmed')==='on'}));practiceBind('practiceTimesheetForm',v=>api.post(`/projects/${p}/practice/timesheets`,{workstage:v.get('workstage'),workDate:v.get('workDate'),minutes:Number(v.get('minutes')),billable:v.get('billable')==='on',description:v.get('description'),taskId:null}));practiceBind('practiceSupervisionForm',v=>api.post(`/projects/${p}/practice/supervision-reviews`,{candidateUserId:v.get('candidateUserId'),mentorUserId:v.get('mentorUserId'),periodStart:v.get('periodStart'),periodEnd:v.get('periodEnd'),summary:v.get('summary'),competencies:String(v.get('competencies')).split(',').map(x=>x.trim()).filter(Boolean),humanConfirmed:v.get('humanConfirmed')==='on'}));practiceBind('practiceRegistrationForm',v=>api.post('/practice/registration-renewals',{userId:v.get('userId'),professionalBody:v.get('professionalBody'),registrationNumber:v.get('registrationNumber'),expiresOn:v.get('expiresOn'),requiredCpdPoints:Number(v.get('requiredCpdPoints')),recordedCpdPoints:Number(v.get('recordedCpdPoints')),piExpiresOn:v.get('piExpiresOn')||null,humanConfirmed:v.get('humanConfirmed')==='on'}));practiceBind('practiceTemplateForm',v=>api.post('/practice/templates',{name:v.get('name'),category:v.get('category'),allowedRoles:String(v.get('allowedRoles')).split(',').map(x=>x.trim()).filter(Boolean),content:v.get('content'),humanConfirmed:v.get('humanConfirmed')==='on'}));}
  async function practiceAction(path,body){try{await api.post(path,body);await hydratePracticeManagement();}catch(error){showToast(error.message);}}
  const practiceReason=message=>{const value=prompt(message);return typeof value==='string'&&value.trim()?value.trim():null;};
  window.practiceAdvancePipeline=(id,current)=>{const next={lead:'qualified',qualified:'proposal',proposal:'negotiation'}[current];if(next)window.practiceTransitionPipeline(id,next);};
  window.practiceTransitionPipeline=(id,stage)=>{const reason=practiceReason(`Reason for moving this opportunity to ${stage}:`);if(reason)practiceAction(`/practice/pipeline/${id}/transitions`,{stage,reason,humanConfirmed:true});};
  window.practiceTransitionTask=(id,status)=>{const reason=practiceReason(`Reason for changing this task to ${status}:`);if(reason)practiceAction(`/practice/tasks/${id}/transitions`,{status,reason,humanConfirmed:true});};
  window.practiceSubmitTime=id=>practiceAction(`/practice/timesheets/${id}/submit`,{humanConfirmed:true});
  window.practiceReviewTime=id=>practiceAction(`/practice/timesheets/${id}/review`,{decision:'approved',reason:'Authorised practice administrator reviewed the submitted time evidence.',humanConfirmed:confirm('Approve this exact submitted time entry?')});
  window.practiceSignOffSupervision=id=>{const reason=practiceReason('Professional sign-off reason:');if(reason)practiceAction(`/practice/supervision-reviews/${id}/sign-off`,{reason,humanConfirmed:true});};
  window.practiceReviseTemplate=id=>{const content=prompt('Enter the complete controlled content for the new immutable revision:');if(typeof content!=='string'||!content.trim())return;const reason=practiceReason('Reason for this template revision:');if(reason)practiceAction(`/practice/templates/${id}/revisions`,{content:content.trim(),reason,humanConfirmed:true});};
  window.practiceAssessInvoice=()=>practiceAction(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/practice/invoice-readiness`,{expensesReady:true,disbursementsReady:true,humanConfirmed:confirm('Assess readiness only? This will not create an invoice or move money.')});
  function renderPracticeContext(){const active=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId),nav=document.getElementById('navigator'),title=document.getElementById('inspectTitle'),sub=document.getElementById('inspectSub'),body=document.getElementById('inspectBody');if(nav)nav.innerHTML=`<div class="nav-head"><div class="kicker">Professional office operations</div><div class="nav-title">Practice Management</div><div class="nav-sub">${escapeHtml(active?.name||'No project selected')}</div></div><div class="back-row" onclick="openProjectSpace()"><span>←</span><span class="nav-label">Back to datum project space</span></div><div class="nav-section"><div class="nav-row active"><span class="nav-icon">${icon('practice',21)}</span><span class="nav-label">Pipeline & workload</span></div><div class="nav-row"><span class="nav-icon">${icon('audit_trail',21)}</span><span class="nav-label">Time & governance</span></div></div>`;if(title)title.textContent='Office governance';if(sub)sub.textContent='Tenant-scoped and auditable';if(body)body.innerHTML='<div class="inspect-note"><b>Human responsibility remains explicit.</b><br>Candidate sign-off, invoice creation, payment movement and professional-body verification are never automated by this workspace.</div><div class="inspect-block"><h4>Connected evidence</h4><p>ProjectRecords<br>Inbox tasks<br>Audit trail<br>Agent recommendations<br>MariaDB persistence</p></div>';}

  let closeoutState=null;
  function closeoutWorkspace(){return `<div id="closeoutWorkspace" class="procurement-workspace"><div class="notice"><b>Controlled completion boundary:</b> No internal record grants municipal occupation approval. No closeout action moves money. Practical completion and handover issue require an authorised professional; retention remains in Finance.</div><div id="closeoutBody"><div class="notice">Loading MariaDB-backed closeout records…</div></div></div>`;}
  function renderCloseoutContext(){const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId),nav=document.getElementById('navigator'),title=document.getElementById('inspectTitle'),sub=document.getElementById('inspectSub'),body=document.getElementById('inspectBody');if(nav)nav.innerHTML=`<div class="nav-head"><div class="kicker">Controlled completion</div><div class="nav-title">Closeout & handover</div><div class="nav-sub">${escapeHtml(project?.name||'Select a project')}</div></div><div class="back-row" onclick="openProjectSpace()"><span>←</span><span class="nav-label">Back to datum project space</span></div><div class="nav-note"><b>External authority:</b><br>Municipal occupation approval is verified evidence, never an Architex decision.</div>`;if(title)title.textContent='Closeout evidence';if(sub)sub.textContent='MariaDB-backed controls';if(body)body.innerHTML='<div class="inspect-note"><b>Human authority required.</b><br>Completion certificates and handover packs require authorised issue.</div><div class="inspect-block"><h4>BOUNDARIES</h4><p>Municipal approval claimed: no<br>Money movement: no<br>Retention release: Finance workflow<br>Tenant/project scope: enforced</p></div>';}
  async function hydrateCloseout(){const root=document.getElementById('closeoutBody'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root||!projectId)return;try{closeoutState=await api.get(`/projects/${projectId}/closeout-workspace`);renderCloseout();}catch(error){root.innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function closeoutRows(items,empty){return items.length?items.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.title||x.status||'Controlled record')}</b><span>${siteStatus(x.status)}</span><small>${(x.blockers||[]).map(siteStatus).join(' · ')||'No recorded blockers'}</small></div></article>`).join(''):`<div class="notice">${empty}</div>`;}
  function renderCloseout(){const root=document.getElementById('closeoutBody'),w=closeoutState;if(!root||!w)return;const currentPack=[...w.handoverPacks].reverse().find(x=>!['issued','superseded'].includes(x.status));root.innerHTML=`
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Practical completion readiness</h2><p>Upstream critical snag/NCR checks and authorised immutable issue.</p></div></div><form id="closeoutPcForm" class="scaffold-grid"><label class="trust-check"><input type="checkbox" name="worksComplete"> Works complete</label><label class="trust-check"><input type="checkbox" name="healthSafetyFile"> H&amp;S file complete</label><label class="trust-check"><input type="checkbox" name="commissioningComplete"> Commissioning complete</label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed this exact readiness evidence.</label><button class="btn dark">Assess practical completion</button><span role="status"></span></form><div class="trust-list">${w.practicalCompletions.map(x=>`<article class="trust-row"><div><b>Practical completion</b><span>${siteStatus(x.status)}</span><small>${(x.blockers||[]).map(siteStatus).join(' · ')||`SHA-256 ${escapeHtml(x.snapshotSha256||'pending issue')}`}</small></div><div class="trust-row-actions">${x.status==='ready_for_issue'?`<button class="btn dark" onclick="closeoutIssuePc('${x.id}')">Issue</button>`:''}${x.status==='issued'?`<button class="btn ghost" onclick="closeoutAcceptPc('${x.id}')">Client accept</button>`:''}</div></article>`).join('')||'<div class="notice">No assessment yet.</div>'}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Digital handover pack</h2><p>Versioned as-built, warranty, O&amp;M, keys/access and compliance evidence.</p></div><button class="btn ghost" type="button" onclick="closeoutCreatePack()">New pack</button></div>${currentPack?`<form id="closeoutDocumentForm" class="scaffold-grid"><label>Category<select class="form-select" name="category">${['as_built','warranty','guarantee','om_manual','keys_access','compliance_certificate','other'].map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Title<input class="form-input" name="title" required></label><label>Version<input class="form-input" name="versionLabel" value="v1" required></label><label>Private file<input class="form-input" type="file" name="file" required></label><button class="btn dark">Index verified document</button><span role="status"></span></form><div class="notice">Pack v${currentPack.version} · ${siteStatus(currentPack.status)} · ${(currentPack.blockers||[]).map(siteStatus).join(', ')||'complete'}</div><div class="trust-actions"><button class="btn ghost" onclick="closeoutRefreshPack('${currentPack.id}')">Recheck completeness</button>${currentPack.status==='ready_for_issue'?`<button class="btn dark" onclick="closeoutIssuePack('${currentPack.id}')">Issue handover pack</button>`:''}</div>`:'<div class="notice">Create a versioned handover pack to index private evidence.</div>'}<div class="trust-list">${w.handoverDocuments.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.title)}</b><span>${siteStatus(x.category)} · ${siteStatus(x.status)}</span><small>${escapeHtml(x.versionLabel)}</small></div></article>`).join('')}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Occupation readiness</h2><p>Internal evidence only; the municipality remains the approval authority.</p></div></div><form id="closeoutOccupationForm" class="scaffold-grid"><label>Municipal certificate evidence<input class="form-input" type="file" name="file" required></label><label class="trust-check"><input type="checkbox" name="municipalCertificateVerified"> Certificate evidence verified</label><label class="trust-check"><input type="checkbox" name="insuranceTransitionConfirmed"> Insurance transition confirmed</label>${['water','electricity','fireSystems'].map(x=>`<label class="trust-check"><input type="checkbox" name="${x}"> ${x.replace(/([A-Z])/g,' $1')}</label>`).join('')}<label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> I reviewed the evidence without claiming municipal approval.</label><button class="btn dark">Assess occupation evidence</button><span role="status"></span></form><div class="trust-list">${closeoutRows(w.occupationReadiness,'No occupation-readiness check yet.')}</div></section>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Final account and defects liability</h2><p>Commercial readiness and retention recommendations only; Finance controls every release.</p></div><button class="btn ghost" onclick="closeoutAssessFinalAccount()">Assess final account</button></div><div class="trust-list">${closeoutRows(w.finalAccounts,'No final-account assessment yet.')}</div><form id="closeoutLiabilityForm" class="scaffold-grid"><label>Issued practical completion<select class="form-select" name="practicalCompletionId" required><option value="">Select record</option>${w.practicalCompletions.filter(x=>['issued','client_accepted'].includes(x.status)).map(x=>`<option value="${x.id}">${siteStatus(x.status)} · ${x.id.slice(0,8)}</option>`).join('')}</select></label><label>Starts<input class="form-input" type="date" name="startsOn" required></label><label>Ends<input class="form-input" type="date" name="endsOn" required></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Confirm exact liability dates.</label><button class="btn dark">Create liability period</button><span role="status"></span></form><div class="trust-list">${w.defectsLiabilityPeriods.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.startsOn)} → ${escapeHtml(x.endsOn)}</b><span>${siteStatus(x.status)}</span><small>retentionReleaseRecommended=${x.retentionReleaseRecommended?'true':'false'}</small></div></article>`).join('')||'<div class="notice">No defects-liability period yet.</div>'}</div></section>`;bindCloseout();}
  async function closeoutSubmit(form,operation){const m=form.querySelector('[role=status]');if(m)m.textContent='Saving…';try{await operation(new FormData(form));await hydrateCloseout();}catch(error){if(m)m.textContent=error.message;else showToast(error.message);}}
  async function closeoutUpload(file){const body=new FormData();body.append('file',file);const response=await fetch(`/api/v1/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/files`,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Organisation-Id':api.organisationId,'X-CSRF-Token':api.csrfToken},body}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Private evidence upload failed.');return payload.data.id;}
  function bindCloseout(){document.getElementById('closeoutPcForm')?.addEventListener('submit',e=>{e.preventDefault();closeoutSubmit(e.currentTarget,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/practical-completions`,{checklist:{worksComplete:v.get('worksComplete')==='on',healthSafetyFile:v.get('healthSafetyFile')==='on',commissioningComplete:v.get('commissioningComplete')==='on'},humanConfirmed:v.get('humanConfirmed')==='on'}));});document.getElementById('closeoutDocumentForm')?.addEventListener('submit',e=>{e.preventDefault();closeoutSubmit(e.currentTarget,async v=>{const fileId=await closeoutUpload(e.currentTarget.elements.file.files[0]);return api.post(`/handover-packs/${[...closeoutState.handoverPacks].reverse().find(x=>!['issued','superseded'].includes(x.status)).id}/documents`,{category:v.get('category'),title:v.get('title'),versionLabel:v.get('versionLabel'),fileId,documentRevisionId:null});});});document.getElementById('closeoutOccupationForm')?.addEventListener('submit',e=>{e.preventDefault();closeoutSubmit(e.currentTarget,async v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/occupation-readiness`,{municipalCertificateFileId:await closeoutUpload(e.currentTarget.elements.file.files[0]),municipalCertificateVerified:v.get('municipalCertificateVerified')==='on',insuranceTransitionConfirmed:v.get('insuranceTransitionConfirmed')==='on',utilitiesChecklist:{water:v.get('water')==='on',electricity:v.get('electricity')==='on',fireSystems:v.get('fireSystems')==='on'},humanConfirmed:v.get('humanConfirmed')==='on'}));});document.getElementById('closeoutLiabilityForm')?.addEventListener('submit',e=>{e.preventDefault();closeoutSubmit(e.currentTarget,v=>api.post(`/projects/${window.__ARCHITEX_SHELL_STATE__.selectedProjectId}/defects-liability-periods`,{practicalCompletionId:v.get('practicalCompletionId'),startsOn:v.get('startsOn'),endsOn:v.get('endsOn'),humanConfirmed:v.get('humanConfirmed')==='on'}));});}
  async function closeoutAction(path,body={}){try{await api.post(path,body);await hydrateCloseout();}catch(error){showToast(error.message);}}
