  const financeRoles=['client','architect','bep','engineer','quantity_surveyor','cpm','contractor','subcontractor','supplier','developer','firm_admin','admin'];
  for(const role of financeRoles){if(typeof roleMap!=='undefined'&&Array.isArray(roleMap[role]))for(const tool of ['payments_escrow','valuations','contract_admin','fm_bridge','market_insights'])if(!roleMap[role].includes(tool))roleMap[role].push(tool);if(typeof V8_ROLE_TOOL_ALLOWLIST!=='undefined'&&Array.isArray(V8_ROLE_TOOL_ALLOWLIST[role]))for(const tool of ['payments_escrow','valuations','contract_admin','fm_bridge','market_insights'])if(!V8_ROLE_TOOL_ALLOWLIST[role].includes(tool))V8_ROLE_TOOL_ALLOWLIST[role].push(tool);}
  let agentOrchestrationState=null;
  function agentHexId(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return[...bytes].map(x=>x.toString(16).padStart(2,'0')).join('');}
  function agentOrchestrationWorkspace(){const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId),govern=practiceCanGovern();if(!project)return '<div class="notice">Select a project before opening Agent Orchestration.</div>';return `${pageHead('Agent Orchestration','Identity-anchored coordination, policy routing, bounded memory and human approval gates.','wingman','lavender')}<div id="agentOrchestrationWorkspace" class="procurement-workspace">
    <div class="notice"><b>Human-governed boundary:</b> Recommendations are advisory. Contextual messages remain unsent drafts until a separate authorised person approves them, and approval still does not dispatch externally. Project agents never override permissions. <code>permissionBypassAllowed=false</code>.</div>
    <section class="trust-layout"><form id="agentBootstrapForm" class="panel panel-pad"><h2>Identity & bounded context</h2><p>Bind your own user context to this project without exposing another user's memory.</p><div class="scaffold-grid"><label>Agent display name<input class="form-input" name="displayName" value="Project Wingman" required></label><label class="trust-wide">Purpose<input class="form-input" name="purpose" value="Coordinate project risks without replacing professional decisions." required></label><label>Allowed memory scopes<input class="form-input" name="memoryScope" value="project_phase, assigned_actions, approved_records" required></label><label>Excluded scopes<input class="form-input" name="memoryExclusions" value="other_users_private_context, other_tenants" required></label><label>Retain until<input class="form-input" type="date" name="retentionUntil" required></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Confirm this user/project memory boundary.</label></div><div class="trust-actions"><button class="btn dark">Save bounded context</button><span role="status"></span></div></form>
    ${govern?`<form id="agentPolicyForm" class="panel panel-pad"><h2>Governance policies</h2><p>System governance is separate from helpful recommendations.</p><div class="scaffold-grid"><label>Policy key<input class="form-input" name="policyKey" value="formal_instruction_review" required></label><label>Title<input class="form-input" name="title" value="Formal instruction review" required></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Confirm permission bypass and external dispatch remain disabled.</label></div><div class="trust-actions"><button class="btn dark">Create policy version</button><span role="status"></span></div></form>`:''}</section>
    <section class="trust-layout">${govern?`<form id="agentRouteForm" class="panel panel-pad"><h2>Workflow event routes</h2><div class="scaffold-grid"><label>Event type<input class="form-input" name="eventType" value="site.blocker_detected" required></label><label>Source module<input class="form-input" name="sourceModule" value="site_execution_field_control" required></label><label>Target role<input class="form-input" name="targetRole" value="owner" required></label><label>Policy<select class="form-select" name="policyId" required></select></label><label class="trust-check"><input type="checkbox" name="createDraft" checked> Create contextual draft</label><label class="trust-check"><input type="checkbox" name="approvalRequired" checked> Human approval required</label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Confirm this exact event route.</label></div><div class="trust-actions"><button class="btn dark">Create governed route</button><span role="status"></span></div></form>`:''}
    <form id="agentEventForm" class="panel panel-pad"><h2>Route a workflow event</h2><p>Create traceable advice from human-recorded facts.</p><div class="scaffold-grid"><label>Event type<input class="form-input" name="eventType" value="site.blocker_detected" required></label><label>Source type<input class="form-input" name="sourceType" value="site_payment_blocker" required></label><label>Source object ID<input class="form-input" name="sourceObjectId" pattern="[a-fA-F0-9]{32}" required></label><label>Severity<select class="form-select" name="severity"><option>low</option><option>medium</option><option selected>high</option><option>critical</option></select></label><label class="trust-wide">Recommendation title<input class="form-input" name="title" value="Review unresolved project blocker" required></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Confirm the source facts and request advisory routing.</label></div><div class="trust-actions"><button class="btn dark">Route event</button><span role="status"></span></div></form></section>
    <section class="trust-layout"><form id="agentDraftForm" class="panel panel-pad"><h2>Contextual message drafts</h2><p>Prepare content beside a source object; this action never sends it.</p><div class="scaffold-grid"><label>Policy<select class="form-select" name="policyId" required></select></label><label>Recipient role<input class="form-input" name="recipientRole" value="owner" required></label><label>Source type<input class="form-input" name="sourceType" value="project_record" required></label><label>Source object ID<input class="form-input" name="sourceObjectId" pattern="[a-fA-F0-9]{32}" required></label><label class="trust-wide">Subject<input class="form-input" name="subject" value="Draft project coordination message" required></label><label class="trust-wide">Draft body<textarea class="form-textarea" name="body" required>Draft only. An authorised human must verify and send this message outside the agent workflow.</textarea></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Confirm this is an unsent formal draft.</label></div><div class="trust-actions"><button class="btn dark">Create unsent draft</button><span role="status"></span></div></form><section class="panel panel-pad"><h2>Human approval gates</h2><div id="agentApprovalList" class="trust-list"></div></section></section>
    <section class="trust-layout"><section class="panel panel-pad"><h2>Advisory recommendations</h2><div id="agentRecommendationList" class="trust-list"></div></section><section class="panel panel-pad"><h2>Memory boundary</h2><div id="agentMemoryList" class="trust-list"></div></section></section>
    <section class="trust-layout"><section class="panel panel-pad"><h2>Agent monitoring</h2><div id="agentMonitoringList" class="trust-list"></div></section><section class="panel panel-pad"><h2>Identity & project context</h2><div id="agentContextList" class="trust-list"></div></section></section>
    <section class="panel panel-pad"><h2>Governance policies & routes</h2><div id="agentGovernanceList" class="trust-list"></div></section><section class="panel panel-pad"><h2>Contextual message draft register</h2><div id="agentDraftList" class="trust-list"></div></section></div>`;}
  function agentCsv(value){return String(value||'').split(',').map(x=>x.trim()).filter(Boolean);}
  function agentRows(items,render,empty){return items.length?items.map(render).join(''):`<div class="notice">${escapeHtml(empty)}</div>`;}
  async function hydrateAgentOrchestration(){const root=document.getElementById('agentOrchestrationWorkspace'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root||!projectId)return;try{agentOrchestrationState=await api.get(`/projects/${projectId}/agent-orchestration-workspace`);renderAgentOrchestration();bindAgentOrchestration(projectId);}catch(error){root.insertAdjacentHTML('afterbegin',`<div class="notice">${escapeHtml(error.message)}</div>`);}}
  function renderAgentOrchestration(){const w=agentOrchestrationState;if(!w)return;const currentUser=window.__ARCHITEX_SHELL_STATE__?.session?.userId,policies=w.policies.filter(x=>x.status==='active'),option='<option value="">Select active policy</option>'+policies.map(x=>`<option value="${x.id}">${escapeHtml(x.title)} · v${Number(x.version)}</option>`).join('');document.querySelectorAll('#agentOrchestrationWorkspace select[name=policyId]').forEach(x=>{const old=x.value;x.innerHTML=option;if(policies.some(p=>p.id===old))x.value=old;});const set=(id,html)=>{const node=document.getElementById(id);if(node)node.innerHTML=html;};set('agentContextList',agentRows([...w.identities,...w.userContexts,...w.projectContexts],x=>`<article class="trust-row"><div><b>${escapeHtml(x.displayName||x.purpose||'Project context')}</b><span>${escapeHtml(x.status)}</span><small>${escapeHtml(x.userId||x.agentIdentityId||'project scoped')}</small></div></article>`,'No identity context yet.'));set('agentGovernanceList',agentRows([...w.policies,...w.routes],x=>`<article class="trust-row"><div><b>${escapeHtml(x.title||x.eventType)}</b><span>${escapeHtml(x.policyKey||x.sourceModule||'governed route')}</span><small>${x.version?'Version '+Number(x.version):'Target '+escapeHtml(x.targetRole||'')}${x.approvalRequired?' · approval required':''}</small></div><span class="status ${x.status==='active'?'green':''}">${escapeHtml(x.status)}</span></article>`,'No policies or routes configured.'));set('agentRecommendationList',agentRows(w.recommendations,x=>`<article class="trust-row"><div><b>${escapeHtml(x.title)}</b><span>${escapeHtml(x.rationale)}</span><small>${escapeHtml(x.sourceType)} · ${escapeHtml(x.sourceObjectId)} · policy ${escapeHtml(x.policyId)}</small></div><span class="status amber">${escapeHtml(x.status)}</span></article>`,'No recommendations routed.'));set('agentDraftList',agentRows(w.messageDrafts,x=>`<article class="trust-row"><div><b>${escapeHtml(x.subject)}</b><span>${escapeHtml(x.body)}</span><small>${escapeHtml(x.recipientRole)} · formal instruction · externalDispatchPerformed=${String(x.externalDispatchPerformed)}</small></div><span class="status ${x.status==='approved_for_human_send'?'green':'amber'}">${escapeHtml(x.status.replaceAll('_',' '))}</span></article>`,'No contextual message drafts.'));set('agentApprovalList',agentRows(w.approvalGates,x=>`<article class="trust-row"><div><b>${escapeHtml(x.objectType.replaceAll('_',' '))}</b><span>${escapeHtml(x.requiredRole)} · ${escapeHtml(x.status)}</span><small>${x.requestedBy===currentUser?'A different authorised user must decide.':'Separate human decision; approval does not send.'}</small></div>${practiceCanGovern()&&x.status==='pending'&&x.requestedBy!==currentUser?`<div class="trust-row-actions"><button class="btn dark" onclick="decideAgentApproval('${x.id}','approved')">Approve draft</button><button class="btn ghost" onclick="decideAgentApproval('${x.id}','rejected')">Reject</button></div>`:''}</article>`,'No approval gates.'));set('agentMemoryList',agentRows(w.memoryBoundaries,x=>`<article class="trust-row"><div><b>${escapeHtml(x.scopeKey.replaceAll('_',' '))}</b><span>Allowed: ${x.allowedScopes.map(escapeHtml).join(', ')}</span><small>Excluded: ${x.excludedScopes.map(escapeHtml).join(', ')} · retain until ${escapeHtml(x.retentionUntil)}</small></div><span class="status green">${escapeHtml(x.status)}</span></article>`,'No bounded user memory configured.'));set('agentMonitoringList',agentRows(w.monitoring,x=>`<article class="trust-row"><div><b>${escapeHtml(x.agentKey)}</b><span>${escapeHtml(x.eventType)} · ${escapeHtml(x.outcome)}</span><small>permission bypass=${String(x.permissionBypass)} · external action=${String(x.externalActionPerformed)}</small></div></article>`,'No monitoring outputs.'));const retention=document.querySelector('#agentBootstrapForm [name=retentionUntil]');if(retention&&!retention.value){const d=new Date();d.setFullYear(d.getFullYear()+5);retention.value=localDateInputValue(d);}document.querySelectorAll('#agentOrchestrationWorkspace [name=sourceObjectId]').forEach(x=>{if(!x.value)x.value=agentHexId();});}
  function agentBindForm(id,callback){const form=document.getElementById(id);if(!form||form.dataset.bound)return;form.dataset.bound='1';form.addEventListener('submit',async event=>{event.preventDefault();const status=form.querySelector('[role=status]');status.textContent='Saving…';try{await callback(new FormData(form));status.textContent='Persisted and audited.';await hydrateAgentOrchestration();}catch(error){status.textContent=error.message;}});}
  function bindAgentOrchestration(projectId){agentBindForm('agentBootstrapForm',v=>api.post(`/projects/${projectId}/agent/bootstrap`,{displayName:v.get('displayName'),purpose:v.get('purpose'),memoryScope:agentCsv(v.get('memoryScope')),memoryExclusions:agentCsv(v.get('memoryExclusions')),retentionUntil:v.get('retentionUntil'),humanConfirmed:v.get('humanConfirmed')==='on'}));agentBindForm('agentPolicyForm',v=>api.post('/agent/policies',{policyKey:v.get('policyKey'),title:v.get('title'),rules:{requireApproval:true,allowPermissionBypass:false,allowExternalDispatch:false},humanConfirmed:v.get('humanConfirmed')==='on'}));agentBindForm('agentRouteForm',v=>api.post(`/projects/${projectId}/agent/routes`,{eventType:v.get('eventType'),sourceModule:v.get('sourceModule'),targetRole:v.get('targetRole'),policyId:v.get('policyId'),createDraft:v.get('createDraft')==='on',approvalRequired:v.get('approvalRequired')==='on',humanConfirmed:v.get('humanConfirmed')==='on'}));agentBindForm('agentEventForm',v=>api.post(`/projects/${projectId}/agent/events/route`,{eventType:v.get('eventType'),sourceType:v.get('sourceType'),sourceObjectId:v.get('sourceObjectId'),title:v.get('title'),facts:{severity:v.get('severity'),humanEntered:true},humanConfirmed:v.get('humanConfirmed')==='on'}));agentBindForm('agentDraftForm',v=>api.post(`/projects/${projectId}/agent/message-drafts`,{policyId:v.get('policyId'),recipientRole:v.get('recipientRole'),sourceType:v.get('sourceType'),sourceObjectId:v.get('sourceObjectId'),subject:v.get('subject'),body:v.get('body'),humanConfirmed:v.get('humanConfirmed')==='on'}));}
  window.decideAgentApproval=async(id,decision)=>{const reason=prompt(`${decision==='approved'?'Approval':'Rejection'} reason:`);if(!reason?.trim())return;try{const result=await api.post(`/agent/approval-gates/${id}/decisions`,{decision,reason:reason.trim(),humanConfirmed:true});showToast(`${result.messageDraft.status.replaceAll('_',' ')}; external dispatch: ${result.messageDraft.externalDispatchPerformed}`);await hydrateAgentOrchestration();}catch(error){showToast(error.message);}};
  function renderAgentInspector(){const title=document.getElementById('inspectTitle'),sub=document.getElementById('inspectSub'),body=document.getElementById('inspectBody');if(title)title.textContent='Agent governance';if(sub)sub.textContent='Advisory, scoped and human approved';if(body)body.innerHTML='<div class="inspect-note"><b>No autonomous authority.</b><br>Wingman cannot bypass RBAC, see another user\'s private context, issue a formal instruction, or dispatch externally.</div><div class="inspect-block"><h4>Connected evidence</h4><p>Governance policy<br>Source object<br>ProjectRecord<br>Inbox approval<br>Audit trail<br>Monitoring record</p></div>';}

  let analyticsReportingState=null,analyticsRefreshTimer=null;
  const analyticsKeys=['schedule_variance_days','cost_to_complete_cents','defect_liability_remaining_days','retention_release_readiness_percent','compliance_gap_count'];
  const analyticsTitle=key=>({schedule_variance_days:'Schedule variance',cost_to_complete_cents:'Cost to complete',defect_liability_remaining_days:'Defect liability remaining',retention_release_readiness_percent:'Retention release readiness',compliance_gap_count:'Compliance gaps'}[key]||key.replaceAll('_',' '));
  function analyticsReportingWorkspace(){const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(x=>x.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId),govern=practiceCanGovern(),today=localDateInputValue(new Date());if(!project)return '<div class="notice">Select a project before opening Analytics & Reporting.</div>';return `${pageHead('Analytics & Reporting','Versioned KPIs, role dashboards, acknowledged alerts, scoped exports and redacted platform health.','market_insights','cobalt')}<div id="analyticsReportingWorkspace" class="procurement-workspace analytics-reporting-workspace">
    <div class="notice"><b>Advisory boundary:</b> Analytics surface information only. <code>advisoryOnly=true</code> and <code>formalApprovalChanged=false</code>. KPI snapshots never replace source records or formal approvals.</div>
    <section class="panel panel-pad"><div class="trust-card-head"><div><h2>Five governed KPIs</h2><p>Immutable formula versions, source record IDs and snapshot checksums.</p></div><button class="btn ghost" type="button" onclick="refreshAnalyticsReporting()">Reload</button></div><div id="analyticsKpiGrid" class="analytics-kpi-grid"><div class="notice">Loading metrics…</div></div></section>
    <section class="trust-layout"><form id="analyticsRefreshForm" class="panel panel-pad"><h2>KPI calculation</h2><div class="scaffold-grid"><label>As-of date<input class="form-input" type="date" name="asOf" value="${today}" required></label><label class="trust-check"><input type="checkbox" name="humanConfirmed" required> Confirm the current source records and calculation date.</label></div><div class="trust-actions">${govern?'<button class="btn ghost" type="button" onclick="installAnalyticsBaseline()">Install baseline formulas</button>':''}<button class="btn dark">Create immutable snapshots</button><span role="status"></span></div></form>
    ${govern?`<form id="analyticsLayoutForm" class="panel panel-pad"><h2>Role dashboard</h2><div class="scaffold-grid"><label>Audience<select class="form-select" name="dashboardRole"><option>admin</option><option>professional</option><option selected>client</option><option>contractor</option></select></label><label>Refresh seconds<input class="form-input" type="number" name="refreshSeconds" min="30" max="3600" value="60" required></label><fieldset class="trust-wide proposal-terms"><legend>Widget layout</legend>${analyticsKeys.map(k=>`<label><input type="checkbox" name="widgetKeys" value="${k}" checked> ${analyticsTitle(k)}</label>`).join('')}</fieldset><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Confirm this role-specific layout version.</label></div><div class="trust-actions"><button class="btn dark">Save layout version</button><span role="status"></span></div></form>`:''}</section>
    <section class="trust-layout">${govern?`<form id="analyticsAlertRuleForm" class="panel panel-pad"><h2>Alert rules</h2><div class="scaffold-grid"><label>Name<input class="form-input" name="name" autocomplete="off" value="Retention release pending" required></label><label>Record type<input class="form-input" name="recordType" value="retention_status" required></label><label>Payload path<input class="form-input" name="payloadPath" value="retentionReleasePending" required></label><label>Operator<select class="form-select" name="operator"><option>equals</option><option>not_equals</option><option>greater_than</option><option>less_than</option><option>contains</option></select></label><label>Comparison JSON<input class="form-input" name="comparisonValue" value="true" required></label><label>Severity<select class="form-select" name="severity"><option>low</option><option>medium</option><option selected>high</option><option>critical</option></select></label><label>Recipient role<input class="form-input" name="recipientRole" value="owner" required></label><label>Throttle minutes<input class="form-input" type="number" name="throttleMinutes" min="1" max="10080" value="60" required></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Confirm this exact project alert rule.</label></div><div class="trust-actions"><button class="btn dark">Register rule</button><button class="btn ghost" type="button" onclick="evaluateAnalyticsAlerts()">Evaluate now</button><span role="status"></span></div></form>`:''}<section class="panel panel-pad"><h2>Alert acknowledgements</h2><p>Alerts create Inbox work and must be acknowledged; they never mutate approval state.</p><div id="analyticsAlertList" class="trust-list"></div></section></section>
    <section class="trust-layout"><section class="panel panel-pad"><h2>Scoped exports</h2><p>Project/tenant/date-scoped CSV or JSON with conservative personal-content redaction.</p><div class="scaffold-grid"><label>Dataset<select class="form-select" id="analyticsExportType"><option value="project_records">ProjectRecords</option><option value="inbox">Inbox events</option><option value="audit">Audit trail</option></select></label><label>From<input class="form-input" type="date" id="analyticsExportFrom" value="${today.slice(0,4)}-01-01"></label><label>To<input class="form-input" type="date" id="analyticsExportTo" value="${today}"></label></div><div class="trust-actions"><button class="btn dark" onclick="downloadAnalyticsExport('csv')">Download CSV</button><button class="btn ghost" onclick="downloadAnalyticsExport('json')">Download JSON</button></div></section>
    <section class="panel panel-pad"><h2>Platform health</h2><p>Latency, error counts and memory-boundary violations; no raw personal content.</p>${govern?`<form id="analyticsObservabilityForm" class="scaffold-grid"><label>Metric<select class="form-select" name="metricType"><option value="latency_ms">Latency ms</option><option value="error_count">Error count</option><option value="memory_boundary_violation">Memory-boundary violation</option></select></label><label>Value<input class="form-input" type="number" step="0.01" name="metricValue" value="0" required></label><label>Operation<input class="form-input" name="operation" value="dashboard.refresh" required></label><label>Retention days<input class="form-input" type="number" min="1" max="365" name="retentionDays" value="30" required></label><label class="trust-check trust-wide"><input type="checkbox" name="humanConfirmed" required> Confirm this aggregate technical metric contains no raw personal content.</label><button class="btn dark">Record metric</button><span role="status"></span></form>`:''}<div id="analyticsHealthList" class="trust-list"></div></section></section>
    <section class="panel panel-pad"><h2>Formula & dashboard register</h2><div id="analyticsGovernanceList" class="trust-list"></div></section></div>`;}
  async function hydrateAnalyticsReporting(){const root=document.getElementById('analyticsReportingWorkspace'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root||!projectId)return;if(analyticsRefreshTimer!==null){clearTimeout(analyticsRefreshTimer);analyticsRefreshTimer=null;}try{analyticsReportingState=await api.get(`/projects/${projectId}/analytics-workspace`);renderAnalyticsReporting();bindAnalyticsReporting(projectId);const seconds=Math.max(30,Number(analyticsReportingState.dashboard?.layout?.refreshSeconds||60));analyticsRefreshTimer=setTimeout(()=>{analyticsRefreshTimer=null;if(document.getElementById('analyticsReportingWorkspace'))hydrateAnalyticsReporting();},seconds*1000);}catch(error){root.insertAdjacentHTML('afterbegin',`<div class="notice">${escapeHtml(error.message)}</div>`);}}
  function renderAnalyticsReporting(){const w=analyticsReportingState;if(!w)return;const set=(id,html)=>{const n=document.getElementById(id);if(n)n.innerHTML=html;};set('analyticsKpiGrid',analyticsKeys.map(key=>{const m=w.latestMetrics.find(x=>x.formulaKey===key);return `<article class="analytics-kpi"><span>${escapeHtml(analyticsTitle(key))}</span><b>${m?Number(m.value).toLocaleString():'—'}</b><small>${m?`${escapeHtml(m.unit)} · formula v${m.formulaVersion} · ${escapeHtml(m.snapshotSha256.slice(0,12))}…`:'Awaiting source-backed calculation'}</small></article>`;}).join(''));set('analyticsAlertList',w.alertEvents.length?w.alertEvents.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.name)}</b><span>${escapeHtml(x.severity)} · ${escapeHtml(x.status)}</span><small>acknowledgement required=${String(x.acknowledgementRequired)} · formalApprovalChanged=false</small></div>${x.status==='open'?`<button class="btn dark" onclick="acknowledgeAnalyticsAlert('${x.id}')">Acknowledge</button>`:''}</article>`).join(''):'<div class="notice">No alert events.</div>');set('analyticsHealthList',w.observability.length?w.observability.map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.metricType.replaceAll('_',' '))}: ${Number(x.metricValue)}</b><span>${escapeHtml(x.moduleKey)} · retained until ${escapeHtml(x.retentionUntil)}</span><small>${escapeHtml(JSON.stringify(x.technicalContext))}</small></div></article>`).join(''):'<div class="notice">No retained platform-health metrics visible for this role.</div>');set('analyticsGovernanceList',[...w.formulas,...w.layouts,...w.alertRules].map(x=>`<article class="trust-row"><div><b>${escapeHtml(x.title||x.name||x.dashboardRole)}</b><span>${escapeHtml(x.formulaKey||x.recordType||'dashboard layout')} ${x.version?'· v'+Number(x.version):''}</span><small>${escapeHtml(x.status)}${x.expression?' · '+escapeHtml(x.expression):''}</small></div></article>`).join('')||'<div class="notice">No analytics governance records.</div>');}
  function analyticsBind(id,handler){const f=document.getElementById(id);if(!f||f.dataset.bound)return;f.dataset.bound='1';f.addEventListener('submit',async e=>{e.preventDefault();const status=f.querySelector('[role=status]');status.textContent='Saving…';try{await handler(new FormData(f));status.textContent='Persisted and audited.';await hydrateAnalyticsReporting();}catch(error){status.textContent=error.message;}});}
  function bindAnalyticsReporting(projectId){analyticsBind('analyticsRefreshForm',v=>api.post(`/projects/${projectId}/analytics/kpis/refresh`,{asOf:v.get('asOf'),humanConfirmed:v.get('humanConfirmed')==='on'}));analyticsBind('analyticsLayoutForm',v=>api.post(`/projects/${projectId}/analytics/dashboard-layouts`,{dashboardRole:v.get('dashboardRole'),widgetKeys:v.getAll('widgetKeys'),refreshSeconds:Number(v.get('refreshSeconds')),humanConfirmed:v.get('humanConfirmed')==='on'}));analyticsBind('analyticsAlertRuleForm',v=>api.post(`/projects/${projectId}/analytics/alert-rules`,{name:v.get('name'),recordType:v.get('recordType'),payloadPath:v.get('payloadPath'),operator:v.get('operator'),comparisonValue:JSON.parse(v.get('comparisonValue')),severity:v.get('severity'),recipientRole:v.get('recipientRole'),throttleMinutes:Number(v.get('throttleMinutes')),humanConfirmed:v.get('humanConfirmed')==='on'}));analyticsBind('analyticsObservabilityForm',v=>api.post('/analytics/observability',{moduleKey:'analytics_reporting',metricType:v.get('metricType'),metricValue:Number(v.get('metricValue')),retentionDays:Number(v.get('retentionDays')),technicalContext:{operation:v.get('operation')},humanConfirmed:v.get('humanConfirmed')==='on'}));}
  window.refreshAnalyticsReporting=hydrateAnalyticsReporting;
  window.installAnalyticsBaseline=async()=>{try{await api.post('/analytics/formulas/baseline',{});showToast('Five baseline formula versions installed.');await hydrateAnalyticsReporting();}catch(error){showToast(error.message);}};
  window.evaluateAnalyticsAlerts=async()=>{const p=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;try{const events=await api.post(`/projects/${p}/analytics/alerts/evaluate`,{humanConfirmed:true});showToast(`${events.length} new throttled alerts created.`);await hydrateAnalyticsReporting();}catch(error){showToast(error.message);}};
  window.acknowledgeAnalyticsAlert=async id=>{const note=prompt('Acknowledgement note:');if(!note?.trim())return;try{const result=await api.post(`/analytics/alerts/${id}/acknowledge`,{humanConfirmed:true,note:note.trim()});showToast(`${result.status}; formal approval changed: ${result.formalApprovalChanged}`);await hydrateAnalyticsReporting();}catch(error){showToast(error.message);}};
  window.downloadAnalyticsExport=async format=>{const p=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId,type=document.getElementById('analyticsExportType').value,from=document.getElementById('analyticsExportFrom').value,to=document.getElementById('analyticsExportTo').value;try{const response=await fetch(`${api.base}/projects/${encodeURIComponent(p)}/analytics/exports/${encodeURIComponent(type)}/${format}?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`,{headers:{'X-Organisation-Id':api.organisationId},credentials:'same-origin'});if(!response.ok)throw new Error('Analytics export failed.');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a'),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/);link.href=url;link.download=match?.[1]||`analytics.${format}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){showToast(error.message);}};
