  const standaloneTools=standaloneToolCatalog.splice(0).map(([id,label,category,roles,tags,shellId,backendId])=>({id,label,category,roles,tags,shellId,backendId:backendId||id,standaloneReady:true,canAssign:!standaloneNonAssignable.has(id),description:`Authenticated ${String(category).replaceAll('_',' ')} workflow for ${String(tags).replaceAll(' ',' · ')}.`}));
